RECORD_REPLACE_SCHEMA_VERSION = 1
REPLACE_LOCK_SCHEMA_VERSION = 1
REPLACE_LOCK_TIMEOUT_SECONDS = 30.0
REPLACE_LOCK_STALE_SECONDS = 120.0
REPLACE_LOCK_FIELDS = frozenset(
    {"schema_version", "owner_pid", "owner_token", "owner_process_start", "owner_host", "created_at_utc"}
)
REPLACE_OWNER_TOKEN_PATTERN = re.compile(r"^[0-9a-f]{32}$")
_FILE_ROLES = (
    "human-note",
    "markdown-note",
    "note-metadata",
    "human-records",
    "markdown-records",
    "work-record-index-audit",
)


class RecordReplaceLockError(CkbError):
    def __init__(self, category: str, message: str):
        super().__init__(f"{category}: {message}")
        self.category = category


def _json_digest(value: Any) -> str:
    payload = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(payload).hexdigest()


def _body_digest(body: str) -> str:
    return hashlib.sha256((body.rstrip() + "\n").encode("utf-8")).hexdigest()


def _token_estimate(text: str) -> int:
    return math.ceil(len(text.encode("utf-8")) / 3)


def _operation_root(output: Path) -> Path:
    return output.resolve() / "workspace-meta/record-replace"


def _journal_evidence(output: Path, manifest_path: Path) -> str:
    return manifest_path.resolve().relative_to(output.resolve()).as_posix()


def _new_replace_lock_record(owner_token: str) -> dict[str, Any]:
    state, identity = _process_start_identity(os.getpid())
    if state != "alive" or not identity:
        raise RecordReplaceLockError(
            "record-replace-lock-owner-identity-unavailable",
            f"current process identity is unavailable for record replacement lock: {os.getpid()}",
        )
    return {
        "schema_version": REPLACE_LOCK_SCHEMA_VERSION,
        "owner_pid": os.getpid(),
        "owner_token": owner_token,
        "owner_process_start": identity,
        "owner_host": socket.gethostname(),
        "created_at_utc": utc_now(),
    }


def _parse_replace_lock(value: bytes) -> tuple[dict[str, Any] | None, str | None]:
    try:
        record = json.loads(value.decode("utf-8-sig"))
    except (UnicodeDecodeError, json.JSONDecodeError):
        return None, "record-replace-lock-record-invalid"
    if not isinstance(record, dict) or set(record) != REPLACE_LOCK_FIELDS:
        return None, "record-replace-lock-record-invalid"
    if record.get("schema_version") != REPLACE_LOCK_SCHEMA_VERSION:
        return None, "record-replace-lock-record-invalid"
    if not isinstance(record.get("owner_pid"), int) or record["owner_pid"] < 1:
        return None, "record-replace-lock-record-invalid"
    if not isinstance(record.get("owner_token"), str) or not REPLACE_OWNER_TOKEN_PATTERN.fullmatch(record["owner_token"]):
        return None, "record-replace-lock-record-invalid"
    for field in ("owner_process_start", "owner_host", "created_at_utc"):
        if not isinstance(record.get(field), str) or not record[field] or len(record[field]) > 128:
            return None, "record-replace-lock-record-invalid"
    return record, None


def _replace_lock_owner_state(record: dict[str, Any]) -> str:
    if record["owner_host"] != socket.gethostname():
        return "record-replace-lock-owner-unverifiable"
    state, identity = _process_start_identity(int(record["owner_pid"]))
    if state == "dead":
        return "record-replace-lock-owner-dead"
    if state != "alive" or not identity:
        return "record-replace-lock-owner-unverifiable"
    if identity != record["owner_process_start"]:
        return "record-replace-lock-owner-pid-reused"
    return "record-replace-lock-owner-live"


def _release_replace_lock(lock: Path, descriptor: int, owner_token: str) -> None:
    category: str | None = None
    try:
        if not _same_owner_lock_file(lock, descriptor):
            category = "record-replace-lock-release-file-replaced"
        else:
            record, invalid = _parse_replace_lock(_owner_descriptor_bytes(descriptor))
            if invalid or record is None or record.get("owner_token") != owner_token:
                category = "record-replace-lock-release-owner-token-drift"
    finally:
        _owner_descriptor_unlock(descriptor)
        os.close(descriptor)
    if category is None:
        try:
            record, invalid = _parse_replace_lock(lock.read_bytes())
        except FileNotFoundError:
            category = "record-replace-lock-release-missing"
        else:
            if invalid or record is None or record.get("owner_token") != owner_token:
                category = "record-replace-lock-release-owner-token-drift"
            else:
                lock.unlink()
    if category:
        raise RecordReplaceLockError(category, f"record replacement lock ownership changed before release: {lock}")


@contextmanager
def _replace_lock(output: Path) -> Iterator[dict[str, Any]]:
    root = _operation_root(output)
    root.mkdir(parents=True, exist_ok=True)
    lock = root / ".lock"
    deadline = time.monotonic() + REPLACE_LOCK_TIMEOUT_SECONDS
    owner_token = uuid.uuid4().hex
    descriptor: int | None = None
    recovered_category: str | None = None
    last_category = "concurrent-record-replace-lock"
    while descriptor is None:
        created = False
        try:
            candidate = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_RDWR, 0o600)
            created = True
            os.write(candidate, b" ")
        except FileExistsError:
            try:
                candidate = os.open(lock, os.O_RDWR)
            except FileNotFoundError:
                continue
        if not _owner_descriptor_lock(candidate):
            os.close(candidate)
            last_category = "concurrent-record-replace-lock"
        elif not _same_owner_lock_file(lock, candidate):
            _owner_descriptor_unlock(candidate)
            os.close(candidate)
            continue
        elif created:
            _write_owner_lock_descriptor(candidate, _new_replace_lock_record(owner_token))
            descriptor = candidate
        else:
            age = max(0.0, time.time() - os.fstat(candidate).st_mtime)
            record, invalid = _parse_replace_lock(_owner_descriptor_bytes(candidate))
            if invalid or record is None:
                last_category = invalid or "record-replace-lock-record-invalid"
                recover = False
            else:
                last_category = _replace_lock_owner_state(record)
                recover = age > REPLACE_LOCK_STALE_SECONDS and last_category in {
                    "record-replace-lock-owner-dead",
                    "record-replace-lock-owner-pid-reused",
                }
                recovered_category = last_category if recover else None
            if recover:
                _write_owner_lock_descriptor(candidate, _new_replace_lock_record(owner_token))
                descriptor = candidate
            else:
                _owner_descriptor_unlock(candidate)
                os.close(candidate)
        if descriptor is None:
            if time.monotonic() >= deadline:
                raise RecordReplaceLockError(last_category, f"record replacement is busy: {lock}")
            time.sleep(0.05)
    body_error = False
    try:
        yield {
            "schema_version": REPLACE_LOCK_SCHEMA_VERSION,
            "owner_pid": os.getpid(),
            "owner_token": owner_token,
            "recovered_category": recovered_category,
            "_descriptor": descriptor,
        }
    except BaseException:
        body_error = True
        raise
    finally:
        try:
            _release_replace_lock(lock, descriptor, owner_token)
        except RecordReplaceLockError:
            if not body_error:
                raise


def _rollback_argv(output: Path, manifest: Path) -> list[str]:
    return [
        str(Path(sys.executable).resolve()),
        str(Path(sys.argv[0]).resolve()),
        "record-rollback",
        "--out",
        str(output.resolve()),
        "--manifest",
        str(manifest.resolve()),
    ]


def _powershell_command(argv: list[str]) -> str:
    escaped = [value.replace("'", "''") for value in argv]
    return "& " + " ".join(f"'{value}'" for value in escaped)


def _new_operation(output: Path, kind: str, title: str) -> tuple[str, Path, Path, dict[str, Any]]:
    operation_id = stable_id("record-replace", str(output.resolve()), kind, title, time.time_ns(), os.getpid())
    directory = _operation_root(output) / operation_id
    directory.mkdir(parents=True, exist_ok=False)
    manifest_path = directory / "manifest.json"
    rollback_argv = _rollback_argv(output, manifest_path)
    manifest = {
        "schema_version": RECORD_REPLACE_SCHEMA_VERSION,
        "operation_id": operation_id,
        "operation": "record-replace",
        "status": "preparing",
        "output": str(output.resolve()),
        "kind": kind,
        "title": title,
        "created_at_utc": utc_now(),
        "rollback_manifest": str(manifest_path.resolve()),
        "rollback_argv": rollback_argv,
        "rollback_command": _powershell_command(rollback_argv),
        "roles": [],
    }
    json_write(manifest_path, manifest)
    return operation_id, directory, manifest_path, manifest


def _read_title(path: Path) -> str:
    try:
        text = path.read_text(encoding="utf-8-sig")
    except UnicodeDecodeError as exc:
        raise CkbError(f"managed knowledge note must be valid UTF-8: {path}: {exc}") from exc
    return text.splitlines()[0].removeprefix("# ").strip() if text else ""


def _locate_existing(output: Path, kind: str, title: str) -> tuple[Path, Path, Path, dict[str, Any]]:
    filename = safe_title(title) + ".md"
    relative = Path(DIRECTORY_BY_KIND[kind]) / filename
    markdown = output / "markdown" / relative
    human = output / "human" / relative
    metadata = output / "workspace-meta/notes" / (safe_title(title) + ".json")
    if not markdown.is_file() or not human.is_file():
        for other_kind, directory in DIRECTORY_BY_KIND.items():
            for root_name in ("markdown", "human"):
                candidate = output / root_name / directory / filename
                if candidate.is_file() and _read_title(candidate) == title:
                    if other_kind != kind:
                        raise CkbError(
                            f"record replace kind mismatch for exact title {title}: existing={other_kind}; requested={kind}"
                        )
        raise CkbError(f"record replace target does not exist for exact kind and title: kind={kind}; title={title}")
    if _read_title(markdown) != title or _read_title(human) != title:
        raise CkbError(f"record replace target title differs from the requested exact title: {title}")
    if markdown.read_bytes() != human.read_bytes():
        raise CkbError(f"record replace baseline human/markdown mirrors differ: {relative.as_posix()}")
    if not metadata.is_file():
        raise CkbError(f"record replace metadata is missing: {metadata}")
    record = json_load(metadata)
    if record.get("title") != title:
        raise CkbError(f"record replace metadata title differs from the requested exact title: {title}")
    if record.get("kind") != kind:
        raise CkbError(
            f"record replace kind mismatch for exact title {title}: existing={record.get('kind')}; requested={kind}"
        )
    return relative, human, markdown, record


def _copy_candidate_note_roots(output: Path, candidate_output: Path) -> None:
    for root_name in ("human", "markdown"):
        source_root = output / root_name
        target_root = candidate_output / root_name
        target_root.mkdir(parents=True, exist_ok=True)
        projection = source_root / "projection.json"
        if projection.is_file():
            shutil.copy2(projection, target_root / "projection.json")
        for directory in NOTE_DIRECTORIES:
            source = source_root / directory
            target = target_root / directory
            if source.is_dir():
                shutil.copytree(source, target)
            else:
                target.mkdir(parents=True, exist_ok=True)
    gaps = output / "workspace-meta/gaps"
    if gaps.is_dir():
        shutil.copytree(gaps, candidate_output / "workspace-meta/gaps")


def _file_state(path: Path) -> dict[str, Any]:
    return {
        "exists": path.is_file(),
        "sha256": sha256_file(path) if path.is_file() else None,
        "size": path.stat().st_size if path.is_file() else 0,
    }


def _stage_file_role(
    output: Path,
    directory: Path,
    role: str,
    relative: Path,
    candidate: Path,
) -> dict[str, Any]:
    target = output / relative
    backup = directory / "backup/files" / relative
    staged = directory / "staging/files" / relative
    if target.is_file():
        backup.parent.mkdir(parents=True, exist_ok=True)
        shutil.copy2(target, backup)
    staged.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(candidate, staged)
    return {
        "name": role,
        "kind": "file",
        "path": relative.as_posix(),
        "baseline": {**_file_state(target), "backup": str(backup.resolve()) if backup.is_file() else None},
        "modified": {**_file_state(staged), "candidate": str(staged.resolve())},
    }


def _agent_snapshot(connection: sqlite3.Connection, title: str) -> dict[str, Any]:
    note = connection.execute(
        "SELECT note_title,tag,note_file,content,token_estimate FROM notes WHERE note_title=?",
        (title,),
    ).fetchall()
    links = connection.execute(
        "SELECT note_title,page_title FROM note_links WHERE note_title=? ORDER BY page_title",
        (title,),
    ).fetchall()
    fts = connection.execute(
        "SELECT note_title,title,content FROM note_fts WHERE note_title=?",
        (title,),
    ).fetchall()
    return {"note": [list(row) for row in note], "links": [list(row) for row in links], "fts": [list(row) for row in fts]}


def _agent_candidate(baseline: dict[str, Any], title: str, text: str, links: list[str]) -> dict[str, Any]:
    if len(baseline.get("note", [])) != 1:
        raise CkbError(f"agent-index.sqlite must contain exactly one work record for title: {title}")
    row = list(baseline["note"][0])
    row[3] = text
    row[4] = _token_estimate(text)
    return {
        "note": [row],
        "links": [[title, value] for value in sorted(set(links))],
        "fts": [[title, title, text]],
    }


def _apply_agent_state(connection: sqlite3.Connection, title: str, state: dict[str, Any]) -> None:
    if len(state.get("note", [])) != 1:
        raise CkbError(f"invalid agent-index candidate for title: {title}")
    cursor = connection.execute(
        "UPDATE notes SET tag=?,note_file=?,content=?,token_estimate=? WHERE note_title=?",
        (state["note"][0][1], state["note"][0][2], state["note"][0][3], state["note"][0][4], title),
    )
    if cursor.rowcount != 1:
        raise CkbError(f"agent-index work record disappeared during replacement: {title}")
    connection.execute("DELETE FROM note_links WHERE note_title=?", (title,))
    connection.execute("DELETE FROM note_fts WHERE note_title=?", (title,))
    connection.executemany("INSERT INTO note_links(note_title,page_title) VALUES(?,?)", state.get("links", []))
    connection.executemany("INSERT INTO note_fts(note_title,title,content) VALUES(?,?,?)", state.get("fts", []))


def _machine_snapshot(connection: sqlite3.Connection, document_id: str) -> dict[str, Any]:
    document = connection.execute(
        "SELECT document_id,kind,title,tag,human_file,source_entity_id,content,token_estimate FROM documents WHERE document_id=?",
        (document_id,),
    ).fetchall()
    sections = connection.execute(
        "SELECT section_id,document_id,ordinal,heading,content,token_estimate,source_path,start_line,end_line "
        "FROM sections WHERE document_id=? ORDER BY ordinal,section_id",
        (document_id,),
    ).fetchall()
    section_ids = [row[0] for row in sections]
    sources: list[list[Any]] = []
    if section_ids:
        placeholders = ",".join("?" for _ in section_ids)
        sources = [
            list(row)
            for row in connection.execute(
                f"SELECT section_id,entity_id FROM section_sources WHERE section_id IN ({placeholders}) ORDER BY section_id,entity_id",
                section_ids,
            )
        ]
    links = connection.execute(
        "SELECT source_document_id,target_document_id,target_title,relation FROM document_links "
        "WHERE source_document_id=? ORDER BY target_title,relation",
        (document_id,),
    ).fetchall()
    fts = connection.execute(
        "SELECT section_id,document_id,heading,content,source_path FROM section_fts "
        "WHERE document_id=? ORDER BY rowid",
        (document_id,),
    ).fetchall()
    return {
        "document": [list(row) for row in document],
        "sections": [list(row) for row in sections],
        "section_sources": sources,
        "links": [list(row) for row in links],
        "fts": [list(row) for row in fts],
    }


def _machine_candidate(baseline: dict[str, Any], text: str, links: list[str]) -> dict[str, Any]:
    if len(baseline.get("document", [])) != 1:
        raise CkbError("machine/knowledge.sqlite must contain exactly one target work record")
    document = list(baseline["document"][0])
    document_id = str(document[0])
    document[6] = text
    document[7] = estimated_tokens(text)
    sections: list[list[Any]] = []
    fts: list[list[Any]] = []
    for ordinal, (heading, content) in enumerate(_markdown_sections(text)):
        section_id = f"{document_id}:{ordinal}"
        sections.append([section_id, document_id, ordinal, heading, content, estimated_tokens(content), None, None, None])
        fts.append([section_id, document_id, heading, content, ""])
    return {
        "document": [document],
        "sections": sections,
        "section_sources": [],
        "links": [[document_id, None, value, "wikilink"] for value in sorted(set(links))],
        "fts": fts,
    }


def _apply_machine_state(connection: sqlite3.Connection, document_id: str, state: dict[str, Any]) -> None:
    if len(state.get("document", [])) != 1:
        raise CkbError(f"invalid machine knowledge candidate for document: {document_id}")
    cursor = connection.execute(
        "UPDATE documents SET kind=?,title=?,tag=?,human_file=?,source_entity_id=?,content=?,token_estimate=? WHERE document_id=?",
        (*state["document"][0][1:], document_id),
    )
    if cursor.rowcount != 1:
        raise CkbError(f"machine work record disappeared during replacement: {document_id}")
    existing_ids = [row[0] for row in connection.execute("SELECT section_id FROM sections WHERE document_id=?", (document_id,))]
    if existing_ids:
        placeholders = ",".join("?" for _ in existing_ids)
        connection.execute(f"DELETE FROM section_sources WHERE section_id IN ({placeholders})", existing_ids)
    connection.execute("DELETE FROM section_fts WHERE document_id=?", (document_id,))
    connection.execute("DELETE FROM sections WHERE document_id=?", (document_id,))
    connection.execute("DELETE FROM document_links WHERE source_document_id=?", (document_id,))
    connection.executemany("INSERT INTO sections VALUES(?,?,?,?,?,?,?,?,?)", state.get("sections", []))
    connection.executemany("INSERT INTO section_sources VALUES(?,?)", state.get("section_sources", []))
    connection.executemany("INSERT INTO document_links VALUES(?,?,?,?)", state.get("links", []))
    connection.executemany("INSERT INTO section_fts VALUES(?,?,?,?,?)", state.get("fts", []))


def _sqlite_integrity(connection: sqlite3.Connection, label: str) -> None:
    integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
    foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
    if integrity != "ok" or foreign_keys:
        raise CkbError(f"{label} candidate integrity failed: integrity={integrity}; foreign_keys={foreign_keys[:10]}")


def _trial_agent(path: Path, title: str, baseline: dict[str, Any], candidate: dict[str, Any]) -> None:
    connection = sqlite3.connect(path, timeout=30)
    try:
        connection.execute("PRAGMA foreign_keys=ON")
        connection.execute("BEGIN IMMEDIATE")
        if _json_digest(_agent_snapshot(connection, title)) != _json_digest(baseline):
            raise CkbError(f"agent-index target drifted before candidate validation: {title}")
        _apply_agent_state(connection, title, candidate)
        _sqlite_integrity(connection, "agent-index.sqlite")
        if _json_digest(_agent_snapshot(connection, title)) != _json_digest(candidate):
            raise CkbError(f"agent-index candidate did not reopen exactly: {title}")
        connection.rollback()
    finally:
        if connection.in_transaction:
            connection.rollback()
        connection.close()


def _trial_machine(path: Path, document_id: str, baseline: dict[str, Any], candidate: dict[str, Any]) -> None:
    connection = sqlite3.connect(path, timeout=30)
    try:
        connection.execute("PRAGMA foreign_keys=ON")
        connection.execute("BEGIN IMMEDIATE")
        if _json_digest(_machine_snapshot(connection, document_id)) != _json_digest(baseline):
            raise CkbError(f"machine knowledge target drifted before candidate validation: {document_id}")
        _apply_machine_state(connection, document_id, candidate)
        _sqlite_integrity(connection, "machine/knowledge.sqlite")
        if _json_digest(_machine_snapshot(connection, document_id)) != _json_digest(candidate):
            raise CkbError(f"machine knowledge candidate did not reopen exactly: {document_id}")
        connection.rollback()
    finally:
        if connection.in_transaction:
            connection.rollback()
        connection.close()


def _current_agent(path: Path, title: str) -> dict[str, Any]:
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        return _agent_snapshot(connection, title)
    finally:
        connection.close()


def _current_machine(path: Path, document_id: str) -> dict[str, Any]:
    connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
    try:
        return _machine_snapshot(connection, document_id)
    finally:
        connection.close()


def _commit_agent(path: Path, title: str, expected: dict[str, Any], state: dict[str, Any]) -> None:
    connection = sqlite3.connect(path, timeout=30)
    try:
        connection.execute("PRAGMA foreign_keys=ON")
        connection.execute("BEGIN IMMEDIATE")
        if _json_digest(_agent_snapshot(connection, title)) != _json_digest(expected):
            raise CkbError(f"agent-index target drifted during promotion: {title}")
        _apply_agent_state(connection, title, state)
        _sqlite_integrity(connection, "agent-index.sqlite")
        if _json_digest(_agent_snapshot(connection, title)) != _json_digest(state):
            raise CkbError(f"agent-index promoted state did not reopen exactly: {title}")
        connection.commit()
    finally:
        if connection.in_transaction:
            connection.rollback()
        connection.close()


def _commit_machine(path: Path, document_id: str, expected: dict[str, Any], state: dict[str, Any]) -> None:
    connection = sqlite3.connect(path, timeout=30)
    try:
        connection.execute("PRAGMA foreign_keys=ON")
        connection.execute("BEGIN IMMEDIATE")
        if _json_digest(_machine_snapshot(connection, document_id)) != _json_digest(expected):
            raise CkbError(f"machine knowledge target drifted during promotion: {document_id}")
        _apply_machine_state(connection, document_id, state)
        _sqlite_integrity(connection, "machine/knowledge.sqlite")
        if _json_digest(_machine_snapshot(connection, document_id)) != _json_digest(state):
            raise CkbError(f"machine knowledge promoted state did not reopen exactly: {document_id}")
        connection.commit()
    finally:
        if connection.in_transaction:
            connection.rollback()
        connection.close()


def _cleanup_new_sqlite_sidecars(path: Path, baseline: dict[str, bool]) -> None:
    for suffix in ("-wal", "-shm", "-journal"):
        sidecar = Path(str(path) + suffix)
        if not baseline.get(suffix, False):
            sidecar.unlink(missing_ok=True)


def _promote_file(output: Path, role: dict[str, Any], expected: str | None) -> None:
    target = output / role["path"]
    current = _file_state(target)
    if current["exists"] != role["baseline"]["exists"] or current["sha256"] != expected:
        raise CkbError(f"record replace file drifted during promotion: {role['path']}")
    candidate = Path(role["modified"]["candidate"])
    target.parent.mkdir(parents=True, exist_ok=True)
    temporary = target.with_name(target.name + ".record-replace.tmp")
    shutil.copy2(candidate, temporary)
    os.replace(temporary, target)
    if sha256_file(target) != role["modified"]["sha256"]:
        raise CkbError(f"record replace promoted file did not reopen exactly: {role['path']}")


def _restore_file(output: Path, role: dict[str, Any]) -> None:
    target = output / role["path"]
    if role["baseline"]["exists"]:
        backup = Path(role["baseline"]["backup"])
        temporary = target.with_name(target.name + ".record-rollback.tmp")
        shutil.copy2(backup, temporary)
        os.replace(temporary, target)
    else:
        target.unlink(missing_ok=True)


def _verify_roles(output: Path, roles: list[dict[str, Any]], state_name: str) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    for role in roles:
        expected = role[state_name]
        if role["kind"] == "file":
            actual = _file_state(output / role["path"])
            if actual["exists"] != expected["exists"] or actual["sha256"] != expected["sha256"]:
                errors.append({"role": role["name"], "expected": expected["sha256"], "actual": actual["sha256"]})
        elif role["name"] == "agent-index-note":
            actual_digest = _json_digest(_current_agent(output / role["path"], role["selector"]))
            if actual_digest != expected["sha256"]:
                errors.append({"role": role["name"], "expected": expected["sha256"], "actual": actual_digest})
        else:
            actual_digest = _json_digest(_current_machine(output / role["path"], role["selector"]))
            if actual_digest != expected["sha256"]:
                errors.append({"role": role["name"], "expected": expected["sha256"], "actual": actual_digest})
    return errors


def _candidate_contract(candidate_output: Path, relative: Path) -> dict[str, Any]:
    human = candidate_output / "human" / relative
    markdown = candidate_output / "markdown" / relative
    records_human = candidate_output / "human/RECORDS.md"
    records_markdown = candidate_output / "markdown/RECORDS.md"
    errors = audit_notes(candidate_output)
    work_records = audit_work_record_index(candidate_output)
    if human.read_bytes() != markdown.read_bytes():
        errors.append({"reason": "candidate-note-mirror-differs", "path": relative.as_posix()})
    if records_human.read_bytes() != records_markdown.read_bytes():
        errors.append({"reason": "candidate-record-index-mirror-differs"})
    if work_records["status"] != "passed":
        errors.extend(work_records["errors"])
    if errors:
        raise CkbError(f"record replace candidate audit failed: {errors[:10]}")
    return {"status": "passed", "note_errors": [], "work_record_index": work_records}


def _prepare_replacement(
    output: Path,
    kind: str,
    title: str,
    body_path: Path,
    selectors: list[str],
    query_record: Path | None,
    directory: Path,
    manifest_path: Path,
    manifest: dict[str, Any],
    fault: str | None,
) -> tuple[dict[str, Any], list[dict[str, Any]], dict[str, Any], dict[str, Any]]:
    body = read_note_body(body_path)
    _markdown_root(output)
    relative, human_target, markdown_target, previous = _locate_existing(output, kind, title)
    explicit_evidence = bool(selectors) or query_record is not None
    if explicit_evidence:
        linked_titles = _resolve_page_titles(output, selectors, query_record)
        if kind != "session" and not linked_titles:
            raise CkbError(f"{kind} notes require at least one linked knowledge page")
        source_links = _source_links_for_titles(output, linked_titles)
        query_value = str(query_record.resolve()) if query_record else None
    else:
        linked_titles = list(previous.get("linked_pages") or [])
        source_links = list(previous.get("source_links") or [])
        query_value = previous.get("query_record")
        if kind != "session" and not linked_titles:
            raise CkbError(f"record replace cannot preserve an empty reviewed evidence set: {title}")
    text = render_note_text(kind, title, body, linked_titles, source_links)
    candidate_output = directory / "candidate-output"
    _copy_candidate_note_roots(output, candidate_output)
    for root_name in ("human", "markdown"):
        target = candidate_output / root_name / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        target.write_text(text, encoding="utf-8", newline="\n")
    refresh_work_record_index(candidate_output)
    if fault == "candidate-mirror-diff":
        with (candidate_output / "human" / relative).open("a", encoding="utf-8", newline="\n") as handle:
            handle.write("候选镜像故障注入。\n")
    candidate_audit = _candidate_contract(candidate_output, relative)
    now = utc_now()
    record_id = previous.get("record_id") or stable_id("work-record", kind, title.casefold(), relative.as_posix())
    replacement = {
        "operation_id": manifest["operation_id"],
        "replaced_at_utc": now,
        "previous_page_sha256": sha256_file(markdown_target),
        "previous_body_sha256": previous.get("body_sha256") or sha256_file(markdown_target),
        "body_sha256": _body_digest(body),
    }
    metadata = {
        **previous,
        "schema_version": max(1, int(previous.get("schema_version", 1))),
        "status": "agent-reviewed",
        "record_id": record_id,
        "kind": kind,
        "title": title,
        "file": str(human_target.resolve()),
        "compatibility_file": str(markdown_target.resolve()),
        "linked_pages": linked_titles,
        "source_links": source_links,
        "query_record": query_value,
        "created_at_utc": previous.get("created_at_utc") or previous.get("updated_at_utc") or now,
        "updated_at_utc": now,
        "body_sha256": _body_digest(body),
        "replacement": replacement,
        "obsidian_uri": obsidian_open_uri(markdown_target),
    }
    metadata_candidate = candidate_output / "workspace-meta/notes" / (safe_title(title) + ".json")
    json_write(metadata_candidate, metadata)
    role_sources = (
        ("human-note", Path("human") / relative, candidate_output / "human" / relative),
        ("markdown-note", Path("markdown") / relative, candidate_output / "markdown" / relative),
        ("note-metadata", Path("workspace-meta/notes") / (safe_title(title) + ".json"), metadata_candidate),
        ("human-records", Path("human/RECORDS.md"), candidate_output / "human/RECORDS.md"),
        ("markdown-records", Path("markdown/RECORDS.md"), candidate_output / "markdown/RECORDS.md"),
        (
            "work-record-index-audit",
            Path("workspace-meta/work-record-index-audit.json"),
            candidate_output / "workspace-meta/work-record-index-audit.json",
        ),
    )
    roles = [_stage_file_role(output, directory, role, relative_path, candidate) for role, relative_path, candidate in role_sources]
    agent_path = output / "agent-index.sqlite"
    machine_path = output / "machine/knowledge.sqlite"
    if not agent_path.is_file() or not machine_path.is_file():
        raise CkbError("record replace requires both agent-index.sqlite and machine/knowledge.sqlite")
    agent_connection = sqlite3.connect(f"file:{agent_path.as_posix()}?mode=ro", uri=True)
    try:
        agent_baseline = _agent_snapshot(agent_connection, title)
    finally:
        agent_connection.close()
    agent_candidate = _agent_candidate(agent_baseline, title, text, linked_titles)
    machine_connection = sqlite3.connect(f"file:{machine_path.as_posix()}?mode=ro", uri=True)
    try:
        rows = machine_connection.execute("SELECT document_id FROM documents WHERE title=? AND kind=?", (title, kind)).fetchall()
        if len(rows) != 1:
            raise CkbError(f"machine knowledge must contain one exact kind/title record: kind={kind}; title={title}")
        document_id = str(rows[0][0])
        machine_baseline = _machine_snapshot(machine_connection, document_id)
    finally:
        machine_connection.close()
    machine_candidate = _machine_candidate(machine_baseline, text, linked_titles)
    for folder, name, value in (
        ("backup", "agent-index-note.json", agent_baseline),
        ("staging", "agent-index-note.json", agent_candidate),
        ("backup", "machine-knowledge-note.json", machine_baseline),
        ("staging", "machine-knowledge-note.json", machine_candidate),
    ):
        json_write(directory / folder / name, value)
    roles.extend(
        [
            {
                "name": "agent-index-note",
                "kind": "sqlite-logical",
                "path": "agent-index.sqlite",
                "selector": title,
                "baseline": {
                    "sha256": _json_digest(agent_baseline),
                    "backup": str((directory / "backup/agent-index-note.json").resolve()),
                },
                "modified": {
                    "sha256": _json_digest(agent_candidate),
                    "candidate": str((directory / "staging/agent-index-note.json").resolve()),
                },
            },
            {
                "name": "machine-knowledge-note",
                "kind": "sqlite-logical",
                "path": "machine/knowledge.sqlite",
                "selector": document_id,
                "baseline": {
                    "sha256": _json_digest(machine_baseline),
                    "backup": str((directory / "backup/machine-knowledge-note.json").resolve()),
                },
                "modified": {
                    "sha256": _json_digest(machine_candidate),
                    "candidate": str((directory / "staging/machine-knowledge-note.json").resolve()),
                },
            },
        ]
    )
    _trial_agent(agent_path, title, agent_baseline, agent_candidate)
    _trial_machine(machine_path, document_id, machine_baseline, machine_candidate)
    manifest.update(
        {
            "status": "prepared",
            "prepared_at_utc": utc_now(),
            "record_id": record_id,
            "relative_note": relative.as_posix(),
            "explicit_evidence_replacement": explicit_evidence,
            "linked_pages": linked_titles,
            "body_sha256": _body_digest(body),
            "candidate_audit": candidate_audit,
            "roles": roles,
            "promotion_order": [role["name"] for role in roles],
        }
    )
    json_write(manifest_path, manifest)
    shutil.rmtree(candidate_output)
    return metadata, roles, agent_candidate, machine_candidate


def _restore_promoted(
    output: Path,
    roles: list[dict[str, Any]],
    promoted: list[str],
    agent_baseline: dict[str, Any],
    machine_baseline: dict[str, Any],
) -> None:
    by_name = {role["name"]: role for role in roles}
    for name in reversed(promoted):
        role = by_name[name]
        if role["kind"] == "file":
            _restore_file(output, role)
        elif name == "agent-index-note":
            current = _current_agent(output / role["path"], role["selector"])
            _commit_agent(output / role["path"], role["selector"], current, agent_baseline)
        else:
            current = _current_machine(output / role["path"], role["selector"])
            _commit_machine(output / role["path"], role["selector"], current, machine_baseline)


def _promotion(
    output: Path,
    manifest_path: Path,
    manifest: dict[str, Any],
    roles: list[dict[str, Any]],
    fault: str | None,
) -> dict[str, Any]:
    by_name = {role["name"]: role for role in roles}
    agent_role = by_name["agent-index-note"]
    machine_role = by_name["machine-knowledge-note"]
    agent_baseline = json_load(Path(agent_role["baseline"]["backup"]))
    agent_candidate = json_load(Path(agent_role["modified"]["candidate"]))
    machine_baseline = json_load(Path(machine_role["baseline"]["backup"]))
    machine_candidate = json_load(Path(machine_role["modified"]["candidate"]))
    sidecars = {
        role["name"]: {
            suffix: Path(str(output / role["path"]) + suffix).exists() for suffix in ("-wal", "-shm", "-journal")
        }
        for role in (agent_role, machine_role)
    }
    promoted: list[str] = []
    manifest["status"] = "promoting"
    json_write(manifest_path, manifest)
    try:
        for role in roles:
            if role["kind"] == "file":
                _promote_file(output, role, role["baseline"]["sha256"])
            elif role["name"] == "agent-index-note":
                _commit_agent(output / role["path"], role["selector"], agent_baseline, agent_candidate)
            else:
                _commit_machine(output / role["path"], role["selector"], machine_baseline, machine_candidate)
            promoted.append(role["name"])
            if fault == f"after-{role['name']}":
                raise CkbError(f"injected record replace promotion failure after {role['name']}")
        verification_errors = _verify_roles(output, roles, "modified")
        note_errors = audit_notes(output)
        record_audit = audit_work_record_index(output)
        agent_audit = audit_agent_index(output)
        if verification_errors or note_errors or record_audit["status"] != "passed" or agent_audit["status"] != "passed":
            raise CkbError(
                "record replace post-promotion verification failed: "
                f"roles={verification_errors[:5]}; notes={note_errors[:5]}; records={record_audit['errors'][:5]}; "
                f"agent={agent_audit['errors'][:5]}"
            )
        manifest.update(
            {
                "status": "completed",
                "completed_at_utc": utc_now(),
                "verification": {
                    "status": "passed",
                    "role_errors": [],
                    "note_errors": [],
                    "work_record_index": record_audit,
                    "agent_index": agent_audit,
                },
            }
        )
        json_write(manifest_path, manifest)
        journal = record_operation(output, "record", "record:replace", "replaced", [_journal_evidence(output, manifest_path)])
        manifest["operation_journal"] = journal
        json_write(manifest_path, manifest)
        return journal
    except Exception:
        _restore_promoted(output, roles, promoted, agent_baseline, machine_baseline)
        restored_errors = _verify_roles(output, roles, "baseline")
        manifest.update(
            {
                "status": "failed-restored" if not restored_errors else "failed-restore-incomplete",
                "failed_at_utc": utc_now(),
                "promoted_before_failure": promoted,
                "restore_errors": restored_errors,
            }
        )
        json_write(manifest_path, manifest)
        if restored_errors:
            raise CkbError(f"record replace failed and baseline restoration was incomplete: {restored_errors[:10]}")
        raise
    finally:
        _cleanup_new_sqlite_sidecars(output / agent_role["path"], sidecars[agent_role["name"]])
        _cleanup_new_sqlite_sidecars(output / machine_role["path"], sidecars[machine_role["name"]])


def replace_note(
    output: Path,
    kind: str,
    title: str,
    body_path: Path,
    selectors: list[str] | None = None,
    query_record: Path | None = None,
    *,
    fault: str | None = None,
) -> dict[str, Any]:
    """Replace one exact managed record and publish every dependent role atomically."""

    output = output.resolve()
    normalized_title = title.strip()
    if kind not in TAG_BY_KIND:
        raise CkbError(f"note kind must be one of: {sorted(TAG_BY_KIND)}")
    if not normalized_title:
        raise CkbError("record replace title must not be empty")
    with _replace_lock(output):
        _operation_id, directory, manifest_path, manifest = _new_operation(output, kind, normalized_title)
        try:
            metadata, roles, _agent_candidate_state, _machine_candidate_state = _prepare_replacement(
                output,
                kind,
                normalized_title,
                body_path.resolve(),
                list(selectors or []),
                query_record.resolve() if query_record else None,
                directory,
                manifest_path,
                manifest,
                fault,
            )
            journal = _promotion(output, manifest_path, manifest, roles, fault)
            return {
                **metadata,
                "status": "replaced",
                "operation_id": manifest["operation_id"],
                "manifest": str(manifest_path.resolve()),
                "rollback_manifest": str(manifest_path.resolve()),
                "rollback_command": manifest["rollback_command"],
                "rollback_argv": manifest["rollback_argv"],
                "changed_roles": [role["name"] for role in roles] + ["operation-journal"],
                "before_page_sha256": manifest["roles"][0]["baseline"]["sha256"],
                "after_page_sha256": manifest["roles"][0]["modified"]["sha256"],
                "operation_journal": journal,
                "operation_journal_recorded": True,
            }
        except Exception as exc:
            current = json_load(manifest_path) if manifest_path.is_file() else manifest
            if not str(current.get("status", "")).startswith("failed"):
                current["status"] = "failed"
            current["error"] = {"type": type(exc).__name__, "message": str(exc)}
            current["failed_at_utc"] = current.get("failed_at_utc") or utc_now()
            json_write(manifest_path, current)
            try:
                record_operation(output, "record", "record:replace", "failed", [_journal_evidence(output, manifest_path)])
            except CkbError:
                pass
            if isinstance(exc, CkbError):
                raise
            raise CkbError(f"record replace failed: {exc}") from exc


def _load_rollback_manifest(output: Path, manifest_path: Path) -> dict[str, Any]:
    manifest_path = manifest_path.resolve()
    root = _operation_root(output)
    try:
        manifest_path.relative_to(root)
    except ValueError as exc:
        raise CkbError(f"record rollback manifest must be inside this OUTPUT: {manifest_path}") from exc
    if not manifest_path.is_file():
        raise CkbError(f"record rollback manifest is missing: {manifest_path}")
    manifest = json_load(manifest_path)
    if manifest.get("schema_version") != RECORD_REPLACE_SCHEMA_VERSION or manifest.get("operation") != "record-replace":
        raise CkbError(f"unsupported record rollback manifest: {manifest_path}")
    if Path(str(manifest.get("output") or "")).resolve() != output.resolve():
        raise CkbError(f"record rollback manifest OUTPUT differs from the requested OUTPUT: {manifest_path}")
    if manifest.get("status") not in {"completed", "rolled-back"}:
        raise CkbError(f"record rollback requires a completed replacement: status={manifest.get('status')}")
    return manifest


def rollback_replacement(output: Path, manifest_path: Path) -> dict[str, Any]:
    """Restore the exact file and SQLite logical state owned by one replacement."""

    output = output.resolve()
    manifest_path = manifest_path.resolve()
    with _replace_lock(output):
        manifest = _load_rollback_manifest(output, manifest_path)
        roles = list(manifest.get("roles") or [])
        if {role.get("name") for role in roles} != set(_FILE_ROLES) | {"agent-index-note", "machine-knowledge-note"}:
            raise CkbError("record rollback manifest role set is incomplete")
        baseline_errors = _verify_roles(output, roles, "baseline")
        if manifest["status"] == "rolled-back":
            if baseline_errors:
                raise CkbError(f"record rollback baseline drifted after the prior rollback: {baseline_errors[:10]}")
            journal = record_operation(output, "record", "record:rollback", "rolled-back", [_journal_evidence(output, manifest_path)])
            return {
                "schema_version": RECORD_REPLACE_SCHEMA_VERSION,
                "status": "rolled-back",
                "idempotent": True,
                "operation_id": manifest["operation_id"],
                "manifest": str(manifest_path),
                "restored_roles": [role["name"] for role in roles],
                "operation_journal": journal,
                "operation_journal_recorded": True,
            }
        modified_errors = _verify_roles(output, roles, "modified")
        if modified_errors:
            if not baseline_errors:
                manifest["status"] = "rolled-back"
                manifest["rolled_back_at_utc"] = manifest.get("rolled_back_at_utc") or utc_now()
                json_write(manifest_path, manifest)
                journal = record_operation(output, "record", "record:rollback", "rolled-back", [_journal_evidence(output, manifest_path)])
                return {
                    "schema_version": RECORD_REPLACE_SCHEMA_VERSION,
                    "status": "rolled-back",
                    "idempotent": True,
                    "operation_id": manifest["operation_id"],
                    "manifest": str(manifest_path),
                    "restored_roles": [role["name"] for role in roles],
                    "operation_journal": journal,
                    "operation_journal_recorded": True,
                }
            try:
                record_operation(output, "record", "record:rollback", "conflict", [_journal_evidence(output, manifest_path)])
            except CkbError:
                pass
            raise CkbError(f"record rollback conflict: replacement-owned objects drifted: {modified_errors[:10]}")
        by_name = {role["name"]: role for role in roles}
        restored: list[str] = []
        try:
            for role in reversed(roles):
                if role["kind"] == "file":
                    _restore_file(output, role)
                elif role["name"] == "agent-index-note":
                    _commit_agent(
                        output / role["path"],
                        role["selector"],
                        json_load(Path(role["modified"]["candidate"])),
                        json_load(Path(role["baseline"]["backup"])),
                    )
                else:
                    _commit_machine(
                        output / role["path"],
                        role["selector"],
                        json_load(Path(role["modified"]["candidate"])),
                        json_load(Path(role["baseline"]["backup"])),
                    )
                restored.append(role["name"])
            errors = _verify_roles(output, roles, "baseline")
            note_errors = audit_notes(output)
            records = audit_work_record_index(output)
            agent = audit_agent_index(output)
            if errors or note_errors or records["status"] != "passed" or agent["status"] != "passed":
                raise CkbError(
                    f"record rollback verification failed: roles={errors[:5]}; notes={note_errors[:5]}; "
                    f"records={records['errors'][:5]}; agent={agent['errors'][:5]}"
                )
        except Exception as exc:
            compensation_errors: list[dict[str, Any]] = []
            for name in reversed(restored):
                role = by_name[name]
                try:
                    if role["kind"] == "file":
                        _promote_file(output, role, role["baseline"]["sha256"])
                    elif role["name"] == "agent-index-note":
                        _commit_agent(
                            output / role["path"],
                            role["selector"],
                            json_load(Path(role["baseline"]["backup"])),
                            json_load(Path(role["modified"]["candidate"])),
                        )
                    else:
                        _commit_machine(
                            output / role["path"],
                            role["selector"],
                            json_load(Path(role["baseline"]["backup"])),
                            json_load(Path(role["modified"]["candidate"])),
                        )
                except Exception as compensation_exc:
                    compensation_errors.append(
                        {"role": name, "type": type(compensation_exc).__name__, "message": str(compensation_exc)}
                    )
            manifest["rollback_failure"] = {
                "type": type(exc).__name__,
                "message": str(exc),
                "restored_before_failure": restored,
                "compensation_errors": compensation_errors,
            }
            json_write(manifest_path, manifest)
            try:
                record_operation(output, "record", "record:rollback", "failed", [_journal_evidence(output, manifest_path)])
            except CkbError:
                pass
            if isinstance(exc, CkbError):
                raise
            raise CkbError(f"record rollback failed: {exc}") from exc
        manifest.update(
            {
                "status": "rolled-back",
                "rolled_back_at_utc": utc_now(),
                "rollback_verification": {
                    "status": "passed",
                    "role_errors": [],
                    "note_errors": [],
                    "work_record_index": records,
                    "agent_index": agent,
                },
            }
        )
        json_write(manifest_path, manifest)
        journal = record_operation(output, "record", "record:rollback", "rolled-back", [_journal_evidence(output, manifest_path)])
        manifest["rollback_operation_journal"] = journal
        json_write(manifest_path, manifest)
        return {
            "schema_version": RECORD_REPLACE_SCHEMA_VERSION,
            "status": "rolled-back",
            "idempotent": False,
            "operation_id": manifest["operation_id"],
            "manifest": str(manifest_path),
            "restored_roles": [role["name"] for role in roles],
            "operation_journal": journal,
            "operation_journal_recorded": True,
        }

"""Page-level native PDF extraction with an optional bounded OCR adapter."""

from __future__ import annotations

import importlib
import json
import logging
import os
from pathlib import Path
import re
import subprocess
import sys
import time
from typing import Any

from .common import CkbError, DependencyError, background_process_options, json_load, json_write, path_inside, sha256_file, stable_id, utc_now


PDF_EXTRACTION_SCHEMA_VERSION = 1
PDF_PARSER_NAME = "pypdf"
PDF_PARSER_VERSION = "6.16.2"
DEFAULT_MAX_PDF_BYTES = 32 * 1024 * 1024
DEFAULT_MAX_PDF_PAGES = 400
ABSOLUTE_MAX_PDF_BYTES = 256 * 1024 * 1024
ABSOLUTE_MAX_PDF_PAGES = 2000
DEFAULT_NATIVE_MIN_CHARACTERS = 12
DEFAULT_NATIVE_MIN_PRINTABLE_RATIO = 0.90
DEFAULT_OCR_MAX_PAGES = 12
DEFAULT_OCR_TIMEOUT_SECONDS = 30
DEFAULT_OCR_MAX_INPUT_BYTES = 16 * 1024 * 1024
ABSOLUTE_OCR_MAX_PAGES = 100
ABSOLUTE_OCR_TIMEOUT_SECONDS = 300
ABSOLUTE_OCR_MAX_INPUT_BYTES = 256 * 1024 * 1024
MAX_PAGE_TEXT_CHARACTERS = 2 * 1024 * 1024
MAX_DOCUMENT_TEXT_CHARACTERS = 16 * 1024 * 1024
MAX_OCR_OUTPUT_BYTES = 8 * 1024 * 1024
OCR_ADAPTER_SCHEMA_VERSION = 1


class PdfExtractionError(CkbError):
    """A deterministic PDF validation or extraction failure."""


def _load_pypdf():
    """Load the locked parser, permitting an isolated test/runtime staging path."""

    extra = os.environ.get("CKB_PDF_LIBRARY_PATH", "").strip()
    if extra:
        resolved = Path(extra).resolve()
        if not resolved.is_dir():
            raise DependencyError(f"CKB_PDF_LIBRARY_PATH is not a directory: {resolved}")
        value = str(resolved)
        if value not in sys.path:
            sys.path.insert(0, value)
    try:
        module = importlib.import_module(PDF_PARSER_NAME)
    except ModuleNotFoundError as exc:
        raise DependencyError(
            f"native PDF extraction requires locked {PDF_PARSER_NAME} {PDF_PARSER_VERSION}"
        ) from exc
    version = str(getattr(module, "__version__", ""))
    if version != PDF_PARSER_VERSION:
        raise DependencyError(
            f"native PDF extraction requires {PDF_PARSER_NAME} {PDF_PARSER_VERSION}; found {version or 'unknown'}"
        )
    return module


def _validate_positive_limit(name: str, value: int, absolute: int) -> int:
    if not isinstance(value, int) or value < 1 or value > absolute:
        raise CkbError(f"{name} must be within 1..{absolute}")
    return value


def validate_pdf_limits(max_bytes: int, max_pages: int) -> tuple[int, int]:
    return (
        _validate_positive_limit("PDF max bytes", max_bytes, ABSOLUTE_MAX_PDF_BYTES),
        _validate_positive_limit("PDF max pages", max_pages, ABSOLUTE_MAX_PDF_PAGES),
    )


def validate_ocr_limits(max_pages: int, timeout_seconds: int, max_input_bytes: int) -> tuple[int, int, int]:
    return (
        _validate_positive_limit("OCR max pages", max_pages, ABSOLUTE_OCR_MAX_PAGES),
        _validate_positive_limit("OCR timeout seconds", timeout_seconds, ABSOLUTE_OCR_TIMEOUT_SECONDS),
        _validate_positive_limit("OCR max input bytes", max_input_bytes, ABSOLUTE_OCR_MAX_INPUT_BYTES),
    )


def _normalized_layout_text(value: str) -> str:
    value = value.replace("\r\n", "\n").replace("\r", "\n").replace("\x00", "")
    lines = [line.rstrip() for line in value.split("\n")]
    while lines and not lines[0].strip():
        lines.pop(0)
    while lines and not lines[-1].strip():
        lines.pop()
    return "\n".join(lines)


def _text_metrics(text: str) -> dict[str, Any]:
    nonspace = [character for character in text if not character.isspace()]
    printable = [character for character in nonspace if character.isprintable()]
    replacement = text.count("\ufffd")
    ratio = len(printable) / len(nonspace) if nonspace else 0.0
    return {
        "character_count": len(text),
        "nonspace_character_count": len(nonspace),
        "printable_ratio": round(ratio, 6),
        "replacement_character_count": replacement,
    }


def _usable_text(metrics: dict[str, Any], min_characters: int, min_printable_ratio: float) -> bool:
    return (
        int(metrics["nonspace_character_count"]) >= min_characters
        and float(metrics["printable_ratio"]) >= min_printable_ratio
        and int(metrics["replacement_character_count"]) <= max(1, int(metrics["nonspace_character_count"]) // 100)
    )


def _native_confidence(metrics: dict[str, Any]) -> str:
    if int(metrics["nonspace_character_count"]) >= 80 and float(metrics["printable_ratio"]) >= 0.99:
        return "high"
    return "medium"


_HEADING = re.compile(r"^(?:#{1,6}\s+|(?:\d+(?:\.\d+){0,4}|[A-Z])(?:[.)]|\s+-)\s*)?[^\n]{1,100}$")
_NUMBERED_HEADING = re.compile(r"^(?:\d+(?:\.\d+){1,4}|(?:chapter|section)\s+\d+)\s+\S", re.IGNORECASE)
_LIST_LINE = re.compile(r"^\s*(?:[-*+\u2022\u25cf\u25aa]|\d+[.)]|[A-Za-z][.)])\s+\S")
_CODE_SIGNAL = re.compile(r"(?:[{};]|\b(?:def|class|return|if|for|while|public|private|const|let|var|import|from)\b)")


def _classify_block(lines: list[str]) -> tuple[str, str, list[str]]:
    nonblank = [line for line in lines if line.strip()]
    warnings: list[str] = []
    if not nonblank:
        return "raw", "low", ["empty-block"]
    if all(_LIST_LINE.match(line) for line in nonblank):
        return "list", "high", warnings
    pipe_columns = [line.count("|") for line in nonblank]
    gap_columns = [len(re.findall(r"\S\s{2,}\S", line)) for line in nonblank]
    if len(nonblank) >= 2 and (min(pipe_columns) >= 2 or min(gap_columns) >= 1):
        return "table", "medium", ["layout-derived-table-boundary"]
    indented = sum(1 for line in nonblank if len(line) - len(line.lstrip(" ")) >= 4)
    signals = sum(1 for line in nonblank if _CODE_SIGNAL.search(line))
    if len(nonblank) >= 2 and (indented >= max(1, len(nonblank) // 2) or signals >= 2):
        return "code", "medium", ["layout-derived-code-boundary"]
    if len(nonblank) == 1:
        line = nonblank[0].strip()
        if line.startswith("#") or _NUMBERED_HEADING.match(line):
            return "heading", "high", warnings
        if _HEADING.match(line) and (line.isupper() or not re.search(r"[.!?。！？]$", line)):
            return "heading", "low", ["heading-inferred-from-short-line"]
    if all(len(line.strip()) >= 2 for line in nonblank):
        return "paragraph", "medium", warnings
    return "raw", "low", ["structure-not-reliably-classified"]


def segment_page_text(
    reference_id: str,
    page_number: int,
    method: str,
    confidence: str,
    text: str,
    source_file: str | None = None,
) -> list[dict[str, Any]]:
    """Split page text without rewriting its non-blank lines."""

    # Blank lines are the only hard boundaries.  The classifier never rewrites
    # non-blank lines, so indentation and column spacing remain evidence.
    blocks: list[tuple[int, int, str]] = []
    start: int | None = None
    offset = 0
    for line in text.splitlines(keepends=True):
        content_end = offset + len(line.rstrip("\r\n"))
        if line.strip():
            if start is None:
                start = offset
        elif start is not None:
            blocks.append((start, content_end - len(line.rstrip("\r\n")), text[start:offset].rstrip("\n")))
            start = None
        offset += len(line)
    if start is not None:
        blocks.append((start, len(text), text[start:].rstrip("\n")))
    if not blocks and text:
        blocks = [(0, len(text), text)]
    fragments: list[dict[str, Any]] = []
    for ordinal, (begin, _end, block) in enumerate(blocks, start=1):
        end = begin + len(block)
        if not block.strip():
            continue
        structure, structure_confidence, warnings = _classify_block(block.split("\n"))
        fragments.append(
            {
                "fragment_id": stable_id("reference-fragment", reference_id, page_number, ordinal, begin, end, block),
                "source_id": reference_id,
                "source_file": source_file,
                "page_number": page_number,
                "method": method,
                "confidence": confidence,
                "structure": structure,
                "structure_confidence": structure_confidence,
                "text_range": {"start": begin, "end": end, "unit": "unicode-codepoint", "end_exclusive": True},
                "text": block,
                "warnings": warnings,
            }
        )
    return fragments


def _resolve_ocr_adapter(adapter: Path | None) -> tuple[Path | None, dict[str, Any]]:
    if adapter is None:
        return None, {"status": "missing", "reason": "ocr-adapter-not-configured"}
    resolved = adapter.resolve()
    if not resolved.is_file() or resolved.suffix.casefold() != ".py":
        return None, {"status": "missing", "reason": "ocr-adapter-not-usable", "path": str(resolved)}
    return resolved, {"status": "ready", "path": str(resolved), "sha256": sha256_file(resolved)}


def _run_ocr_page(
    adapter: Path,
    source: Path,
    page_number: int,
    output_path: Path,
    timeout_seconds: int,
    cancel_file: Path | None,
) -> tuple[dict[str, Any] | None, dict[str, Any]]:
    command = [
        sys.executable,
        str(adapter),
        "--source",
        str(source),
        "--page",
        str(page_number),
        "--output",
        str(output_path),
        "--schema-version",
        str(OCR_ADAPTER_SCHEMA_VERSION),
    ]
    if cancel_file is not None:
        command.extend(["--cancel-file", str(cancel_file)])
    started = time.monotonic()
    process = subprocess.Popen(
        command,
        text=True,
        encoding="utf-8",
        errors="replace",
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        **background_process_options(),
    )
    deadline = started + timeout_seconds
    while process.poll() is None:
        if cancel_file is not None and cancel_file.exists():
            process.terminate()
            try:
                stdout, stderr = process.communicate(timeout=5)
            except subprocess.TimeoutExpired:
                process.kill()
                stdout, stderr = process.communicate()
            return None, {
                "status": "pending",
                "reason": "ocr-cancelled",
                "exit_status": process.returncode,
                "stderr": stderr.strip()[:1000],
                "elapsed_seconds": round(time.monotonic() - started, 3),
            }
        if time.monotonic() >= deadline:
            process.kill()
            _stdout, stderr = process.communicate()
            return None, {
                "status": "pending",
                "reason": "ocr-timeout",
                "exit_status": process.returncode,
                "stderr": stderr.strip()[:1000],
                "elapsed_seconds": round(time.monotonic() - started, 3),
            }
        time.sleep(0.05)
    stdout, stderr = process.communicate()
    completed = subprocess.CompletedProcess(command, process.returncode, stdout, stderr)
    elapsed = round(time.monotonic() - started, 3)
    if completed.returncode != 0:
        return None, {
            "status": "pending",
            "reason": "ocr-adapter-failed",
            "exit_status": completed.returncode,
            "stderr": completed.stderr.strip()[:1000],
            "elapsed_seconds": elapsed,
        }
    if not output_path.is_file():
        return None, {"status": "pending", "reason": "ocr-output-missing", "elapsed_seconds": elapsed}
    if output_path.stat().st_size > MAX_OCR_OUTPUT_BYTES:
        return None, {"status": "pending", "reason": "ocr-output-size-limit", "elapsed_seconds": elapsed}
    try:
        result = json_load(output_path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return None, {"status": "pending", "reason": "ocr-output-invalid-json", "detail": str(exc), "elapsed_seconds": elapsed}
    if (
        result.get("schema_version") != OCR_ADAPTER_SCHEMA_VERSION
        or result.get("status") != "extracted"
        or result.get("page_number") != page_number
        or not isinstance(result.get("text"), str)
    ):
        return None, {"status": "pending", "reason": "ocr-output-contract", "elapsed_seconds": elapsed}
    score = result.get("confidence")
    if not isinstance(score, (int, float)) or isinstance(score, bool) or not 0.0 <= float(score) <= 1.0:
        return None, {"status": "pending", "reason": "ocr-confidence-invalid", "elapsed_seconds": elapsed}
    return result, {"status": "completed", "elapsed_seconds": elapsed, "confidence_score": round(float(score), 6)}


def inspect_pdf(source: Path, max_bytes: int, max_pages: int):
    """Open a PDF before any managed files are created."""

    max_bytes, max_pages = validate_pdf_limits(max_bytes, max_pages)
    size = source.stat().st_size
    if size < 5 or size > max_bytes:
        raise PdfExtractionError(f"PDF source must contain 5..{max_bytes} bytes")
    with source.open("rb") as stream:
        header = stream.read(5)
    if header != b"%PDF-":
        raise PdfExtractionError("PDF source does not start with a PDF header")
    pypdf = _load_pypdf()
    parser_logger = logging.getLogger("pypdf")
    previous_level = parser_logger.level
    try:
        parser_logger.setLevel(logging.CRITICAL + 1)
        reader = pypdf.PdfReader(str(source), strict=False)
        if reader.is_encrypted:
            raise PdfExtractionError("encrypted PDF sources require decryption before reference ingest")
        page_count = len(reader.pages)
    except PdfExtractionError:
        raise
    except Exception as exc:
        name = type(exc).__name__
        raise PdfExtractionError(f"corrupt or unsupported PDF source ({name}): {exc}") from exc
    finally:
        parser_logger.setLevel(previous_level)
    if page_count < 1:
        raise PdfExtractionError("PDF source contains no pages")
    if page_count > max_pages:
        raise PdfExtractionError(f"PDF page count {page_count} exceeds limit {max_pages}")
    return pypdf, reader, page_count


def extract_pdf(
    source: Path,
    reference_id: str,
    extraction_root: Path,
    *,
    max_bytes: int = DEFAULT_MAX_PDF_BYTES,
    max_pages: int = DEFAULT_MAX_PDF_PAGES,
    native_min_characters: int = DEFAULT_NATIVE_MIN_CHARACTERS,
    native_min_printable_ratio: float = DEFAULT_NATIVE_MIN_PRINTABLE_RATIO,
    ocr_enabled: bool = False,
    ocr_adapter: Path | None = None,
    ocr_max_pages: int = DEFAULT_OCR_MAX_PAGES,
    ocr_timeout_seconds: int = DEFAULT_OCR_TIMEOUT_SECONDS,
    ocr_max_input_bytes: int = DEFAULT_OCR_MAX_INPUT_BYTES,
    ocr_cancel_file: Path | None = None,
) -> dict[str, Any]:
    """Extract page text and write relocatable evidence beneath one managed root."""

    if native_min_characters < 1 or native_min_characters > 10000:
        raise CkbError("native minimum characters must be within 1..10000")
    if not 0.5 <= native_min_printable_ratio <= 1.0:
        raise CkbError("native minimum printable ratio must be within 0.5..1.0")
    ocr_max_pages, ocr_timeout_seconds, ocr_max_input_bytes = validate_ocr_limits(
        ocr_max_pages,
        ocr_timeout_seconds,
        ocr_max_input_bytes,
    )
    _pypdf, reader, page_count = inspect_pdf(source, max_bytes, max_pages)
    extraction_root = extraction_root.resolve()
    extraction_root.mkdir(parents=True, exist_ok=False)
    pages_root = extraction_root / "pages"
    ocr_root = extraction_root / "ocr"
    pages_root.mkdir()
    if ocr_enabled:
        ocr_root.mkdir()
    adapter, adapter_status = _resolve_ocr_adapter(ocr_adapter) if ocr_enabled else (
        None,
        {"status": "disabled", "reason": "ocr-not-enabled"},
    )
    cancel_file = ocr_cancel_file.resolve() if ocr_cancel_file is not None else None
    pages: list[dict[str, Any]] = []
    missing_pages: list[int] = []
    ocr_attempts = 0
    total_characters = 0
    for page_number, page in enumerate(reader.pages, start=1):
        try:
            native_text = page.extract_text(
                extraction_mode="layout",
                layout_mode_space_vertically=True,
                layout_mode_scale_weight=1.0,
                layout_mode_strip_rotated=False,
            ) or ""
        except Exception as exc:
            native_text = ""
            native_error = {"type": type(exc).__name__, "detail": str(exc)[:1000]}
        else:
            native_error = None
        native_text = _normalized_layout_text(native_text)
        native_metrics = _text_metrics(native_text)
        native_usable = _usable_text(native_metrics, native_min_characters, native_min_printable_ratio)
        selected_text = native_text
        method = "native"
        confidence = _native_confidence(native_metrics) if native_usable else "low"
        status = "extracted" if native_usable else "pending"
        reason = None if native_usable else "native-text-below-usable-threshold"
        ocr_record: dict[str, Any] = {"status": "not-needed" if native_usable else adapter_status["status"]}
        if not native_usable and ocr_enabled:
            if cancel_file is not None and cancel_file.exists():
                ocr_record = {"status": "pending", "reason": "ocr-cancelled"}
                reason = "ocr-cancelled"
            elif source.stat().st_size > ocr_max_input_bytes:
                ocr_record = {"status": "pending", "reason": "ocr-input-size-limit"}
                reason = "ocr-input-size-limit"
            elif adapter is None:
                ocr_record = dict(adapter_status)
                reason = str(adapter_status["reason"])
            elif ocr_attempts >= ocr_max_pages:
                ocr_record = {"status": "pending", "reason": "ocr-page-limit"}
                reason = "ocr-page-limit"
            else:
                ocr_attempts += 1
                adapter_output = ocr_root / f"page-{page_number:04d}.json"
                result, execution = _run_ocr_page(
                    adapter,
                    source,
                    page_number,
                    adapter_output,
                    ocr_timeout_seconds,
                    cancel_file,
                )
                ocr_record = execution
                if result is not None:
                    candidate = _normalized_layout_text(result["text"])
                    metrics = _text_metrics(candidate)
                    score = float(result["confidence"])
                    usable = _usable_text(metrics, native_min_characters, native_min_printable_ratio) and score >= 0.75
                    selected_text = candidate
                    method = "ocr"
                    confidence = "high" if score >= 0.90 else "medium" if usable else "low"
                    status = "extracted" if usable else "pending"
                    reason = None if usable else "ocr-text-below-usable-threshold"
                    ocr_record.update({"text_metrics": metrics, "accepted": usable})
                else:
                    reason = str(execution["reason"])
        if len(selected_text) > MAX_PAGE_TEXT_CHARACTERS:
            raise PdfExtractionError(
                f"PDF page {page_number} extracted text exceeds {MAX_PAGE_TEXT_CHARACTERS} characters"
            )
        total_characters += len(selected_text)
        if total_characters > MAX_DOCUMENT_TEXT_CHARACTERS:
            raise PdfExtractionError(
                f"PDF extracted text exceeds {MAX_DOCUMENT_TEXT_CHARACTERS} characters"
            )
        page_text_path = pages_root / f"page-{page_number:04d}.txt"
        page_text_path.write_text(selected_text, encoding="utf-8", newline="\n")
        page_record = {
            "page_number": page_number,
            "status": status,
            "method": method,
            "confidence": confidence,
            "reason": reason,
            "source_id": reference_id,
            "source_file": str(source.resolve()),
            "text_file": str(page_text_path.resolve()),
            "text_relative": page_text_path.relative_to(extraction_root.parent.parent).as_posix(),
            "text_sha256": sha256_file(page_text_path),
            "text_length": len(selected_text),
            "native_metrics": native_metrics,
            "native_error": native_error,
            "ocr": ocr_record,
            "fragments": segment_page_text(
                reference_id,
                page_number,
                method,
                confidence,
                selected_text,
                str(source.resolve()),
            ),
        }
        if status != "extracted":
            missing_pages.append(page_number)
        pages.append(page_record)
    result = {
        "schema_version": PDF_EXTRACTION_SCHEMA_VERSION,
        "reference_id": reference_id,
        "status": "ready" if not missing_pages else "pending",
        "source_file": str(source.resolve()),
        "source_sha256": sha256_file(source),
        "parser": {"name": PDF_PARSER_NAME, "version": PDF_PARSER_VERSION, "mode": "layout"},
        "page_count": page_count,
        "extracted_page_count": page_count - len(missing_pages),
        "pending_pages": missing_pages,
        "limits": {
            "max_pdf_bytes": max_bytes,
            "max_pdf_pages": max_pages,
            "max_page_text_characters": MAX_PAGE_TEXT_CHARACTERS,
            "max_document_text_characters": MAX_DOCUMENT_TEXT_CHARACTERS,
            "native_min_characters": native_min_characters,
            "native_min_printable_ratio": native_min_printable_ratio,
        },
        "ocr": {
            "enabled": ocr_enabled,
            "adapter": adapter_status,
            "max_pages": ocr_max_pages,
            "attempted_pages": ocr_attempts,
            "timeout_seconds_per_page": ocr_timeout_seconds,
            "max_input_bytes": ocr_max_input_bytes,
            "max_output_bytes_per_page": MAX_OCR_OUTPUT_BYTES,
            "cancel_file": str(cancel_file) if cancel_file is not None else None,
        },
        "pages": pages,
        "created_at_utc": utc_now(),
    }
    extraction_manifest = extraction_root / "manifest.json"
    json_write(extraction_manifest, result)
    result["manifest"] = str(extraction_manifest.resolve())
    result["manifest_sha256"] = sha256_file(extraction_manifest)
    return result


def validate_pdf_extraction(
    output: Path,
    manifest: dict[str, Any],
    *,
    require_ready: bool = False,
) -> tuple[dict[str, Any] | None, list[dict[str, Any]]]:
    """Reopen page evidence and report all extraction/provenance drift."""

    errors: list[dict[str, Any]] = []
    reference_id = str(manifest.get("reference_id") or "")
    extraction_value = manifest.get("extraction_file")
    if not isinstance(extraction_value, str) or not extraction_value:
        return None, [{"reason": "reference-pdf-extraction-missing", "reference_id": reference_id}]
    extraction_path = Path(extraction_value)
    expected_root = (output / "references" / "extractions" / reference_id).resolve()
    if not path_inside(extraction_path, expected_root) or extraction_path.resolve() != expected_root / "manifest.json":
        return None, [{"reason": "reference-pdf-extraction-path", "reference_id": reference_id, "path": str(extraction_path)}]
    if not extraction_path.is_file():
        return None, [{"reason": "reference-pdf-extraction-missing", "reference_id": reference_id}]
    if sha256_file(extraction_path) != manifest.get("extraction_sha256"):
        errors.append({"reason": "reference-pdf-extraction-drift", "reference_id": reference_id})
    try:
        extraction = json_load(extraction_path)
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        return None, [{"reason": "reference-pdf-extraction-invalid", "reference_id": reference_id, "detail": str(exc)}]
    if extraction.get("schema_version") != PDF_EXTRACTION_SCHEMA_VERSION or extraction.get("reference_id") != reference_id:
        errors.append({"reason": "reference-pdf-extraction-contract", "reference_id": reference_id})
    if extraction.get("source_sha256") != manifest.get("source_sha256"):
        errors.append({"reason": "reference-pdf-source-binding", "reference_id": reference_id})
    if Path(str(extraction.get("source_file") or "")).resolve() != Path(str(manifest.get("source_file") or "")).resolve():
        errors.append({"reason": "reference-pdf-source-path-binding", "reference_id": reference_id})
    parser = extraction.get("parser") if isinstance(extraction.get("parser"), dict) else {}
    if parser.get("name") != PDF_PARSER_NAME or parser.get("version") != PDF_PARSER_VERSION or parser.get("mode") != "layout":
        errors.append({"reason": "reference-pdf-parser-contract", "reference_id": reference_id})
    pages = extraction.get("pages")
    declared_page_count = extraction.get("page_count")
    if (
        not isinstance(pages, list)
        or not isinstance(declared_page_count, int)
        or isinstance(declared_page_count, bool)
        or len(pages) != declared_page_count
    ):
        errors.append({"reason": "reference-pdf-page-count", "reference_id": reference_id})
        pages = pages if isinstance(pages, list) else []
    expected_numbers = list(range(1, len(pages) + 1))
    actual_numbers = [page.get("page_number") for page in pages if isinstance(page, dict)]
    if actual_numbers != expected_numbers:
        errors.append({"reason": "reference-pdf-page-sequence", "reference_id": reference_id, "pages": actual_numbers})
    if manifest.get("page_count") != extraction.get("page_count"):
        errors.append({"reason": "reference-pdf-manifest-page-count", "reference_id": reference_id})
    fragment_ids: set[str] = set()
    expected_page_files: set[Path] = set()
    for page in pages:
        if not isinstance(page, dict):
            continue
        page_number = page.get("page_number")
        page_contract = (
            page.get("source_id") == reference_id
            and page.get("status") in {"extracted", "pending"}
            and page.get("method") in {"native", "ocr"}
            and page.get("confidence") in {"high", "medium", "low"}
            and isinstance(page.get("native_metrics"), dict)
            and isinstance(page.get("ocr"), dict)
            and (
                (page.get("status") == "extracted" and page.get("confidence") in {"high", "medium"} and page.get("reason") is None)
                or (page.get("status") == "pending" and page.get("confidence") == "low" and isinstance(page.get("reason"), str))
            )
        )
        if not page_contract:
            errors.append({"reason": "reference-pdf-page-contract", "reference_id": reference_id, "page_number": page_number})
        path = Path(str(page.get("text_file") or ""))
        expected_page_files.add(path.resolve())
        if not path_inside(path, expected_root / "pages"):
            errors.append({"reason": "reference-pdf-page-path", "reference_id": reference_id, "page_number": page_number})
            continue
        expected_relative = path.resolve().relative_to((output / "references").resolve()).as_posix()
        if page.get("text_relative") != expected_relative:
            errors.append({"reason": "reference-pdf-page-relative-path", "reference_id": reference_id, "page_number": page_number})
        if Path(str(page.get("source_file") or "")).resolve() != Path(str(manifest.get("source_file") or "")).resolve():
            errors.append({"reason": "reference-pdf-page-source-binding", "reference_id": reference_id, "page_number": page_number})
        if not path.is_file() or sha256_file(path) != page.get("text_sha256"):
            errors.append({"reason": "reference-pdf-page-drift", "reference_id": reference_id, "page_number": page_number})
            continue
        text = path.read_text(encoding="utf-8")
        if len(text) != page.get("text_length"):
            errors.append({"reason": "reference-pdf-page-length", "reference_id": reference_id, "page_number": page_number})
        fragments = page.get("fragments")
        if not isinstance(fragments, list):
            errors.append({"reason": "reference-pdf-fragments", "reference_id": reference_id, "page_number": page_number})
            continue
        ranges: list[tuple[int, int]] = []
        for fragment in fragments:
            if not isinstance(fragment, dict):
                errors.append({"reason": "reference-pdf-fragment-contract", "reference_id": reference_id, "page_number": page_number})
                continue
            fragment_id = str(fragment.get("fragment_id") or "")
            text_range = fragment.get("text_range") if isinstance(fragment.get("text_range"), dict) else {}
            start, end = text_range.get("start"), text_range.get("end")
            method_matches = fragment.get("method") == page.get("method") and fragment.get("method") in {"native", "ocr"}
            confidence_matches = (
                fragment.get("confidence") == page.get("confidence")
                and fragment.get("confidence") in {"high", "medium", "low"}
            )
            valid = (
                fragment.get("source_id") == reference_id
                and Path(str(fragment.get("source_file") or "")).resolve() == Path(str(manifest.get("source_file") or "")).resolve()
                and fragment.get("page_number") == page_number
                and method_matches
                and confidence_matches
                and fragment.get("structure") in {"heading", "paragraph", "list", "code", "table", "raw"}
                and fragment.get("structure_confidence") in {"high", "medium", "low"}
                and isinstance(fragment.get("warnings"), list)
                and isinstance(start, int)
                and isinstance(end, int)
                and 0 <= start < end <= len(text)
                and text[start:end] == fragment.get("text")
                and fragment_id
                and fragment_id not in fragment_ids
            )
            if not valid:
                errors.append({"reason": "reference-pdf-fragment-contract", "reference_id": reference_id, "page_number": page_number, "fragment_id": fragment_id})
            else:
                fragment_ids.add(fragment_id)
                ranges.append((start, end))
        if ranges != sorted(ranges) or any(left[1] > right[0] for left, right in zip(ranges, ranges[1:])):
            errors.append({"reason": "reference-pdf-fragment-overlap", "reference_id": reference_id, "page_number": page_number})
        if page.get("status") == "extracted" and (not text.strip() or not fragments):
            errors.append({"reason": "reference-pdf-empty-extracted-page", "reference_id": reference_id, "page_number": page_number})
    pages_directory = expected_root / "pages"
    actual_page_files = {path.resolve() for path in pages_directory.glob("page-*.txt")} if pages_directory.is_dir() else set()
    if actual_page_files != expected_page_files:
        errors.append(
            {
                "reason": "reference-pdf-page-file-set",
                "reference_id": reference_id,
                "missing": sorted(str(path) for path in expected_page_files - actual_page_files),
                "extra": sorted(str(path) for path in actual_page_files - expected_page_files),
            }
        )
    pending_pages = [page.get("page_number") for page in pages if isinstance(page, dict) and page.get("status") != "extracted"]
    if pending_pages != extraction.get("pending_pages"):
        errors.append({"reason": "reference-pdf-pending-page-set", "reference_id": reference_id})
    expected_status = "pending" if pending_pages else "ready"
    if extraction.get("status") != expected_status or manifest.get("extraction_status") != expected_status:
        errors.append({"reason": "reference-pdf-extraction-status", "reference_id": reference_id})
    if extraction.get("extracted_page_count") != len(pages) - len(pending_pages):
        errors.append({"reason": "reference-pdf-extracted-page-count", "reference_id": reference_id})
    if manifest.get("pending_pages") != pending_pages:
        errors.append({"reason": "reference-pdf-manifest-pending-pages", "reference_id": reference_id})
    if require_ready and pending_pages:
        errors.append({"reason": "reference-pdf-pages-pending", "reference_id": reference_id, "pages": pending_pages})
    return extraction, errors


def pdf_fragment(extraction: dict[str, Any], fragment_id: str) -> tuple[dict[str, Any], dict[str, Any]]:
    for page in extraction.get("pages", []):
        for fragment in page.get("fragments", []):
            if fragment.get("fragment_id") == fragment_id:
                return page, fragment
    raise CkbError(f"PDF review fragment does not exist: {fragment_id}")

"""Machine-only research gap register with one bounded human navigation entry."""

from __future__ import annotations

from collections import Counter
import json
from pathlib import Path, PurePosixPath
import re
from typing import Any

from .common import CkbError, json_load, json_write, path_inside, stable_id, utc_now


GAP_SCHEMA_VERSION = 1
GAP_KINDS = ("insufficient-evidence", "conflicting-sources", "deferred-feedback")
GAP_STATUSES = ("open", "deferred", "resolved")
_RECORD_FIELDS = {
    "schema_version", "gap_id", "kind", "status", "summary_zh", "evidence_paths",
    "created_at_utc", "updated_at_utc", "resolution_zh", "resolution_evidence_paths",
}
_CHINESE = re.compile(r"[\u3400-\u9fff]")


def _root(output: Path) -> Path:
    return output.resolve() / "workspace-meta/gaps"


def _records_root(output: Path) -> Path:
    return _root(output) / "records"


def _narrative(path: Path, label: str) -> str:
    if not path.is_file():
        raise CkbError(f"{label} file does not exist: {path}")
    value = re.sub(r"\s+", " ", path.read_text(encoding="utf-8-sig")).strip()
    if len(value) < 8 or len(value) > 600 or len(_CHINESE.findall(value)) < 4:
        raise CkbError(f"{label} must be one Simplified-Chinese statement between 8 and 600 characters")
    return value


def _evidence(output: Path, values: list[str], label: str) -> list[str]:
    if not values:
        raise CkbError(f"{label} requires at least one evidence path")
    if len(values) > 12:
        raise CkbError(f"{label} accepts at most 12 evidence paths")
    result: set[str] = set()
    for value in values:
        candidate = Path(value)
        if not candidate.is_absolute():
            candidate = output / candidate
        resolved = candidate.resolve()
        if not resolved.is_file() or not path_inside(resolved, output):
            raise CkbError(f"{label} evidence must be an existing file inside OUTPUT: {value}")
        result.add(resolved.relative_to(output).as_posix())
    return sorted(result)


def _record_path(output: Path, gap_id: str) -> Path:
    return _records_root(output) / f"{gap_id}.json"


def gap_records(output: Path) -> list[dict[str, Any]]:
    root = _records_root(output)
    if not root.is_dir():
        return []
    result = []
    for path in sorted(root.glob("gap-*.json")):
        value = json_load(path)
        if isinstance(value, dict):
            result.append(value)
    return result


def _index_value(records: list[dict[str, Any]]) -> dict[str, Any]:
    by_status = Counter(str(item.get("status")) for item in records)
    by_kind = Counter(str(item.get("kind")) for item in records)
    return {
        "schema_version": GAP_SCHEMA_VERSION,
        "status": "ready",
        "updated_at_utc": utc_now(),
        "counts": {"total": len(records), **{name: by_status.get(name, 0) for name in GAP_STATUSES}},
        "counts_by_kind": {name: by_kind.get(name, 0) for name in GAP_KINDS},
        "gaps": [
            {
                "gap_id": item["gap_id"], "kind": item["kind"], "status": item["status"],
                "summary_zh": item["summary_zh"], "evidence_count": len(item["evidence_paths"]),
                "updated_at_utc": item["updated_at_utc"],
            }
            for item in records
        ],
    }


def _write_index(output: Path) -> dict[str, Any]:
    value = _index_value(gap_records(output))
    json_write(_root(output) / "index.json", value)
    return value


def gap_navigation_counts(root: Path) -> dict[str, int] | None:
    path = root.parent / "workspace-meta/gaps/index.json"
    if not path.is_file():
        return None
    value = json_load(path)
    counts = value.get("counts") if isinstance(value, dict) else None
    if not isinstance(counts, dict):
        return None
    return {name: int(counts.get(name, 0)) for name in ("total", *GAP_STATUSES)}


def _sync_indexes(output: Path) -> None:
    if (output / "human").is_dir() and (output / "markdown").is_dir():
        from .work_record_index import refresh_work_record_index
        refresh_work_record_index(output)
    if (output / "agent-index.sqlite").is_file():
        from .agent_index import build_agent_index
        build_agent_index(output)
    if (output / "machine/knowledge.sqlite").is_file():
        from .machine_knowledge import build_machine_knowledge
        build_machine_knowledge(output)


def create_gap(output: Path, kind: str, summary_path: Path, evidence_paths: list[str]) -> dict[str, Any]:
    output = output.resolve()
    if not (output / "state.json").is_file():
        raise CkbError(f"CKB output is required: {output}")
    if kind not in GAP_KINDS:
        raise CkbError(f"gap kind must be one of: {list(GAP_KINDS)}")
    summary = _narrative(summary_path.resolve(), "gap summary")
    evidence = _evidence(output, evidence_paths, "gap")
    gap_id = stable_id("gap", kind, summary, *evidence)
    path = _record_path(output, gap_id)
    if path.is_file():
        value = json_load(path)
        return {**value, "idempotent": True, "record": str(path.resolve()), "index": str((_root(output) / "index.json").resolve())}
    stamp = utc_now()
    value = {
        "schema_version": GAP_SCHEMA_VERSION, "gap_id": gap_id, "kind": kind,
        "status": "deferred" if kind == "deferred-feedback" else "open",
        "summary_zh": summary, "evidence_paths": evidence, "created_at_utc": stamp,
        "updated_at_utc": stamp, "resolution_zh": None, "resolution_evidence_paths": [],
    }
    json_write(path, value)
    _write_index(output)
    _sync_indexes(output)
    audit = audit_gap_register(output)
    if audit["status"] != "passed":
        raise CkbError(f"research gap audit failed: {audit['errors'][:10]}")
    return {**value, "idempotent": False, "record": str(path.resolve()), "index": str((_root(output) / "index.json").resolve()), "audit": audit}


def resolve_gap(output: Path, gap_id: str, resolution_path: Path, evidence_paths: list[str]) -> dict[str, Any]:
    output = output.resolve()
    path = _record_path(output, gap_id)
    if not path.is_file():
        raise CkbError(f"research gap does not exist: {gap_id}")
    value = json_load(path)
    if value.get("status") == "resolved":
        raise CkbError(f"research gap is already resolved: {gap_id}")
    value["status"] = "resolved"
    value["resolution_zh"] = _narrative(resolution_path.resolve(), "gap resolution")
    value["resolution_evidence_paths"] = _evidence(output, evidence_paths, "gap resolution")
    value["updated_at_utc"] = utc_now()
    json_write(path, value)
    _write_index(output)
    _sync_indexes(output)
    audit = audit_gap_register(output)
    if audit["status"] != "passed":
        raise CkbError(f"research gap audit failed: {audit['errors'][:10]}")
    return {**value, "record": str(path.resolve()), "index": str((_root(output) / "index.json").resolve()), "audit": audit}


def list_gaps(output: Path, status: str | None = None, kind: str | None = None) -> dict[str, Any]:
    if status is not None and status not in GAP_STATUSES:
        raise CkbError(f"gap status must be one of: {list(GAP_STATUSES)}")
    if kind is not None and kind not in GAP_KINDS:
        raise CkbError(f"gap kind must be one of: {list(GAP_KINDS)}")
    selected = [item for item in gap_records(output.resolve()) if (status is None or item.get("status") == status) and (kind is None or item.get("kind") == kind)]
    return {"schema_version": GAP_SCHEMA_VERSION, "status": "ready", "filters": {"status": status, "kind": kind}, "count": len(selected), "gaps": selected}


def gap_machine_records(output: Path) -> dict[str, Any]:
    records = gap_records(output)
    documents = []
    for item in records:
        status_zh = {"open": "待补证据", "deferred": "暂缓处理", "resolved": "已关闭"}[item["status"]]
        kind_zh = {"insufficient-evidence": "证据不足", "conflicting-sources": "来源冲突", "deferred-feedback": "暂缓反馈"}[item["kind"]]
        lines = [f"状态：{status_zh}", f"类型：{kind_zh}", f"待验证说明：{item['summary_zh']}", "证据路径：" + "；".join(item["evidence_paths"])]
        if item.get("resolution_zh"):
            lines.extend([f"关闭说明：{item['resolution_zh']}", "关闭证据：" + "；".join(item.get("resolution_evidence_paths", []))])
        content = "\n".join(lines)
        documents.append({"document_id": f"gap:{item['gap_id']}", "gap_id": item["gap_id"], "kind": "gap", "title": "研究缺口：" + item["summary_zh"][:80], "tag": "#类型/缺口", "human_file": None, "content": content, "section_heading": "待验证研究缺口" if item["status"] != "resolved" else "已关闭研究缺口", "record": item})
    return {"records": records, "documents": documents}


def _record_errors(output: Path, path: Path, item: dict[str, Any]) -> list[str]:
    if set(item) != _RECORD_FIELDS:
        return [f"{path.name}: fields differ from the fixed gap schema"]
    errors = []
    if item.get("schema_version") != GAP_SCHEMA_VERSION or item.get("kind") not in GAP_KINDS or item.get("status") not in GAP_STATUSES:
        errors.append(f"{path.name}: schema, kind, or status is invalid")
    summary = item.get("summary_zh")
    if not isinstance(summary, str) or len(_CHINESE.findall(summary)) < 4:
        errors.append(f"{path.name}: summary must use Simplified Chinese")
    evidence = item.get("evidence_paths")
    if not isinstance(evidence, list) or not evidence or len(evidence) > 12:
        errors.append(f"{path.name}: evidence_paths must contain one to twelve files")
    else:
        for value in evidence:
            relative = PurePosixPath(str(value))
            if relative.is_absolute() or ".." in relative.parts or not (output / Path(str(value))).is_file():
                errors.append(f"{path.name}: invalid or missing evidence path: {value}")
    expected_id = stable_id("gap", item.get("kind"), item.get("summary_zh"), *(item.get("evidence_paths") or []))
    if item.get("gap_id") != expected_id or path.stem != expected_id:
        errors.append(f"{path.name}: stable gap id mismatch")
    if item.get("status") == "resolved":
        resolution = item.get("resolution_zh")
        resolution_evidence = item.get("resolution_evidence_paths")
        if not isinstance(resolution, str) or len(_CHINESE.findall(resolution)) < 4:
            errors.append(f"{path.name}: resolved gap requires a Chinese resolution")
        if not isinstance(resolution_evidence, list) or not resolution_evidence:
            errors.append(f"{path.name}: resolved gap requires closure evidence")
        else:
            for value in resolution_evidence:
                relative = PurePosixPath(str(value))
                if relative.is_absolute() or ".." in relative.parts or not (output / Path(str(value))).is_file():
                    errors.append(f"{path.name}: invalid or missing closure evidence: {value}")
    elif item.get("resolution_zh") is not None or item.get("resolution_evidence_paths") != []:
        errors.append(f"{path.name}: unresolved gap must not contain resolution fields")
    return errors


def audit_gap_register(output: Path) -> dict[str, Any]:
    output = output.resolve()
    root = _root(output)
    if not root.is_dir():
        return {"schema_version": GAP_SCHEMA_VERSION, "status": "passed", "initialized": False, "counts": {"total": 0, "open": 0, "deferred": 0, "resolved": 0}, "errors": []}
    errors: list[str] = []
    records = gap_records(output)
    for path in sorted(_records_root(output).glob("gap-*.json")):
        item = json_load(path)
        if not isinstance(item, dict):
            errors.append(f"{path.name}: gap record must be an object")
            continue
        errors.extend(_record_errors(output, path, item))
    index_path = root / "index.json"
    index = json_load(index_path) if index_path.is_file() else {}
    if not index_path.is_file():
        errors.append("gap index is missing")
    expected = _index_value(records)
    for key in ("schema_version", "status", "counts", "counts_by_kind", "gaps"):
        if index.get(key) != expected.get(key):
            errors.append(f"gap index mismatch: {key}")
    if (output / "human/gaps").exists() or (output / "markdown/gaps").exists():
        errors.append("research gaps must not create one human page per gap")
    for human_root in (output / "human", output / "markdown"):
        if human_root.is_dir():
            records_page = human_root / "RECORDS.md"
            text = records_page.read_text(encoding="utf-8-sig") if records_page.is_file() else ""
            if text.count("## 研究缺口与待补来源") != 1:
                errors.append(f"single research-gap navigation entry is missing: {records_page}")
    database = output / "machine/knowledge.sqlite"
    if database.is_file():
        import sqlite3
        with sqlite3.connect(database) as connection:
            tables = {row[0] for row in connection.execute("SELECT name FROM sqlite_master WHERE type='table'")}
            if "research_gaps" not in tables:
                errors.append("machine knowledge research_gaps table is missing")
            elif connection.execute("SELECT count(*) FROM research_gaps").fetchone()[0] != len(records):
                errors.append("machine gap count mismatch")
    counts = Counter(str(item.get("status")) for item in records)
    return {"schema_version": GAP_SCHEMA_VERSION, "status": "passed" if not errors else "failed", "initialized": True, "counts": {"total": len(records), **{name: counts.get(name, 0) for name in GAP_STATUSES}}, "index": str(index_path.resolve()), "errors": errors}

from __future__ import annotations

import json
import os
import shutil
import zipfile
from pathlib import Path
from typing import Any

from .common import CkbError, DependencyError, json_load, json_write, safe_rmtree, sha256_file, utc_now
from .providers import private_runtime_root


def skill_root() -> Path:
    return Path(__file__).resolve().parents[2]


def lock_document() -> dict[str, Any]:
    return json_load(skill_root() / "toolchain.lock.json")


def payload_path() -> Path:
    return skill_root() / "assets" / "runtime" / "win-x64" / "payload.zip"


def deployment_plan() -> dict[str, Any]:
    lock = lock_document()
    payload = payload_path()
    destination = private_runtime_root() / lock["lock_id"]
    payload_lock = lock.get("payload")
    deployed_record = (
        json_load(destination / "deployed.json")
        if destination.is_dir() and (destination / "deployed.json").is_file()
        else {}
    )
    required_members = payload_lock.get("required_members", []) if isinstance(payload_lock, dict) else []
    deployment_matches = (
        isinstance(payload_lock, dict)
        and deployed_record.get("status") == "ready"
        and deployed_record.get("lock_id") == lock.get("lock_id")
        and deployed_record.get("payload_sha256") == payload_lock.get("sha256")
        and (destination / "payload-files.json").is_file()
        and isinstance(required_members, list)
        and bool(required_members)
        and all((destination / member).is_file() for member in required_members)
    )
    if deployment_matches:
        status = "ready"
    elif not payload.is_file():
        status = "payload-missing"
    elif not isinstance(payload_lock, dict):
        status = "payload-unlocked"
    elif payload.stat().st_size != int(payload_lock.get("size", -1)) or sha256_file(payload) != payload_lock.get("sha256"):
        status = "payload-invalid"
    else:
        status = "permission-required"
    return {
        "status": status,
        "lock_id": lock["lock_id"],
        "components": lock["components"],
        "payload": str(payload.resolve()),
        "payload_size": payload.stat().st_size if payload.is_file() else None,
        "payload_sha256": sha256_file(payload) if payload.is_file() else None,
        "expected_payload": payload_lock,
        "destination": str(destination.resolve()),
        "rollback": f"runtime remove --lock-id {lock['lock_id']}",
    }


def deploy(accept: bool) -> dict[str, Any]:
    plan = deployment_plan()
    if plan["status"] == "ready":
        return plan
    if plan["status"] != "permission-required":
        raise DependencyError(json.dumps(plan, ensure_ascii=False))
    if not accept:
        raise DependencyError(json.dumps(plan, ensure_ascii=False))
    payload = Path(plan["payload"])
    destination = Path(plan["destination"])
    destination.parent.mkdir(parents=True, exist_ok=True)
    temporary = destination.with_name(destination.name + ".deploying")
    if temporary.exists():
        safe_rmtree(temporary, destination.parent)
    temporary.mkdir()
    host_snapshot = _host_snapshot()
    with zipfile.ZipFile(payload) as archive:
        for member in archive.infolist():
            target = (temporary / member.filename).resolve()
            try:
                target.relative_to(temporary.resolve())
            except ValueError as exc:
                raise CkbError(f"runtime archive path escapes destination: {member.filename}") from exc
        archive.extractall(temporary)
    files_manifest_path = temporary / "payload-files.json"
    if not files_manifest_path.is_file():
        safe_rmtree(temporary, destination.parent)
        raise CkbError("runtime payload lacks payload-files.json")
    files_manifest = json_load(files_manifest_path)
    for item in files_manifest.get("files", []):
        member_path = (temporary / item["path"]).resolve()
        try:
            member_path.relative_to(temporary.resolve())
        except ValueError as exc:
            safe_rmtree(temporary, destination.parent)
            raise CkbError(f"runtime manifest path escapes destination: {item['path']}") from exc
        if not member_path.is_file() or member_path.stat().st_size != int(item["size"]) or sha256_file(member_path) != item["sha256"]:
            safe_rmtree(temporary, destination.parent)
            raise CkbError(f"runtime payload member verification failed: {item['path']}")
    json_write(
        temporary / "deployed.json",
        {
            "status": "ready",
            "lock_id": plan["lock_id"],
            "payload_sha256": plan["payload_sha256"],
            "deployed_at_utc": utc_now(),
            "host_snapshot_before": host_snapshot,
        },
    )
    if destination.exists():
        safe_rmtree(destination, destination.parent)
    os.replace(temporary, destination)
    plan["status"] = "ready"
    return plan


def remove(lock_id: str) -> dict[str, Any]:
    root = private_runtime_root().resolve()
    target = (root / lock_id).resolve()
    try:
        target.relative_to(root)
    except ValueError as exc:
        raise CkbError("runtime lock ID resolves outside the private runtime root") from exc
    existed = target.exists()
    deployment = json_load(target / "deployed.json") if (target / "deployed.json").is_file() else {}
    if existed:
        safe_rmtree(target, root)
    current_snapshot = _host_snapshot()
    expected_snapshot = deployment.get("host_snapshot_before")
    return {
        "status": "removed",
        "lock_id": lock_id,
        "path": str(target),
        "existed": existed,
        "host_snapshot_before": expected_snapshot,
        "host_snapshot_after": current_snapshot,
        "host_environment_restored": expected_snapshot is None or expected_snapshot == current_snapshot,
    }


def _host_snapshot() -> dict[str, Any]:
    commands = ["python", "node", "git", "pyright-langserver", "typescript-language-server", "clangd", "csharp-ls", "dotnet", "logseq"]
    return {"path": os.environ.get("PATH", ""), "commands": {name: shutil.which(name) for name in commands}}

"""Audited, reversible extension of a completed CKB knowledge scope."""

from __future__ import annotations

import hashlib
import json
import gc
from pathlib import Path, PurePosixPath
import shutil
import sqlite3
from typing import Any
import warnings

from .common import CkbError, json_load, json_write, path_inside, sha256_file, stable_id
from .gitrepo import LANGUAGE_BY_SUFFIX, preflight
from .migration import (
    _entity_key,
    _preserve_mutable_layers,
    _replace_review_packs,
    _review_for_new_entity,
    _review_shape,
    _selected_entities,
)
from .pipeline import build_chunk, finalize, initialize, status as pipeline_status


SCOPE_EXTENSION_SCHEMA_VERSION = 1
STATE_RELATIVE = Path("scope-extension/state.json")
PLAN_RELATIVE = Path("scope-extension/plan.json")
AUDIT_RELATIVE = Path("scope-extension/audit.json")
SUPPORTED_LANGUAGES = tuple(sorted(set(LANGUAGE_BY_SUFFIX.values())))


def _error(category: str, message: str) -> CkbError:
    return CkbError(f"scope-extension:{category}: {message}")


def _canonical_entry(value: str) -> str:
    value = value.strip()
    if "#" not in value:
        raise _error("entry-shape", f"new entry must use LANGUAGE:PATH#QUALIFIED_NAME: {value}")
    left, qualified = value.split("#", 1)
    if ":" not in left:
        raise _error("entry-shape", f"new entry must use LANGUAGE:PATH#QUALIFIED_NAME: {value}")
    language, path = left.split(":", 1)
    language = language.strip().casefold()
    normalized_path = PurePosixPath(path.replace("\\", "/").strip("/"))
    if language not in SUPPORTED_LANGUAGES:
        raise _error("unsupported-language", f"entry language is not supported: {language}")
    if not path or normalized_path.is_absolute() or ".." in normalized_path.parts:
        raise _error("entry-path", f"entry path must be a repository-relative source path: {path}")
    if not qualified.strip():
        raise _error("entry-qualified-name", "entry qualified name must not be empty")
    return f"{language}:{normalized_path.as_posix()}#{qualified.strip()}"


def _tree_manifest(root: Path) -> dict[str, Any]:
    root = root.resolve()
    if not root.is_dir():
        raise _error("output-missing", f"directory does not exist: {root}")
    files: list[dict[str, Any]] = []
    for path in sorted((item for item in root.rglob("*") if item.is_file()), key=lambda item: item.relative_to(root).as_posix()):
        relative = path.relative_to(root).as_posix()
        files.append({"path": relative, "size": path.stat().st_size, "sha256": sha256_file(path)})
    canonical = json.dumps(files, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return {
        "algorithm": "sha256-tree-v1",
        "file_count": len(files),
        "byte_count": sum(int(item["size"]) for item in files),
        "sha256": hashlib.sha256(canonical).hexdigest(),
        "files": files,
    }


def _same_manifest(left: dict[str, Any], right: dict[str, Any]) -> bool:
    return all(left.get(key) == right.get(key) for key in ("algorithm", "file_count", "byte_count", "sha256", "files"))


def _sqlite_checks(output: Path) -> list[dict[str, Any]]:
    checks: list[dict[str, Any]] = []
    for relative in ("machine/knowledge.sqlite", "agent-index.sqlite", "machine/automation.sqlite"):
        path = output / relative
        if not path.is_file():
            if relative == "machine/automation.sqlite":
                continue
            checks.append({"path": relative, "integrity_check": "missing", "foreign_key_errors": None, "passed": False})
            continue
        connection = sqlite3.connect(f"file:{path.as_posix()}?mode=ro", uri=True)
        try:
            integrity = str(connection.execute("PRAGMA integrity_check").fetchone()[0])
            foreign_keys = connection.execute("PRAGMA foreign_key_check").fetchall()
        finally:
            connection.close()
        checks.append({
            "path": relative,
            "integrity_check": integrity,
            "foreign_key_errors": [list(row) for row in foreign_keys],
            "passed": integrity == "ok" and not foreign_keys,
        })
    return checks


def _release_audit_handles() -> None:
    """Release transient sqlite objects left by read-only audit helpers."""
    with warnings.catch_warnings():
        warnings.simplefilter("ignore", ResourceWarning)
        gc.collect()


def _candidate_graph(output: Path) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    state = json_load(output / "state.json")
    entities: dict[str, dict[str, Any]] = {}
    links: dict[str, dict[str, Any]] = {}
    for batch in state["parse_batches"]:
        candidate = json_load(output / "chunks" / batch["id"] / "candidate.json")
        entities.update((item["id"], item) for item in candidate.get("entities", []))
        links.update((item["id"], item) for item in candidate.get("links", []))
    return [entities[key] for key in sorted(entities)], [links[key] for key in sorted(links)]


def _dimension(old_values: set[str], new_values: set[str]) -> dict[str, Any]:
    return {
        "retained": sorted(old_values & new_values),
        "added": sorted(new_values - old_values),
        "removed": sorted(old_values - new_values),
        "counts": {
            "retained": len(old_values & new_values),
            "added": len(new_values - old_values),
            "removed": len(old_values - new_values),
        },
    }


def _page_ids(document: dict[str, Any]) -> set[str]:
    return set(document.get("page_entity_ids") or [])


def _replace_prefix(value: Any, old: str, new: str) -> Any:
    if isinstance(value, dict):
        return {key: _replace_prefix(item, old, new) for key, item in value.items()}
    if isinstance(value, list):
        return [_replace_prefix(item, old, new) for item in value]
    if isinstance(value, str):
        return value.replace(old, new).replace(old.replace("\\", "/"), new.replace("\\", "/"))
    return value


def _rebind_preserved_json(staging: Path, previous_output: Path, mutable_files: list[dict[str, Any]]) -> list[str]:
    changed: list[str] = []
    old = str(previous_output.resolve())
    new = str(staging.resolve())
    for item in mutable_files:
        relative = str(item.get("relative_target") or "")
        path = staging / relative
        if path.suffix.casefold() != ".json" or not path.is_file():
            continue
        try:
            value = json_load(path)
        except (CkbError, OSError, UnicodeError, json.JSONDecodeError):
            continue
        updated = _replace_prefix(value, old, new)
        if updated != value:
            json_write(path, updated)
            changed.append(relative)
        item["post_extension_sha256"] = sha256_file(path)
        item["post_extension_size"] = path.stat().st_size
    return sorted(changed)


def _layer_inventory(output: Path, mutable_files: list[dict[str, Any]] | None = None) -> dict[str, Any]:
    gaps = list((output / "workspace-meta/gaps/records").glob("gap-*.json"))
    gap_statuses: dict[str, int] = {}
    for path in gaps:
        status = str(json_load(path).get("status"))
        gap_statuses[status] = gap_statuses.get(status, 0) + 1
    manifests = list((output / "references/manifests").glob("*.json"))
    reference_statuses: dict[str, int] = {}
    for path in manifests:
        status = str(json_load(path).get("status"))
        reference_statuses[status] = reference_statuses.get(status, 0) + 1
    records = mutable_files or []
    return {
        "work_record_count": len(list((output / "workspace-meta/notes").glob("*.json"))),
        "reference_count": len(manifests),
        "reference_statuses": dict(sorted(reference_statuses.items())),
        "gap_count": len(gaps),
        "gap_statuses": dict(sorted(gap_statuses.items())),
        "feedback_count": len(list((output / "workspace-meta/feedback").glob("*/*.json"))),
        "operation_shard_count": len(list((output / "workspace-meta/operations").glob("*.jsonl"))),
        "vault_user_files": sorted(
            item["relative_target"]
            for item in records
            if item.get("kind") == "vault-user-file"
        ),
    }


def _preservation_errors(staging: Path, records: list[dict[str, Any]]) -> list[dict[str, Any]]:
    errors: list[dict[str, Any]] = []
    for item in records:
        relative = str(item.get("relative_target") or "")
        baseline_relative = str(item.get("baseline_relative_target") or "")
        target = staging / relative
        baseline = staging / baseline_relative
        if not baseline.is_file() or sha256_file(baseline) != item.get("baseline_sha256"):
            errors.append({"path": relative, "reason": "baseline-missing-or-changed"})
            continue
        if not target.is_file():
            errors.append({"path": relative, "reason": "live-file-missing"})
            continue
        # A same-snapshot scope extension does not rekey page titles.  Vault
        # user bytes, including learning notes and work-record prose, therefore
        # remain exact; JSON control records may receive bounded path rebinding.
        if item.get("kind") == "vault-user-file" and sha256_file(target) != item.get("initial_target_sha256"):
            errors.append({"path": relative, "reason": "vault-user-file-changed"})
    return errors


def _recomputed_review_sets(staging: Path, old_graph: dict[str, Any]) -> tuple[set[str], set[str], set[str]]:
    new_entities, _sources = _selected_entities(staging)
    _candidate_entities, candidate_links = _candidate_graph(staging)
    old_links = {item["id"]: item for item in old_graph.get("links", [])}
    new_links = {item["id"]: item for item in candidate_links}
    added_relation_ids = set(new_links) - set(old_links)
    affected_ids = {
        endpoint
        for relation_id in added_relation_ids
        for endpoint in (new_links[relation_id].get("source"), new_links[relation_id].get("target"))
        if endpoint
    }
    catalog = json_load(staging / "catalog.json")
    reuse_paths = set((catalog.get("migration_reuse") or {}).get("reused_file_paths", []))
    old_by_key = {_entity_key(entity): entity for entity in old_graph.get("entities", [])}
    reusable: set[str] = set()
    for entity in new_entities:
        previous = old_by_key.get(_entity_key(entity))
        if (
            entity["path"] in reuse_paths
            and entity["id"] not in affected_ids
            and previous
            and previous.get("review_status") == "agent-reviewed"
            and _review_shape(previous.get("classification")) == _review_shape(entity.get("classification"))
        ):
            reusable.add(entity["id"])
    selected = {item["id"] for item in new_entities}
    return reusable, selected - reusable, added_relation_ids


def _load_extension_state(output: Path) -> dict[str, Any]:
    path = output.resolve() / STATE_RELATIVE
    if not path.is_file():
        raise _error("state-missing", f"scope extension state does not exist: {path}")
    value = json_load(path)
    if value.get("schema_version") != SCOPE_EXTENSION_SCHEMA_VERSION:
        raise _error("state-schema", "scope extension state schema is unsupported")
    if Path(str(value.get("staging_output"))).resolve() != output.resolve():
        raise _error("absolute-binding", "state staging_output does not match the requested output")
    return value


def start_scope_extension(
    previous_output: Path,
    repository: Path,
    staging: Path,
    entries: list[str],
    expand_depth: int,
    expand_direction: str,
) -> dict[str, Any]:
    previous_output = previous_output.resolve()
    repository = repository.resolve()
    staging = staging.resolve()
    if path_inside(staging, previous_output) or path_inside(previous_output, staging):
        raise _error("overlapping-output", "staging and previous OUTPUT must be separate, non-overlapping directories")
    if expand_depth < 0:
        raise _error("expand-depth", "extension depth must be zero or greater")
    if expand_direction not in {"both", "callers", "callees"}:
        raise _error("expand-direction", f"unsupported expansion direction: {expand_direction}")
    canonical_added = [_canonical_entry(value) for value in entries]
    if not canonical_added:
        raise _error("entry-required", "at least one new entry is required")
    if len(set(canonical_added)) != len(canonical_added):
        raise _error("duplicate-entry", "the same new center was supplied more than once")

    old_state = json_load(previous_output / "state.json")
    old_audit = json_load(previous_output / "audit/global.json")
    old_scope = json_load(previous_output / "scope.json")
    old_graph = json_load(previous_output / "graph.json")
    if old_state.get("status") != "complete" or old_audit.get("status") != "passed" or not (previous_output / ".complete").is_file():
        raise _error("origin-not-audited", f"previous OUTPUT is not complete and globally audited: {previous_output}")
    selectors = old_scope.get("selectors") or {}
    old_entries = list(selectors.get("entries") or [])
    old_canonical = {_canonical_entry(value) for value in old_entries if "#" in str(value)}
    duplicates = sorted(set(canonical_added) & old_canonical)
    if duplicates:
        raise _error("entry-already-present", f"new center already exists in the old scope: {duplicates}")
    target_entries = [*old_entries, *sorted(canonical_added)]
    repository_state = preflight(repository)
    operation_id = stable_id(
        "scope-extension",
        previous_output,
        repository_state["commit"],
        *target_entries,
        expand_depth,
        expand_direction,
    )
    request = {
        "previous_output": str(previous_output),
        "repository": str(repository),
        "repository_commit": repository_state["commit"],
        "staging_output": str(staging),
        "added_entries": sorted(canonical_added),
        "target_entries": target_entries,
        "expand_depth": expand_depth,
        "expand_direction": expand_direction,
    }
    if staging.exists():
        state_path = staging / STATE_RELATIVE
        if not state_path.is_file():
            raise _error("staging-not-empty", f"staging already exists without matching extension state: {staging}")
        existing = _load_extension_state(staging)
        if existing.get("operation_id") != operation_id or existing.get("request") != request:
            raise _error("staging-conflict", "staging is bound to a different scope extension request")
        return extension_status(staging)

    origin_manifest = _tree_manifest(previous_output)
    try:
        initialize(
            repository,
            staging,
            old_state["format"],
            list(selectors.get("scope_paths") or []),
            target_entries,
            expand_depth,
            expand_direction,
            list(selectors.get("include") or []),
            csharp_solution=selectors.get("csharp_solution"),
            csharp_project=selectors.get("csharp_project"),
            allow_dotnet_restore=bool(selectors.get("allow_dotnet_restore", False)),
            page_config_path=previous_output / "page-config.json",
            reuse_from_output=previous_output,
        )
        mutable_files = _preserve_mutable_layers(previous_output, staging)
        rebound_json = _rebind_preserved_json(staging, previous_output, mutable_files)
        state = json_load(staging / "state.json")
        for batch in state["parse_batches"]:
            build_chunk(staging, batch["id"], "all")
        new_entities, _sources = _selected_entities(staging)
        _candidate_entities, candidate_links = _candidate_graph(staging)
        old_links = {item["id"]: item for item in old_graph.get("links", [])}
        new_links = {item["id"]: item for item in candidate_links}
        added_relation_ids = set(new_links) - set(old_links)
        affected_ids = {
            endpoint
            for relation_id in added_relation_ids
            for endpoint in (new_links[relation_id].get("source"), new_links[relation_id].get("target"))
            if endpoint
        }
        catalog = json_load(staging / "catalog.json")
        reuse_paths = set((catalog.get("migration_reuse") or {}).get("reused_file_paths", []))
        old_by_key = {_entity_key(entity): entity for entity in old_graph.get("entities", [])}
        reusable_reviews: dict[str, dict[str, Any]] = {}
        id_map: dict[str, str] = {}
        for entity in new_entities:
            previous = old_by_key.get(_entity_key(entity))
            if (
                entity["path"] in reuse_paths
                and entity["id"] not in affected_ids
                and previous
                and previous.get("review_status") == "agent-reviewed"
                and _review_shape(previous.get("classification")) == _review_shape(entity.get("classification"))
            ):
                reusable_reviews[entity["id"]] = _review_for_new_entity(entity, previous)
                id_map[str(previous["id"])] = entity["id"]
        reused_ids, delta_ids = _replace_review_packs(staging, reusable_reviews)

        new_scope = json_load(staging / "scope.json")
        new_navigation = json_load(staging / "navigation-plan.json")
        old_navigation = old_graph.get("navigation_plan") or {}
        dimensions = {
            "entries": _dimension(set(old_entries), set(target_entries)),
            "paths": _dimension(set(old_scope.get("selected_file_paths") or []), set(new_scope.get("selected_file_paths") or [])),
            "entities": _dimension({item["id"] for item in old_graph.get("entities", [])}, set(new_scope.get("selected_entity_ids") or [])),
            "relations": _dimension(set(old_links), set(new_links)),
            "pages": _dimension(_page_ids(old_navigation), _page_ids(new_navigation)),
        }
        removed = {name: value["removed"] for name, value in dimensions.items() if value["removed"]}
        if removed:
            raise _error("scope-contraction", f"append-only extension removed prior scope items: {removed}")
        final_state = json_load(staging / "state.json")
        extension = {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "operation_id": operation_id,
            "status": "pending-agent-review" if delta_ids else "ready-for-audit",
            "previous_output": str(previous_output),
            "staging_output": str(staging),
            "repository": str(repository),
            "repository_commit": repository_state["commit"],
            "request": request,
        }
        final_state["scope_extension"] = extension
        json_write(staging / "state.json", final_state)
        plan = {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "operation_id": operation_id,
            "status": extension["status"],
            "bindings": {
                "previous_output": str(previous_output),
                "staging_output": str(staging),
                "repository": str(repository),
                "repository_commit": repository_state["commit"],
                "origin_commit": old_state.get("repository", {}).get("commit"),
            },
            "selectors": {
                "old_entries": old_entries,
                "added_entries": sorted(canonical_added),
                "target_entries": target_entries,
                "expand_depth": expand_depth,
                "expand_direction": expand_direction,
            },
            "delta": dimensions,
            "review": {
                "reused_entity_ids": sorted(reused_ids),
                "delta_entity_ids": sorted(delta_ids),
                "affected_relation_ids": sorted(added_relation_ids),
                "affected_existing_entity_ids": sorted(affected_ids & {item["id"] for item in old_graph.get("entities", [])}),
                "old_to_new_id_map": id_map,
            },
            "reuse": {
                "file_paths": sorted(reuse_paths),
                "file_count": len(reuse_paths),
                "review_entity_count": len(reused_ids),
                "delta_review_entity_count": len(delta_ids),
            },
            "preservation": {
                "origin_manifest": origin_manifest,
                "mutable_files": mutable_files,
                "rebound_json_files": rebound_json,
                "origin_layers": _layer_inventory(previous_output, mutable_files),
            },
        }
        json_write(staging / PLAN_RELATIVE, plan)
        json_write(staging / STATE_RELATIVE, {**extension, "request": request})
    except Exception as exc:
        if staging.exists():
            shutil.rmtree(staging)
        if isinstance(exc, CkbError) and str(exc).startswith("scope-extension:"):
            raise
        message = str(exc)
        category = "entry-resolution" if "entry resolves to" in message else "start-failed"
        raise _error(category, message) from exc
    return extension_status(staging)


def _control_records(output: Path) -> list[tuple[Path, dict[str, Any]]]:
    """Load and validate the immutable control history for one OUTPUT name.

    Legacy schema-1 records did not persist parent_operation_id.  Their parent
    is inferred only when exactly one older modified manifest equals the
    child's origin manifest.  New records persist that same relation and depth.
    """
    output = output.resolve()
    records: list[tuple[Path, dict[str, Any]]] = []
    by_id: dict[str, tuple[Path, dict[str, Any]]] = {}
    for path in sorted(output.parent.glob(f".{output.name}.scope-extension-*.json")):
        value = json_load(path)
        operation_id = str(value.get("operation_id") or "")
        if value.get("schema_version") != SCOPE_EXTENSION_SCHEMA_VERSION or not operation_id:
            raise _error("control-record-drift", f"control record schema or operation id is invalid: {path}")
        if path != _control_path(output, operation_id):
            raise _error("control-record-drift", f"control record path does not match operation id: {path}")
        if Path(str(value.get("output") or "")).resolve() != output:
            raise _error("control-record-drift", f"control record OUTPUT binding drifted: {path}")
        if operation_id in by_id:
            raise _error("control-record-drift", f"duplicate control operation id: {operation_id}")
        item = json.loads(json.dumps(value))
        records.append((path, item))
        by_id[operation_id] = (path, item)

    for path, value in records:
        origin = value.get("origin_manifest")
        if not isinstance(origin, dict):
            raise _error("control-record-drift", f"control origin manifest is missing: {path}")
        inferred = [
            candidate
            for _candidate_path, candidate in records
            if candidate.get("operation_id") != value.get("operation_id")
            and isinstance(candidate.get("modified_manifest"), dict)
            and _same_manifest(candidate["modified_manifest"], origin)
        ]
        if "parent_operation_id" in value:
            parent_id = value.get("parent_operation_id")
            if parent_id is not None:
                parent = by_id.get(str(parent_id))
                if parent is None or not isinstance(parent[1].get("modified_manifest"), dict) or not _same_manifest(parent[1]["modified_manifest"], origin):
                    raise _error("control-record-drift", f"parent operation does not produce the child origin: {path}")
        else:
            if len(inferred) > 1:
                raise _error("control-record-drift", f"legacy parent operation is ambiguous: {path}")
            parent_id = inferred[0]["operation_id"] if inferred else None
        value["parent_operation_id"] = parent_id

    depths: dict[str, int] = {}

    def depth(operation_id: str, trail: set[str]) -> int:
        if operation_id in depths:
            return depths[operation_id]
        if operation_id in trail:
            raise _error("control-record-drift", f"control parent cycle includes: {operation_id}")
        value = by_id[operation_id][1]
        parent_id = value.get("parent_operation_id")
        result = 1 if parent_id is None else depth(str(parent_id), {*trail, operation_id}) + 1
        recorded = value.get("chain_depth")
        if recorded is not None and int(recorded) != result:
            raise _error("control-record-drift", f"control chain depth drifted: {operation_id}")
        value["chain_depth"] = result
        depths[operation_id] = result
        return result

    for _path, value in records:
        depth(str(value["operation_id"]), set())
    return records


def _control_selection(output: Path, actual_manifest: dict[str, Any] | None = None) -> dict[str, Any]:
    output = output.resolve()
    records = _control_records(output)
    actual = actual_manifest or _tree_manifest(output)
    active = [
        (path, value)
        for path, value in records
        if value.get("status") == "cutover-complete"
        and isinstance(value.get("modified_manifest"), dict)
        and _same_manifest(value["modified_manifest"], actual)
    ]
    if len(active) > 1:
        raise _error("control-record-active-ambiguous", f"multiple active cutovers match current OUTPUT: {[item[1]['operation_id'] for item in active]}")
    rolled_back = [
        (path, value)
        for path, value in records
        if value.get("status") == "rolled-back"
        and _same_manifest(value["origin_manifest"], actual)
    ]
    return {
        "records": records,
        "actual_manifest": actual,
        "active": active[0] if active else None,
        "rolled_back_matches": rolled_back,
    }


def _public_control(value: dict[str, Any]) -> dict[str, Any]:
    return json.loads(json.dumps(value))


def extension_status(output: Path) -> dict[str, Any]:
    output = output.resolve()
    controls = sorted(output.parent.glob(f".{output.name}.scope-extension-*.json"))
    if controls:
        selection = _control_selection(output)
        if selection["active"]:
            _path, active = selection["active"]
            return {
                "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
                "status": "cutover-complete",
                "active_operation_id": active["operation_id"],
                "parent_operation_id": active.get("parent_operation_id"),
                "chain_depth": active["chain_depth"],
                "cutover": _public_control(active),
                "control_record_count": len(selection["records"]),
            }
        rolled_back = selection["rolled_back_matches"]
        return {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "status": "rolled-back" if len(rolled_back) == 1 else "no-active-cutover",
            "active_operation_id": None,
            "rolled_back_operation_id": rolled_back[0][1]["operation_id"] if len(rolled_back) == 1 else None,
            "matching_rolled_back_operation_ids": [value["operation_id"] for _path, value in rolled_back],
            "control_record_count": len(selection["records"]),
        }
    state = _load_extension_state(output)
    plan = json_load(output / PLAN_RELATIVE)
    build_state = json_load(output / "state.json")
    pending = [item["id"] for item in build_state.get("review_packs", []) if item.get("status") != "passed"]
    return {
        "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
        "status": state["status"],
        "operation_id": state["operation_id"],
        "previous_output": state["previous_output"],
        "staging_output": state["staging_output"],
        "repository_commit": state["repository_commit"],
        "pending_review_packs": pending,
        "next_review_template": next((item.get("review_template_path") for item in build_state.get("review_packs", []) if item.get("status") != "passed"), None),
        "delta": plan["delta"],
        "reuse": plan["reuse"],
    }


def audit_scope_extension(staging: Path) -> dict[str, Any]:
    staging = staging.resolve()
    state = _load_extension_state(staging)
    plan = json_load(staging / PLAN_RELATIVE)
    checks: list[dict[str, Any]] = []

    def check(name: str, passed: bool, detail: Any, category: str) -> None:
        checks.append({"name": name, "passed": bool(passed), "category": category, "detail": detail})

    origin = Path(state["previous_output"])
    actual_origin = _tree_manifest(origin)
    expected_origin = plan["preservation"]["origin_manifest"]
    check("origin-output-unchanged", _same_manifest(actual_origin, expected_origin), {"expected": expected_origin["sha256"], "actual": actual_origin["sha256"]}, "origin-drift")
    repository_state = preflight(Path(state["repository"]))
    check("target-repository-pinned", repository_state["commit"] == state["repository_commit"], repository_state, "target-drift")
    removed = {name: value["removed"] for name, value in plan["delta"].items() if value["removed"]}
    check("append-only-delta", not removed, removed, "scope-contraction")
    build_state = json_load(staging / "state.json")
    old_graph = json_load(origin / "graph.json")
    expected_reused, expected_delta, expected_added_relations = _recomputed_review_sets(staging, old_graph)
    actual_reused = {
        entity_id
        for pack in build_state.get("review_packs", [])
        if str(pack.get("id", "")).startswith("migrated-")
        for entity_id in pack.get("entity_ids", [])
    }
    actual_delta = {
        entity_id
        for pack in build_state.get("review_packs", [])
        if str(pack.get("id", "")).startswith("delta-")
        for entity_id in pack.get("entity_ids", [])
    }
    review_detail = {
        "reused_missing": sorted(expected_reused - actual_reused),
        "reused_extra": sorted(actual_reused - expected_reused),
        "delta_missing": sorted(expected_delta - actual_delta),
        "delta_extra": sorted(actual_delta - expected_delta),
        "relation_delta_missing": sorted(expected_added_relations - set(plan["review"]["affected_relation_ids"])),
        "relation_delta_extra": sorted(set(plan["review"]["affected_relation_ids"]) - expected_added_relations),
        "plan_reused_missing": sorted(expected_reused - set(plan["review"]["reused_entity_ids"])),
        "plan_reused_extra": sorted(set(plan["review"]["reused_entity_ids"]) - expected_reused),
        "plan_delta_missing": sorted(expected_delta - set(plan["review"]["delta_entity_ids"])),
        "plan_delta_extra": sorted(set(plan["review"]["delta_entity_ids"]) - expected_delta),
    }
    check("exact-delta-review-set", not any(review_detail.values()), review_detail, "delta-review-drift")
    preservation_errors = _preservation_errors(staging, plan["preservation"]["mutable_files"])
    actual_layers = _layer_inventory(staging, plan["preservation"]["mutable_files"])
    expected_layers = plan["preservation"]["origin_layers"]
    check(
        "mutable-layers-preserved",
        not preservation_errors and actual_layers == expected_layers,
        {"errors": preservation_errors, "expected": expected_layers, "actual": actual_layers},
        "mutable-layer-loss",
    )
    pending = [item["id"] for item in build_state.get("review_packs", []) if item.get("status") != "passed"]
    check("delta-reviews-complete", not pending, pending, "review-pending")
    final_result: dict[str, Any] | None = None
    if not pending and all(item["passed"] for item in checks):
        try:
            final_result = finalize(staging)
        except CkbError as exc:
            check("global-finalize", False, str(exc), "global-audit")
        else:
            check("global-finalize", final_result.get("status") == "complete", final_result.get("global_audit"), "global-audit")
    else:
        check("global-finalize", False, "blocked by earlier extension checks", "blocked")
    global_audit = json_load(staging / "audit/global.json") if (staging / "audit/global.json").is_file() else {}
    check("global-audit-passed", global_audit.get("status") == "passed", global_audit.get("status"), "global-audit")
    sqlite_checks = _sqlite_checks(staging)
    check("sqlite-integrity-and-foreign-keys", bool(sqlite_checks) and all(item["passed"] for item in sqlite_checks), sqlite_checks, "sqlite-integrity")
    from .llm_wiki_capabilities import maintenance_check

    maintenance = maintenance_check(staging) if global_audit.get("status") == "passed" else {"status": "blocked"}
    _release_audit_handles()
    check("maintain", maintenance.get("status") == "passed", maintenance, "maintain")
    passed = all(item["passed"] for item in checks)
    result = {
        "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
        "operation_id": state["operation_id"],
        "status": "ready" if passed else "failed",
        "checks": checks,
        "counts": {"passed": sum(item["passed"] for item in checks), "total": len(checks)},
        "sqlite": sqlite_checks,
        "maintenance_status": maintenance.get("status"),
    }
    json_write(staging / AUDIT_RELATIVE, result)
    if passed:
        state["status"] = "ready"
        plan["status"] = "ready"
        json_write(staging / STATE_RELATIVE, state)
        json_write(staging / PLAN_RELATIVE, plan)
        build_state = json_load(staging / "state.json")
        build_state["scope_extension"] = {**build_state.get("scope_extension", {}), "status": "ready"}
        json_write(staging / "state.json", build_state)
    return result


def _control_path(output: Path, operation_id: str) -> Path:
    return output.parent / f".{output.name}.scope-extension-{operation_id}.json"


def cutover_scope_extension(staging: Path, *, fault: str | None = None) -> dict[str, Any]:
    staging = staging.resolve()
    state = _load_extension_state(staging)
    audit = json_load(staging / AUDIT_RELATIVE) if (staging / AUDIT_RELATIVE).is_file() else {}
    if state.get("status") != "ready" or audit.get("status") != "ready":
        raise _error("not-ready", "scope extension audit has not marked staging ready")
    output = Path(state["previous_output"]).resolve()
    if path_inside(staging, output) or path_inside(output, staging):
        raise _error("overlapping-output", "staging and production OUTPUT overlap")
    plan = json_load(staging / PLAN_RELATIVE)
    expected_origin = plan["preservation"]["origin_manifest"]
    actual_origin = _tree_manifest(output)
    if not _same_manifest(expected_origin, actual_origin):
        raise _error("origin-drift", "production OUTPUT changed after scope extension start")
    repository_state = preflight(Path(state["repository"]))
    if repository_state["commit"] != state["repository_commit"]:
        raise _error("target-drift", "target repository commit changed before cutover")
    operation_id = state["operation_id"]
    backup = output.parent / f".{output.name}.scope-extension-backup-{operation_id}"
    control_path = _control_path(output, operation_id)
    selection = _control_selection(output, actual_origin) if list(output.parent.glob(f".{output.name}.scope-extension-*.json")) else {"active": None}
    parent = selection.get("active")
    parent_record = parent[1] if parent else None
    previous_attempts: list[dict[str, Any]] = []
    if control_path.is_file() and not backup.exists():
        existing = json_load(control_path)
        if existing.get("status") == "cutover-failed-restored":
            previous_attempts = list(existing.get("attempts") or [])
            previous_attempts.append(
                {
                    "status": existing["status"],
                    "failure": existing.get("failure"),
                    "origin_restored": existing.get("origin_restored"),
                }
            )
        else:
            raise _error("cutover-conflict", "cutover control record already exists in a non-retryable state")
    if backup.exists():
        raise _error("cutover-conflict", "cutover backup or control record already exists")
    record = {
        "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
        "operation_id": operation_id,
        "status": "cutover-started",
        "parent_operation_id": parent_record.get("operation_id") if parent_record else None,
        "chain_depth": int(parent_record.get("chain_depth", 0)) + 1 if parent_record else 1,
        "output": str(output),
        "staging_output": str(staging),
        "backup_output": str(backup),
        "repository": state["repository"],
        "repository_commit": state["repository_commit"],
        "origin_manifest": expected_origin,
        "attempts": previous_attempts,
    }
    json_write(control_path, record)
    moved_staging = False
    try:
        # Some audit helpers use sqlite3 connection context managers whose
        # objects close only when released.  Collect before Windows directory
        # renames so verified databases do not retain transient file handles.
        _release_audit_handles()
        output.rename(backup)
        if fault == "after-backup-rename":
            raise OSError("injected failure after backup rename")
        backup_manifest = _tree_manifest(backup)
        if not _same_manifest(expected_origin, backup_manifest):
            raise _error("backup-verification", "renamed backup does not match the verified origin manifest")
        staging.rename(output)
        moved_staging = True
        if fault == "after-staging-rename":
            raise OSError("injected failure after staging rename")
        pipeline_status(output)
        sqlite_checks = _sqlite_checks(output)
        if not sqlite_checks or not all(item["passed"] for item in sqlite_checks):
            raise _error("cutover-verification", f"promoted SQLite verification failed: {sqlite_checks}")
        modified_manifest = _tree_manifest(output)
        record.update({
            "status": "cutover-complete",
            "backup_manifest": backup_manifest,
            "modified_manifest": modified_manifest,
            "sqlite": sqlite_checks,
        })
        json_write(control_path, record)
        return {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "status": "cutover-complete",
            "operation_id": operation_id,
            "parent_operation_id": record["parent_operation_id"],
            "chain_depth": record["chain_depth"],
            "output": str(output),
            "backup_output": str(backup),
            "control": str(control_path),
            "sqlite": sqlite_checks,
        }
    except Exception as exc:
        try:
            if moved_staging and output.exists():
                output.rename(staging)
            if backup.exists() and not output.exists():
                backup.rename(output)
        finally:
            restored = output.is_dir() and _same_manifest(expected_origin, _tree_manifest(output))
            record.update({"status": "cutover-failed-restored" if restored else "cutover-failed", "failure": str(exc), "origin_restored": restored})
            json_write(control_path, record)
        if isinstance(exc, CkbError):
            raise
        raise _error("cutover-failed", str(exc)) from exc


def _active_control(output: Path) -> tuple[Path, dict[str, Any]]:
    selection = _control_selection(output)
    if selection["active"]:
        return selection["active"]
    rolled_back = selection["rolled_back_matches"]
    if len(rolled_back) == 1:
        value = rolled_back[0][1]
        value["idempotent_selection"] = True
        return rolled_back[0][0], value
    if len(rolled_back) > 1:
        raise _error("control-record", f"no active cutover; multiple rolled-back operations match current OUTPUT: {[item[1]['operation_id'] for item in rolled_back]}")
    raise _error("control-record", "no active cutover matches current OUTPUT")


def rollback_scope_extension(output: Path, *, fault: str | None = None) -> dict[str, Any]:
    output = output.resolve()
    control_path, record = _active_control(output)
    if record.get("status") == "rolled-back":
        actual = _tree_manifest(output)
        if not _same_manifest(record["origin_manifest"], actual):
            raise _error("rollback-drift", "rolled-back OUTPUT no longer matches its origin manifest")
        return {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "status": "rolled-back",
            "operation_id": record["operation_id"],
            "reactivated_operation_id": None,
            "output": str(output),
            "idempotent": True,
        }
    actual_modified = _tree_manifest(output)
    if not _same_manifest(record["modified_manifest"], actual_modified):
        raise _error("modified-drift", "promoted OUTPUT changed after cutover; rollback guard stopped replacement")
    backup = Path(record["backup_output"])
    if not backup.is_dir() or not _same_manifest(record["origin_manifest"], _tree_manifest(backup)):
        raise _error("backup-verification", "cutover backup is missing or changed")
    rolled_forward = output.parent / f".{output.name}.scope-extension-modified-{record['operation_id']}"
    if rolled_forward.exists():
        raise _error("rollback-conflict", f"rollback quarantine already exists: {rolled_forward}")
    restored_origin = False
    try:
        _release_audit_handles()
        output.rename(rolled_forward)
        if fault == "after-modified-rename":
            raise OSError("injected failure after modified rename")
        backup.rename(output)
        restored_origin = True
        if fault == "after-backup-restore":
            raise OSError("injected failure after backup restore")
        restored = _tree_manifest(output)
        if not _same_manifest(record["origin_manifest"], restored):
            raise _error("rollback-verification", "restored OUTPUT differs from the pre-cutover byte manifest")
        sqlite_checks = _sqlite_checks(output)
        if not sqlite_checks or not all(item["passed"] for item in sqlite_checks):
            raise _error("rollback-sqlite", f"restored SQLite verification failed: {sqlite_checks}")
        parent_operation_id = record.get("parent_operation_id")
        if parent_operation_id:
            parent_matches = [
                value
                for _path, value in _control_records(output)
                if value.get("operation_id") == parent_operation_id
            ]
            if len(parent_matches) != 1 or parent_matches[0].get("status") != "cutover-complete" or not _same_manifest(parent_matches[0].get("modified_manifest", {}), restored):
                raise _error("rollback-parent", "restored OUTPUT does not match the recorded parent cutover")
        record.update({
            "status": "rolled-back",
            "rolled_forward_output": str(rolled_forward),
            "restored_manifest": restored,
            "rollback_sqlite": sqlite_checks,
            "reactivated_operation_id": parent_operation_id,
        })
        json_write(control_path, record)
        selected_after = _control_selection(output, restored)["active"]
        actual_reactivated = selected_after[1]["operation_id"] if selected_after else None
        if actual_reactivated != parent_operation_id:
            raise _error("rollback-parent", f"active parent mismatch after rollback: expected {parent_operation_id}, got {actual_reactivated}")
        return {
            "schema_version": SCOPE_EXTENSION_SCHEMA_VERSION,
            "status": "rolled-back",
            "operation_id": record["operation_id"],
            "reactivated_operation_id": parent_operation_id,
            "output": str(output),
            "modified_output": str(rolled_forward),
            "control": str(control_path),
            "sqlite": sqlite_checks,
        }
    except Exception as exc:
        try:
            if restored_origin and output.exists():
                output.rename(backup)
            if rolled_forward.exists() and not output.exists():
                rolled_forward.rename(output)
        finally:
            restored_modified = output.is_dir() and _same_manifest(record["modified_manifest"], _tree_manifest(output))
            record.update({
                "status": "cutover-complete" if restored_modified else "rollback-failed",
                "last_rollback_failure": str(exc),
                "modified_restored": restored_modified,
            })
            json_write(control_path, record)
        if isinstance(exc, CkbError):
            raise
        raise _error("rollback-failed", str(exc)) from exc

"""Session-owned supervisor for the local CKB JSONL stdio server.

The short-lived Harness adapters never pretend to own a session process.  A
real CKB request starts one supervisor for a bounded lifecycle key; that
supervisor owns the stdio child, its pipes and reader threads until an explicit
session close or a reliable Harness parent PID disappears.
"""

from __future__ import annotations

from dataclasses import dataclass
import hashlib
import json
import os
from pathlib import Path
import queue
import shutil
import signal
import sqlite3
import subprocess
import sys
import threading
import time
from typing import Any, TextIO
import uuid

from .common import CkbError, background_process_options, json_load, json_write, utc_now
from .stdio_server import STDIO_RETRIEVAL_PROTOCOL, STDIO_RETRIEVAL_PROTOCOL_VERSION


SESSION_STDIO_SCHEMA_VERSION = 1
DEFAULT_START_TIMEOUT_SECONDS = 15.0
DEFAULT_REQUEST_TIMEOUT_SECONDS = 45.0
DEFAULT_CLOSE_TIMEOUT_SECONDS = 8.0
POLL_SECONDS = 0.025
WINDOWS_MAX_PATH_CHARS = 259
# The longest compact generated relative path is
# ``responses/<16-hex>.json.tmp`` (36 characters including separators).
# 223 + 36 = 259, the non-prefixed Windows path ceiling observed by the
# locked runtime.  Longer roots return an explicit structured fallback.
WINDOWS_LIFECYCLE_DIRECTORY_CHARS = 223
_FORBIDDEN_STATE_KEYS = {
    "prompt",
    "assistant",
    "assistant_message",
    "cookie",
    "credential",
    "password",
    "secret",
    "token",
    "transcript",
    "tool_input",
}


class _StartGate:
    def __init__(self) -> None:
        self.lock = threading.Lock()
        self.users = 0


_START_GATES_GUARD = threading.Lock()
_START_GATES: dict[str, _StartGate] = {}


def _retain_start_gate(key: str) -> _StartGate:
    with _START_GATES_GUARD:
        gate = _START_GATES.get(key)
        if gate is None:
            gate = _StartGate()
            _START_GATES[key] = gate
        gate.users += 1
        return gate


def _release_start_gate(key: str, gate: _StartGate) -> None:
    with _START_GATES_GUARD:
        gate.users -= 1
        if gate.users == 0 and _START_GATES.get(key) is gate:
            _START_GATES.pop(key, None)


def default_session_stdio_root() -> Path:
    configured = os.environ.get("CKB_SESSION_STDIO_ROOT")
    return (Path(configured).expanduser() if configured else Path.home() / ".ckb" / "session-stdio").resolve()


def _path_identity(path: Path | str) -> str:
    value = str(Path(path).expanduser().resolve()).replace("\\", "/").rstrip("/")
    return value.casefold() if os.name == "nt" else value


def _digest(*values: object) -> str:
    text = "\0".join(str(value) for value in values)
    return hashlib.sha256(text.encode("utf-8", errors="strict")).hexdigest()


def session_digest(session_id: str) -> str:
    value = session_id.strip()
    if not value:
        raise CkbError("session stdio requires a non-empty session id")
    return _digest("session", value)


def lifecycle_key(
    harness: str,
    session_id: str,
    output: Path,
    *,
    executable: Path | None = None,
    ckb: Path | None = None,
) -> str:
    python_value = executable or Path(sys.executable)
    ckb_value = ckb or Path(__file__).resolve().parents[1] / "ckb.py"
    identity = _digest(
        _path_identity(python_value),
        _path_identity(ckb_value),
        STDIO_RETRIEVAL_PROTOCOL,
        STDIO_RETRIEVAL_PROTOCOL_VERSION,
    )
    return "stdio-" + _digest(harness.strip().casefold(), session_digest(session_id), _path_identity(output), identity)


def _lifecycle_directory(root: Path, key: str) -> Path:
    return root.resolve() / key


def _lease_path(directory: Path) -> Path:
    return directory / "lease.json"


def _read_json(path: Path) -> dict[str, Any] | None:
    try:
        value = json_load(path)
        return value if isinstance(value, dict) else None
    except (FileNotFoundError, json.JSONDecodeError, OSError):
        return None


def _validate_lifecycle_path_budget(directory: Path) -> dict[str, int]:
    characters = len(str(directory))
    if os.name == "nt" and characters > WINDOWS_LIFECYCLE_DIRECTORY_CHARS:
        raise CkbError(
            "session stdio lifecycle path budget exceeded: "
            f"directory_chars={characters}; directory_limit={WINDOWS_LIFECYCLE_DIRECTORY_CHARS}; "
            f"generated_path_limit={WINDOWS_MAX_PATH_CHARS}"
        )
    return {
        "directory_chars": characters,
        "directory_limit": WINDOWS_LIFECYCLE_DIRECTORY_CHARS,
        "generated_path_limit": WINDOWS_MAX_PATH_CHARS,
    }


def _write_lease(directory: Path, value: dict[str, Any], timeout: float = 3.0) -> None:
    """Replace lease state despite short Windows reader sharing conflicts."""

    path = _lease_path(directory)
    path.parent.mkdir(parents=True, exist_ok=True)
    _validate_lifecycle_path_budget(directory)
    temporary: Path | None = None
    for _attempt in range(32):
        candidate = directory / f".l{uuid.uuid4().hex[:6]}"
        try:
            with candidate.open("x", encoding="utf-8", newline="\n") as stream:
                stream.write(json.dumps(value, ensure_ascii=False, indent=2) + "\n")
            temporary = candidate
            break
        except FileExistsError:
            continue
    if temporary is None:
        raise CkbError("session stdio could not allocate a compact lease temporary file")
    deadline = time.monotonic() + timeout
    try:
        while True:
            try:
                os.replace(temporary, path)
                return
            except OSError as exc:
                sharing_conflict = os.name == "nt" and getattr(exc, "winerror", None) in {5, 32}
                if not sharing_conflict or time.monotonic() >= deadline:
                    raise
                time.sleep(POLL_SECONDS)
    finally:
        temporary.unlink(missing_ok=True)


def pid_exists(pid: int | None) -> bool:
    if not isinstance(pid, int) or pid <= 0:
        return False
    if pid == os.getpid():
        return True
    if os.name == "nt":
        try:
            import ctypes
            from ctypes import wintypes

            handle = ctypes.windll.kernel32.OpenProcess(0x00100000 | 0x1000, False, pid)
            if not handle:
                return False
            try:
                exit_code = wintypes.DWORD()
                if not ctypes.windll.kernel32.GetExitCodeProcess(handle, ctypes.byref(exit_code)):
                    return False
                return int(exit_code.value) == 259  # STILL_ACTIVE
            finally:
                ctypes.windll.kernel32.CloseHandle(handle)
        except Exception:
            return False
    try:
        os.kill(pid, 0)
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError:
        return False
    return True


def _force_terminate_pid(pid: int) -> bool:
    if not pid_exists(pid):
        return True
    if os.name == "nt":
        try:
            import ctypes

            process = ctypes.windll.kernel32.OpenProcess(0x0001 | 0x00100000, False, pid)
            if not process:
                return not pid_exists(pid)
            try:
                ctypes.windll.kernel32.TerminateProcess(process, 143)
                ctypes.windll.kernel32.WaitForSingleObject(process, 3000)
            finally:
                ctypes.windll.kernel32.CloseHandle(process)
            return not pid_exists(pid)
        except Exception:
            return False
    try:
        os.kill(pid, signal.SIGTERM)
    except ProcessLookupError:
        return True
    deadline = time.monotonic() + 2.0
    while pid_exists(pid) and time.monotonic() < deadline:
        time.sleep(POLL_SECONDS)
    if pid_exists(pid):
        try:
            os.kill(pid, signal.SIGKILL)
        except ProcessLookupError:
            pass
    return not pid_exists(pid)


def process_metrics(pid: int | None = None) -> dict[str, Any]:
    """Return RSS and handle counts using only the locked runtime's stdlib."""

    process_id = int(pid or os.getpid())
    if os.name == "nt":
        import ctypes
        from ctypes import wintypes

        class PROCESS_MEMORY_COUNTERS(ctypes.Structure):
            _fields_ = [
                ("cb", wintypes.DWORD),
                ("PageFaultCount", wintypes.DWORD),
                ("PeakWorkingSetSize", ctypes.c_size_t),
                ("WorkingSetSize", ctypes.c_size_t),
                ("QuotaPeakPagedPoolUsage", ctypes.c_size_t),
                ("QuotaPagedPoolUsage", ctypes.c_size_t),
                ("QuotaPeakNonPagedPoolUsage", ctypes.c_size_t),
                ("QuotaNonPagedPoolUsage", ctypes.c_size_t),
                ("PagefileUsage", ctypes.c_size_t),
                ("PeakPagefileUsage", ctypes.c_size_t),
            ]

        handle = ctypes.windll.kernel32.OpenProcess(0x0400 | 0x0010, False, process_id)
        if not handle:
            raise CkbError(f"session stdio metrics cannot open process: pid={process_id}")
        try:
            counters = PROCESS_MEMORY_COUNTERS()
            counters.cb = ctypes.sizeof(counters)
            if not ctypes.windll.psapi.GetProcessMemoryInfo(handle, ctypes.byref(counters), counters.cb):
                raise CkbError(f"session stdio RSS metric is unavailable: pid={process_id}")
            count = wintypes.DWORD()
            if not ctypes.windll.kernel32.GetProcessHandleCount(handle, ctypes.byref(count)):
                raise CkbError(f"session stdio handle metric is unavailable: pid={process_id}")
            return {
                "pid": process_id,
                "rss_bytes": int(counters.WorkingSetSize),
                "handles": int(count.value),
                "source": "windows-kernel32-psapi",
            }
        finally:
            ctypes.windll.kernel32.CloseHandle(handle)
    status = Path(f"/proc/{process_id}/status")
    handles = Path(f"/proc/{process_id}/fd")
    if not status.is_file() or not handles.is_dir():
        raise CkbError(f"session stdio process metrics are unavailable: pid={process_id}")
    rss_line = next((line for line in status.read_text(encoding="utf-8").splitlines() if line.startswith("VmRSS:")), None)
    if rss_line is None:
        raise CkbError(f"session stdio RSS metric is unavailable: pid={process_id}")
    rss_bytes = int(rss_line.split()[1]) * 1024
    return {"pid": process_id, "rss_bytes": rss_bytes, "handles": len(list(handles.iterdir())), "source": "procfs"}


def _state_counts(
    *,
    lease: int,
    process: int,
    pending: int,
    readers: int,
    pipes: int,
) -> dict[str, int]:
    return {
        "active_leases": lease,
        "processes": process,
        "pending_requests": pending,
        "reader_threads": readers,
        "timers": 0,
        "listeners": 0,
        "pipes": pipes,
        "session_mappings": lease,
        "cache_references": lease,
    }


def _base_lease(
    *,
    key: str,
    harness: str,
    opaque_session: str,
    output: Path,
    executable: Path,
    ckb: Path,
    parent_pid: int | None,
    generation: str,
) -> dict[str, Any]:
    stamp = utc_now()
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "lifecycle_key": key,
        "generation": generation,
        "harness": harness.strip().casefold(),
        "session_digest": opaque_session,
        "output": str(output.resolve()),
        "state": "starting",
        "supervisor_pid": os.getpid(),
        "server_pid": None,
        "protocol": STDIO_RETRIEVAL_PROTOCOL,
        "protocol_version": STDIO_RETRIEVAL_PROTOCOL_VERSION,
        "executable_identity": _digest(_path_identity(executable), _path_identity(ckb)),
        "parent_pid": parent_pid,
        "parent_monitor": "pid" if parent_pid else "unavailable",
        "created_at_utc": stamp,
        "last_used_at_utc": stamp,
        "closed_at_utc": None,
        "fallback": {"active": False, "reason": None},
        "close_reason": None,
        "object_counts": _state_counts(lease=1, process=0, pending=0, readers=0, pipes=0),
    }


class _Reader(threading.Thread):
    def __init__(self, stream: TextIO, destination: queue.Queue[str] | list[str], name: str) -> None:
        super().__init__(name=name, daemon=False)
        self.stream = stream
        self.destination = destination

    def run(self) -> None:
        try:
            for line in self.stream:
                if isinstance(self.destination, queue.Queue):
                    self.destination.put(line)
                elif len(self.destination) < 200:
                    self.destination.append(line.rstrip("\r\n")[:2000])
        finally:
            if isinstance(self.destination, queue.Queue):
                self.destination.put("")


@dataclass
class _Transport:
    executable: Path
    ckb: Path
    output: Path
    process: subprocess.Popen[str] | None = None
    stdout_queue: queue.Queue[str] | None = None
    stdout_reader: _Reader | None = None
    stderr_reader: _Reader | None = None
    stderr_lines: list[str] | None = None
    pending: int = 0

    def start(self, timeout: float) -> dict[str, Any]:
        command = [str(self.executable), "-X", "utf8", str(self.ckb), "serve", "--stdio", "--out", str(self.output)]
        self.process = subprocess.Popen(
            command,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            encoding="utf-8",
            errors="strict",
            bufsize=1,
            **background_process_options(),
        )
        assert self.process.stdout is not None and self.process.stderr is not None
        self.stdout_queue = queue.Queue()
        self.stderr_lines = []
        self.stdout_reader = _Reader(self.process.stdout, self.stdout_queue, "ckb-stdio-stdout")
        self.stderr_reader = _Reader(self.process.stderr, self.stderr_lines, "ckb-stdio-stderr")
        self.stdout_reader.start()
        self.stderr_reader.start()
        response = self.request({"id": "handshake", "method": "ping"}, timeout)
        result = response.get("result") if response.get("ok") else None
        if not isinstance(result, dict):
            raise CkbError("session stdio handshake did not return a result")
        if result.get("protocol") != STDIO_RETRIEVAL_PROTOCOL:
            raise CkbError("session stdio handshake protocol mismatch")
        if result.get("protocol_version") != STDIO_RETRIEVAL_PROTOCOL_VERSION:
            raise CkbError("session stdio handshake protocol version mismatch")
        if _path_identity(result.get("output", "")) != _path_identity(self.output):
            raise CkbError("session stdio handshake output mismatch")
        return response

    def request(self, request: dict[str, Any], timeout: float) -> dict[str, Any]:
        if self.process is None or self.process.poll() is not None:
            raise CkbError("session stdio child is not running")
        if self.process.stdin is None or self.stdout_queue is None:
            raise CkbError("session stdio child pipes are unavailable")
        self.pending += 1
        try:
            self.process.stdin.write(json.dumps(request, ensure_ascii=True, separators=(",", ":")) + "\n")
            self.process.stdin.flush()
            deadline = time.monotonic() + timeout
            while True:
                remaining = deadline - time.monotonic()
                if remaining <= 0:
                    raise CkbError("session stdio response timeout")
                try:
                    line = self.stdout_queue.get(timeout=min(remaining, 0.1))
                except queue.Empty:
                    if self.process.poll() is not None:
                        raise CkbError("session stdio stdout closed before a response")
                    continue
                if not line:
                    raise CkbError("session stdio stdout reached EOF")
                try:
                    response = json.loads(line)
                except json.JSONDecodeError as exc:
                    raise CkbError("session stdio returned invalid JSON") from exc
                if not isinstance(response, dict) or response.get("id") != request.get("id"):
                    raise CkbError("session stdio response id mismatch")
                return response
        finally:
            self.pending -= 1

    def close(self, timeout: float) -> dict[str, Any]:
        process = self.process
        escalation = "already-exited"
        if process is not None and process.poll() is None:
            try:
                response = self.request({"id": "shutdown", "method": "shutdown"}, min(timeout, 2.0))
                escalation = "shutdown" if response.get("ok") else "shutdown-error"
            except Exception:
                escalation = "shutdown-error"
            try:
                process.wait(timeout=max(0.2, timeout / 2))
            except subprocess.TimeoutExpired:
                process.terminate()
                escalation = "terminate"
                try:
                    process.wait(timeout=max(0.2, timeout / 3))
                except subprocess.TimeoutExpired:
                    process.kill()
                    escalation = "kill"
                    process.wait(timeout=max(0.2, timeout / 3))
        if process is not None:
            for stream in (process.stdin, process.stdout, process.stderr):
                if stream is not None:
                    try:
                        stream.close()
                    except OSError:
                        pass
        for reader in (self.stdout_reader, self.stderr_reader):
            if reader is not None:
                reader.join(timeout=2.0)
        exit_code = process.returncode if process is not None else None
        pid = process.pid if process is not None else None
        stderr = list(self.stderr_lines or [])[-20:]
        self.process = None
        self.stdout_queue = None
        self.stdout_reader = None
        self.stderr_reader = None
        self.stderr_lines = None
        self.pending = 0
        return {"escalation": escalation, "server_pid": pid, "exit_code": exit_code, "stderr": stderr}


def _write_response(directory: Path, token: str, value: dict[str, Any]) -> None:
    json_write(directory / "responses" / f"{token}.json", value)


def _clear_transient(directory: Path) -> None:
    for name in ("requests", "responses", "control"):
        current = directory / name
        if not current.is_dir():
            continue
        for path in current.iterdir():
            try:
                if path.is_file():
                    path.unlink()
                elif path.is_dir():
                    shutil.rmtree(path)
            except OSError:
                pass


def controller_main(
    *,
    root: Path,
    key: str,
    harness: str,
    opaque_session: str,
    output: Path,
    executable: Path,
    ckb: Path,
    parent_pid: int | None,
    generation: str,
    start_timeout: float = DEFAULT_START_TIMEOUT_SECONDS,
    close_timeout: float = DEFAULT_CLOSE_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    directory = _lifecycle_directory(root, key)
    path_budget = _validate_lifecycle_path_budget(directory)
    for name in ("requests", "responses", "control"):
        (directory / name).mkdir(parents=True, exist_ok=True)
    lease = _base_lease(
        key=key,
        harness=harness,
        opaque_session=opaque_session,
        output=output,
        executable=executable,
        ckb=ckb,
        parent_pid=parent_pid,
        generation=generation,
    )
    lease["path_budget"] = path_budget
    _write_lease(directory, lease)
    transport = _Transport(executable=executable, ckb=ckb, output=output)
    close_reason = "controller-stop"
    restart_budget = 1
    try:
        try:
            transport.start(start_timeout)
        except Exception as exc:
            close_info = transport.close(close_timeout)
            lease.update(
                {
                    "state": "fallback",
                    "fallback": {"active": True, "reason": f"startup:{type(exc).__name__}:{str(exc)[:300]}"},
                    "server_pid": None,
                    "object_counts": _state_counts(lease=1, process=0, pending=0, readers=0, pipes=0),
                    "close_detail": close_info,
                    "last_used_at_utc": utc_now(),
                }
            )
            _write_lease(directory, lease)
            return lease
        assert transport.process is not None
        lease.update(
            {
                "state": "ready",
                "server_pid": transport.process.pid,
                "object_counts": _state_counts(lease=1, process=1, pending=0, readers=2, pipes=3),
                "last_used_at_utc": utc_now(),
            }
        )
        _write_lease(directory, lease)
        while True:
            if parent_pid and not pid_exists(parent_pid):
                close_reason = "parent-death"
                break
            controls = sorted((directory / "control").glob("*.json"))
            if controls:
                control = _read_json(controls[0]) or {}
                close_reason = str(control.get("reason") or "explicit-close")[:120]
                break
            request_paths = sorted((directory / "requests").glob("*.json"))
            if not request_paths:
                time.sleep(POLL_SECONDS)
                continue
            request_path = request_paths[0]
            envelope = _read_json(request_path)
            if envelope is None:
                try:
                    request_path.unlink()
                except OSError:
                    pass
                continue
            token = str(envelope.get("request_token") or request_path.stem)
            request = envelope.get("request")
            if not isinstance(request, dict):
                _write_response(directory, token, {"status": "failed", "reason": "invalid-request-envelope"})
                request_path.unlink(missing_ok=True)
                continue
            lease["object_counts"] = _state_counts(lease=1, process=1, pending=1, readers=2, pipes=3)
            lease["last_used_at_utc"] = utc_now()
            _write_lease(directory, lease)
            response_value: dict[str, Any]
            try:
                response = transport.request(request, float(envelope.get("timeout_seconds") or DEFAULT_REQUEST_TIMEOUT_SECONDS))
                response_value = {
                    "schema_version": SESSION_STDIO_SCHEMA_VERSION,
                    "status": "passed" if response.get("ok") else "failed",
                    "mode": "resident-stdio",
                    "resident": True,
                    "lifecycle_key": key,
                    "generation": lease.get("generation"),
                    "supervisor_pid": os.getpid(),
                    "server_pid": transport.process.pid if transport.process else None,
                    "response": response,
                    "fallback": {"active": False, "reason": None},
                }
            except Exception as first_exc:
                response_value = {}
                if restart_budget > 0:
                    restart_budget -= 1
                    transport.close(close_timeout)
                    try:
                        transport.start(start_timeout)
                        assert transport.process is not None
                        lease["server_pid"] = transport.process.pid
                        response = transport.request(request, float(envelope.get("timeout_seconds") or DEFAULT_REQUEST_TIMEOUT_SECONDS))
                        response_value = {
                            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
                            "status": "passed" if response.get("ok") else "failed",
                            "mode": "resident-stdio",
                            "resident": True,
                            "lifecycle_key": key,
                            "generation": lease.get("generation"),
                            "supervisor_pid": os.getpid(),
                            "server_pid": transport.process.pid,
                            "response": response,
                            "fallback": {"active": False, "reason": None},
                            "restart_count": 1,
                        }
                    except Exception as second_exc:
                        response_value = {
                            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
                            "status": "transport-failed",
                            "mode": "cli-fallback-required",
                            "resident": False,
                            "lifecycle_key": key,
                            "supervisor_pid": os.getpid(),
                            "server_pid": None,
                            "fallback": {
                                "active": True,
                                "reason": f"request:{type(first_exc).__name__}:{str(first_exc)[:160]}; restart:{type(second_exc).__name__}:{str(second_exc)[:160]}",
                            },
                        }
                if not response_value:
                    response_value = {
                        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
                        "status": "transport-failed",
                        "mode": "cli-fallback-required",
                        "resident": False,
                        "lifecycle_key": key,
                        "supervisor_pid": os.getpid(),
                        "server_pid": None,
                        "fallback": {"active": True, "reason": f"request:{type(first_exc).__name__}:{str(first_exc)[:300]}"},
                    }
            _write_response(directory, token, response_value)
            request_path.unlink(missing_ok=True)
            if response_value.get("status") == "transport-failed":
                lease["fallback"] = response_value["fallback"]
                close_reason = "transport-failed"
                break
            lease["object_counts"] = _state_counts(lease=1, process=1, pending=0, readers=2, pipes=3)
            lease["last_used_at_utc"] = utc_now()
            _write_lease(directory, lease)
    finally:
        lease["state"] = "closing"
        lease["close_reason"] = close_reason
        lease["object_counts"] = _state_counts(
            lease=1,
            process=1 if transport.process and transport.process.poll() is None else 0,
            pending=transport.pending,
            readers=sum(reader is not None for reader in (transport.stdout_reader, transport.stderr_reader)),
            pipes=3 if transport.process else 0,
        )
        _write_lease(directory, lease)
        close_detail = transport.close(close_timeout)
        lease.update(
            {
                "state": "closed",
                "server_pid": None,
                # Retain the supervisor PID until another process observes
                # that it has really exited; cleanup then clears the reference.
                "supervisor_pid": os.getpid(),
                "closed_at_utc": utc_now(),
                "last_used_at_utc": utc_now(),
                "close_detail": close_detail,
                "object_counts": _state_counts(lease=0, process=0, pending=0, readers=0, pipes=0),
            }
        )
        _write_lease(directory, lease)
        for path in (directory / "requests").glob("*.json"):
            envelope = _read_json(path) or {}
            token = str(envelope.get("request_token") or path.stem)
            _write_response(
                directory,
                token,
                {
                    "schema_version": SESSION_STDIO_SCHEMA_VERSION,
                    "status": "transport-failed",
                    "mode": "cli-fallback-required",
                    "resident": False,
                    "lifecycle_key": key,
                    "fallback": {"active": True, "reason": f"closed:{close_reason}"},
                },
            )
            path.unlink(missing_ok=True)
    return lease


def _supervisor_process_options() -> dict[str, Any]:
    if os.name == "nt":
        flags = getattr(subprocess, "CREATE_NO_WINDOW", 0) | getattr(subprocess, "CREATE_NEW_PROCESS_GROUP", 0)
        return {"creationflags": flags} if flags else {}
    return {"start_new_session": True}


def _reap_supervisor(process: subprocess.Popen[Any]) -> None:
    try:
        process.wait()
    except OSError:
        pass


def _acquire_start_lock(directory: Path, timeout: float) -> Any | None:
    lock = directory / "start.lock"
    deadline = time.monotonic() + timeout
    while time.monotonic() < deadline:
        handle = lock.open("a+b")
        try:
            if lock.stat().st_size == 0:
                handle.write(b"0")
                handle.flush()
            handle.seek(0)
            if os.name == "nt":
                import msvcrt

                msvcrt.locking(handle.fileno(), msvcrt.LK_NBLCK, 1)
            else:
                import fcntl

                fcntl.flock(handle.fileno(), fcntl.LOCK_EX | fcntl.LOCK_NB)
            handle.seek(0)
            handle.write(
                json.dumps({"pid": os.getpid(), "created_at_utc": utc_now()}, separators=(",", ":")).encode("utf-8")
            )
            handle.truncate()
            handle.flush()
            return handle
        except OSError:
            handle.close()
            time.sleep(POLL_SECONDS)
    return None


def _release_start_lock(lock: Any | None) -> None:
    if lock is not None and not lock.closed:
        try:
            lock.seek(0)
            if os.name == "nt":
                import msvcrt

                msvcrt.locking(lock.fileno(), msvcrt.LK_UNLCK, 1)
            else:
                import fcntl

                fcntl.flock(lock.fileno(), fcntl.LOCK_UN)
        except OSError:
            pass
        finally:
            lock.close()


def _active_lease(directory: Path) -> dict[str, Any] | None:
    lease = _read_json(_lease_path(directory))
    if not lease:
        return None
    # The supervisor owns child health and the one permitted restart.  A dead
    # server with a live ready supervisor is therefore still the active lease;
    # clients must queue the request instead of racing a second supervisor.
    if lease.get("state") == "ready" and (
        pid_exists(lease.get("supervisor_pid")) or pid_exists(lease.get("server_pid"))
    ):
        return lease
    return None


def activate_session_stdio(
    *,
    harness: str,
    session_id: str,
    output: Path,
    root: Path | None = None,
    executable: Path | None = None,
    ckb: Path | None = None,
    parent_pid: int | None = None,
    start_timeout: float = DEFAULT_START_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    """Start and handshake the lifecycle at the first exact Skill application."""

    output_value = output.expanduser().resolve()
    executable_value = (executable or Path(sys.executable)).expanduser().resolve()
    ckb_value = (ckb or Path(__file__).resolve().parents[1] / "ckb.py").expanduser().resolve()
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    normalized_harness = harness.strip().casefold()
    opaque_session = session_digest(session_id)
    key = lifecycle_key(normalized_harness, session_id, output_value, executable=executable_value, ckb=ckb_value)
    if not (output_value / "machine" / "knowledge.sqlite").is_file():
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "fallback",
            "mode": "cli-fallback",
            "resident": False,
            "created": False,
            "lifecycle_key": key,
            "generation": None,
            "supervisor_pid": None,
            "server_pid": None,
            "protocol": None,
            "protocol_version": None,
            "parent_monitor": "pid" if parent_pid else "unavailable",
            "fallback": {"active": True, "reason": "startup:machine-knowledge-missing"},
        }
    directory = _lifecycle_directory(root_value, key)
    root_value.mkdir(parents=True, exist_ok=True)
    try:
        lease = _active_lease(directory)
        created = lease is None
        if lease is None:
            lease = _start_supervisor(
                directory=directory,
                root=root_value,
                key=key,
                harness=normalized_harness,
                opaque_session=opaque_session,
                output=output_value,
                executable=executable_value,
                ckb=ckb_value,
                parent_pid=parent_pid,
                timeout=start_timeout,
            )
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "ready",
            "mode": "resident-stdio",
            "resident": True,
            "created": created,
            "lifecycle_key": key,
            "generation": lease.get("generation"),
            "supervisor_pid": lease.get("supervisor_pid"),
            "server_pid": lease.get("server_pid"),
            "protocol": lease.get("protocol"),
            "protocol_version": lease.get("protocol_version"),
            "parent_monitor": lease.get("parent_monitor"),
            "path_budget": lease.get("path_budget"),
            "fallback": {"active": False, "reason": None},
        }
    except Exception as exc:
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "fallback",
            "mode": "cli-fallback",
            "resident": False,
            "created": False,
            "lifecycle_key": key,
            "generation": None,
            "supervisor_pid": None,
            "server_pid": None,
            "protocol": None,
            "protocol_version": None,
            "parent_monitor": "pid" if parent_pid else "unavailable",
            "fallback": {"active": True, "reason": f"startup:{type(exc).__name__}:{str(exc)[:300]}"},
        }


def _activation_exists(output: Path, harness: str, session_id: str) -> bool:
    database = output.resolve() / "machine" / "automation.sqlite"
    if not database.is_file():
        return False
    try:
        connection = sqlite3.connect(f"file:{database.as_posix()}?mode=ro", uri=True)
        try:
            row = connection.execute(
                "SELECT 1 FROM skill_activations WHERE harness=? AND external_session_id=? AND skill_name=? LIMIT 1",
                (harness.strip().casefold(), session_id, "code-knowledge-builder"),
            ).fetchone()
            return row is not None
        finally:
            connection.close()
    except sqlite3.Error:
        return False


def _start_supervisor_locked(
    *,
    directory: Path,
    root: Path,
    key: str,
    harness: str,
    opaque_session: str,
    output: Path,
    executable: Path,
    ckb: Path,
    parent_pid: int | None,
    timeout: float,
) -> dict[str, Any]:
    _validate_lifecycle_path_budget(directory)
    directory.mkdir(parents=True, exist_ok=True)
    lock = _acquire_start_lock(directory, timeout)
    if lock is None:
        raise CkbError("session stdio single-flight start lock timeout")
    try:
        active = _active_lease(directory)
        if active:
            return active
        cleanup_sessions(root=root, only_key=key)
        previous = _read_json(_lease_path(directory)) or {}
        previous_pid = previous.get("supervisor_pid")
        previous_deadline = time.monotonic() + timeout
        while pid_exists(previous_pid) and time.monotonic() < previous_deadline:
            time.sleep(POLL_SECONDS)
        if pid_exists(previous_pid):
            raise CkbError("session stdio previous supervisor did not exit before restart")
        cleanup_sessions(root=root, only_key=key)
        generation = uuid.uuid4().hex[:16]
        log_root = directory / "logs"
        log_root.mkdir(parents=True, exist_ok=True)
        command = [
            str(executable),
            "-X",
            "utf8",
            str(ckb),
            "stdio-session",
            "_controller",
            "--root",
            str(root),
            "--key",
            key,
            "--harness",
            harness,
            "--session-digest",
            opaque_session,
            "--out",
            str(output),
            "--python",
            str(executable),
            "--ckb",
            str(ckb),
            "--generation",
            generation,
        ]
        if parent_pid:
            command.extend(["--parent-pid", str(parent_pid)])
        with (log_root / "supervisor.stdout.log").open("a", encoding="utf-8", newline="\n") as stdout_log, (
            log_root / "supervisor.stderr.log"
        ).open("a", encoding="utf-8", newline="\n") as stderr_log:
            process = subprocess.Popen(
                command,
                stdin=subprocess.DEVNULL,
                stdout=stdout_log,
                stderr=stderr_log,
                close_fds=True,
                **_supervisor_process_options(),
            )
        threading.Thread(
            target=_reap_supervisor,
            args=(process,),
            name=f"ckb-stdio-reap-{process.pid}",
            daemon=True,
        ).start()
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            lease = _read_json(_lease_path(directory))
            current_generation = lease.get("generation") if lease else None
            if (
                lease
                and current_generation == generation
                and lease.get("state") == "ready"
                and pid_exists(lease.get("server_pid"))
            ):
                return lease
            if lease and current_generation == generation and lease.get("state") in {"fallback", "closed"}:
                reason = (lease.get("fallback") or {}).get("reason") or lease.get("close_reason") or "startup-failed"
                raise CkbError(f"session stdio supervisor did not become ready: {reason}")
            if process.poll() is not None:
                raise CkbError(f"session stdio supervisor exited during start: exit={process.returncode}")
            time.sleep(POLL_SECONDS)
        raise CkbError("session stdio supervisor start timeout")
    finally:
        _release_start_lock(lock)


def _start_supervisor(**arguments: Any) -> dict[str, Any]:
    key = str(arguments["key"])
    timeout = float(arguments["timeout"])
    gate = _retain_start_gate(key)
    acquired = gate.lock.acquire(timeout=timeout)
    if not acquired:
        _release_start_gate(key, gate)
        raise CkbError("session stdio in-process single-flight timeout")
    try:
        return _start_supervisor_locked(**arguments)
    finally:
        gate.lock.release()
        _release_start_gate(key, gate)


def _fallback_command(executable: Path, ckb: Path, output: Path, request: dict[str, Any]) -> tuple[list[str] | None, str | None]:
    method = request.get("method")
    if method in {"retrieve", "brief"}:
        question = request.get("question")
        if not isinstance(question, str) or not question.strip():
            return None, "fallback-retrieve-requires-question"
        command = [str(executable), "-X", "utf8", str(ckb), str(method), "--out", str(output), question]
        command.extend(["--budget", str(request.get("budget", 1800 if method == "brief" else 1500))])
        command.extend(["--max-pages", str(request.get("max_pages", 8)), "--profile", str(request.get("profile", "fast"))])
        return command, None
    if method in {"entity", "source", "neighbors"}:
        selector = request.get("selector")
        if not isinstance(selector, str) or not selector.strip():
            return None, f"fallback-{method}-requires-selector"
        command = [str(executable), "-X", "utf8", str(ckb), str(method), "--out", str(output), selector]
        if method == "source":
            command.extend(["--context-lines", str(request.get("context_lines", 3))])
        elif method == "neighbors":
            command.extend(["--depth", str(request.get("depth", 1)), "--limit", str(request.get("limit", 50))])
            if request.get("relation"):
                command.extend(["--relation", str(request["relation"])])
        return command, None
    if method == "changes":
        command = [str(executable), "-X", "utf8", str(ckb), "changes", "--out", str(output), "--limit", str(request.get("limit", 20))]
        if request.get("kind"):
            command.extend(["--kind", str(request["kind"])])
        return command, None
    if method == "ping":
        return [], None
    return None, f"fallback-unsupported-method:{method}"


def _run_cli_fallback(
    *,
    executable: Path,
    ckb: Path,
    output: Path,
    request: dict[str, Any],
    reason: str,
    timeout: float,
) -> dict[str, Any]:
    command, error = _fallback_command(executable, ckb, output, request)
    if error:
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "failed",
            "mode": "cli-fallback",
            "resident": False,
            "fallback": {"active": True, "reason": reason},
            "error": {"type": "CkbError", "message": error, "exit_code": 2},
        }
    if command == []:
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "passed",
            "mode": "cli-fallback",
            "resident": False,
            "fallback": {"active": True, "reason": reason},
            "response": {
                "id": request.get("id"),
                "ok": True,
                "method": "ping",
                "result": {"status": "available-via-cli", "protocol": None, "protocol_version": None},
            },
        }
    environment = os.environ.copy()
    environment["CKB_STDIO_FALLBACK"] = "1"
    try:
        completed = subprocess.run(
            command,
            text=True,
            encoding="utf-8",
            errors="replace",
            stdin=subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            timeout=timeout,
            env=environment,
            **background_process_options(),
        )
    except subprocess.TimeoutExpired:
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "failed",
            "mode": "cli-fallback",
            "resident": False,
            "fallback": {"active": True, "reason": reason},
            "error": {"type": "TimeoutExpired", "message": "per-command CLI fallback timed out", "exit_code": 2},
        }
    try:
        value = json.loads(completed.stdout) if completed.stdout.strip() else None
    except json.JSONDecodeError:
        value = None
    ok = completed.returncode == 0 and isinstance(value, dict)
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "passed" if ok else "failed",
        "mode": "cli-fallback",
        "resident": False,
        "fallback": {"active": True, "reason": reason},
        "response": {
            "id": request.get("id"),
            "ok": ok,
            "method": request.get("method"),
            "result": value if ok else None,
            "error": None
            if ok
            else {
                "type": "CliFallbackError",
                "message": (completed.stderr or completed.stdout or "fallback failed").strip()[:1000],
                "exit_code": completed.returncode,
            },
        },
        "cli_exit_status": completed.returncode,
    }


def request_session(
    *,
    harness: str,
    session_id: str,
    output: Path,
    request: dict[str, Any],
    root: Path | None = None,
    executable: Path | None = None,
    ckb: Path | None = None,
    parent_pid: int | None = None,
    start_timeout: float = DEFAULT_START_TIMEOUT_SECONDS,
    request_timeout: float = DEFAULT_REQUEST_TIMEOUT_SECONDS,
    require_activation: bool = True,
) -> dict[str, Any]:
    output_value = output.expanduser().resolve()
    executable_value = (executable or Path(sys.executable)).expanduser().resolve()
    ckb_value = (ckb or Path(__file__).resolve().parents[1] / "ckb.py").expanduser().resolve()
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    if not (output_value / "machine" / "knowledge.sqlite").is_file():
        raise CkbError(f"session stdio requires machine/knowledge.sqlite: {output_value}")
    if not executable_value.is_file() or not ckb_value.is_file():
        raise CkbError("session stdio executable identity is missing")
    if not isinstance(request, dict):
        raise CkbError("session stdio request must be one JSON object")
    request = dict(request)
    if not isinstance(request.get("id"), (str, int)) or isinstance(request.get("id"), bool):
        request["id"] = "request-" + uuid.uuid4().hex[:16]
    normalized_harness = harness.strip().casefold()
    if require_activation and not _activation_exists(output_value, normalized_harness, session_id):
        return {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "status": "ignored",
            "mode": "not-started",
            "resident": False,
            "reason": "skill-not-applied-in-session",
            "fallback": {"active": False, "reason": None},
        }
    opaque_session = session_digest(session_id)
    key = lifecycle_key(normalized_harness, session_id, output_value, executable=executable_value, ckb=ckb_value)
    directory = _lifecycle_directory(root_value, key)
    root_value.mkdir(parents=True, exist_ok=True)
    try:
        lease = _active_lease(directory)
        if lease is None:
            lease = _start_supervisor(
                directory=directory,
                root=root_value,
                key=key,
                harness=normalized_harness,
                opaque_session=opaque_session,
                output=output_value,
                executable=executable_value,
                ckb=ckb_value,
                parent_pid=parent_pid,
                timeout=start_timeout,
            )
    except Exception as exc:
        return _run_cli_fallback(
            executable=executable_value,
            ckb=ckb_value,
            output=output_value,
            request=request,
            reason=f"startup:{type(exc).__name__}:{str(exc)[:300]}",
            timeout=request_timeout,
        )
    token = uuid.uuid4().hex[:16]
    request_path = directory / "requests" / f"{token}.json"
    response_path = directory / "responses" / f"{token}.json"
    json_write(
        request_path,
        {
            "schema_version": SESSION_STDIO_SCHEMA_VERSION,
            "request_token": token,
            "timeout_seconds": request_timeout,
            "created_at_utc": utc_now(),
            "request": request,
        },
    )
    deadline = time.monotonic() + request_timeout + 2.0
    try:
        while time.monotonic() < deadline:
            response = _read_json(response_path)
            if response is not None:
                if response.get("status") == "transport-failed":
                    reason = str((response.get("fallback") or {}).get("reason") or "transport-failed")
                    return _run_cli_fallback(
                        executable=executable_value,
                        ckb=ckb_value,
                        output=output_value,
                        request=request,
                        reason=reason,
                        timeout=request_timeout,
                    )
                return response
            current = _read_json(_lease_path(directory)) or lease
            if current.get("state") in {"fallback", "closed"} or not pid_exists(current.get("supervisor_pid")):
                reason = str((current.get("fallback") or {}).get("reason") or current.get("close_reason") or "supervisor-exited")
                return _run_cli_fallback(
                    executable=executable_value,
                    ckb=ckb_value,
                    output=output_value,
                    request=request,
                    reason=reason,
                    timeout=request_timeout,
                )
            time.sleep(POLL_SECONDS)
        return _run_cli_fallback(
            executable=executable_value,
            ckb=ckb_value,
            output=output_value,
            request=request,
            reason="client-response-timeout",
            timeout=request_timeout,
        )
    finally:
        request_path.unlink(missing_ok=True)
        response_path.unlink(missing_ok=True)


def environment_session() -> tuple[str, str, int | None] | None:
    """Resolve only documented or explicit Harness identity environment fields."""

    explicit_harness = str(os.environ.get("CKB_HARNESS") or "").strip().casefold()
    candidates = [
        ("codex", ("CODEX_SESSION_ID", "CODEX_THREAD_ID")),
        ("claude", ("CLAUDE_SESSION_ID",)),
        ("opencode", ("OPENCODE_SESSION_ID",)),
        ("dsh", ("DSH_SESSION_ID",)),
        ("gemini", ("GEMINI_SESSION_ID",)),
        ("copilot", ("COPILOT_SESSION_ID",)),
        ("cursor", ("CURSOR_SESSION_ID",)),
        ("generic", ("CKB_SESSION_ID",)),
    ]
    if explicit_harness:
        candidates.sort(key=lambda item: item[0] != explicit_harness)
    for harness, names in candidates:
        if explicit_harness and harness != explicit_harness:
            continue
        for name in ("CKB_SESSION_ID", *names):
            session = str(os.environ.get(name) or "").strip()
            if session:
                parent_text = str(os.environ.get("CKB_HARNESS_PID") or "").strip()
                parent_pid = int(parent_text) if parent_text.isdigit() and int(parent_text) > 0 else None
                return harness, session, parent_pid
    return None


def maybe_request_session(output: Path, request: dict[str, Any]) -> dict[str, Any] | None:
    """Route an ordinary CKB CLI query through an already activated session."""

    if os.environ.get("CKB_STDIO_FALLBACK") == "1":
        return None
    identity = environment_session()
    if identity is None:
        return None
    harness, session_id, parent_pid = identity
    if not _activation_exists(output.resolve(), harness, session_id):
        return None
    return request_session(
        harness=harness,
        session_id=session_id,
        output=output,
        request=request,
        parent_pid=parent_pid,
    )


def list_sessions(*, root: Path | None = None, active_only: bool = False) -> dict[str, Any]:
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    leases: list[dict[str, Any]] = []
    if root_value.is_dir():
        for path in sorted(root_value.glob("stdio-*/lease.json")):
            lease = _read_json(path)
            if not lease:
                continue
            active = lease.get("state") in {"starting", "ready", "closing"} and pid_exists(lease.get("supervisor_pid"))
            if active_only and not active:
                continue
            value = dict(lease)
            value["active"] = active
            leases.append(value)
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "passed",
        "root": str(root_value),
        "count": len(leases),
        "active": sum(1 for item in leases if item["active"]),
        "leases": leases,
    }


def close_session(
    *,
    harness: str,
    session_id: str,
    output: Path,
    root: Path | None = None,
    reason: str = "explicit-close",
    timeout: float = DEFAULT_CLOSE_TIMEOUT_SECONDS,
) -> dict[str, Any]:
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    opaque = session_digest(session_id)
    output_identity = _path_identity(output)
    matches: list[Path] = []
    if root_value.is_dir():
        for path in root_value.glob("stdio-*/lease.json"):
            lease = _read_json(path)
            if not lease:
                continue
            if (
                lease.get("harness") == harness.strip().casefold()
                and lease.get("session_digest") == opaque
                and _path_identity(lease.get("output", "")) == output_identity
            ):
                matches.append(path.parent)
    closed: list[dict[str, Any]] = []
    for directory in sorted(matches):
        lease = _read_json(_lease_path(directory)) or {}
        if lease.get("state") == "closed" and not pid_exists(lease.get("supervisor_pid")) and not pid_exists(lease.get("server_pid")):
            closed.append({"lifecycle_key": lease.get("lifecycle_key"), "status": "already-closed"})
            continue
        token = uuid.uuid4().hex[:12]
        json_write(directory / "control" / f"c-{token}.json", {"reason": reason[:120], "requested_at_utc": utc_now()})
        deadline = time.monotonic() + timeout
        while time.monotonic() < deadline:
            current = _read_json(_lease_path(directory)) or lease
            if (
                current.get("state") == "closed"
                and not pid_exists(current.get("server_pid"))
                and not pid_exists(current.get("supervisor_pid"))
            ):
                cleanup_sessions(root=root_value, only_key=str(current.get("lifecycle_key") or directory.name))
                current = _read_json(_lease_path(directory)) or current
                closed.append({"lifecycle_key": current.get("lifecycle_key"), "status": "closed", "lease": current})
                break
            if not pid_exists(current.get("supervisor_pid")):
                cleanup_sessions(root=root_value, only_key=str(current.get("lifecycle_key") or directory.name))
            time.sleep(POLL_SECONDS)
        else:
            current = _read_json(_lease_path(directory)) or lease
            _force_terminate_pid(int(current.get("supervisor_pid") or 0))
            _force_terminate_pid(int(current.get("server_pid") or 0))
            cleanup_sessions(root=root_value, only_key=str(current.get("lifecycle_key") or directory.name))
            closed.append({"lifecycle_key": current.get("lifecycle_key"), "status": "forced-cleanup"})
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "closed" if matches else "not-found",
        "reason": reason[:120],
        "matched": len(matches),
        "closed": closed,
    }


def cleanup_sessions(*, root: Path | None = None, only_key: str | None = None) -> dict[str, Any]:
    root_value = (root or default_session_stdio_root()).expanduser().resolve()
    cleaned: list[dict[str, Any]] = []
    if not root_value.is_dir():
        return {"schema_version": SESSION_STDIO_SCHEMA_VERSION, "status": "passed", "root": str(root_value), "cleaned": []}
    directories = [root_value / only_key] if only_key else sorted(path for path in root_value.glob("stdio-*") if path.is_dir())
    for directory in directories:
        lease = _read_json(_lease_path(directory))
        if not lease:
            continue
        supervisor_pid = lease.get("supervisor_pid")
        server_pid = lease.get("server_pid")
        parent_pid = lease.get("parent_pid")
        parent_dead = bool(parent_pid) and not pid_exists(parent_pid)
        supervisor_dead = bool(supervisor_pid) and not pid_exists(supervisor_pid)
        if lease.get("state") in {"starting", "ready", "closing"} and pid_exists(supervisor_pid) and parent_dead:
            json_write(directory / "control" / f"c-{uuid.uuid4().hex[:12]}.json", {"reason": "parent-death-cleanup"})
            cleaned.append({"lifecycle_key": lease.get("lifecycle_key"), "action": "close-requested"})
            continue
        if (supervisor_dead or not supervisor_pid) and lease.get("state") in {"fallback", "closed"}:
            deadline = time.monotonic() + 1.5
            while pid_exists(server_pid) and time.monotonic() < deadline:
                time.sleep(POLL_SECONDS)
            forced = False
            if pid_exists(server_pid):
                forced = _force_terminate_pid(int(server_pid))
            lease.update(
                {
                    "state": "closed",
                    "supervisor_pid": None,
                    "server_pid": None,
                    "closed_at_utc": lease.get("closed_at_utc") or utc_now(),
                    "close_reason": lease.get("close_reason") or "stale-cleanup",
                    "object_counts": _state_counts(lease=0, process=0, pending=0, readers=0, pipes=0),
                }
            )
            _write_lease(directory, lease)
            _clear_transient(directory)
            cleaned.append({"lifecycle_key": lease.get("lifecycle_key"), "action": "stale-cleaned", "forced_server": forced})
    return {"schema_version": SESSION_STDIO_SCHEMA_VERSION, "status": "passed", "root": str(root_value), "cleaned": cleaned}


def audit_sessions(*, root: Path | None = None) -> dict[str, Any]:
    listing = list_sessions(root=root)
    errors: list[str] = []
    totals = _state_counts(lease=0, process=0, pending=0, readers=0, pipes=0)
    for lease in listing["leases"]:
        serialized = json.dumps(lease, ensure_ascii=False, sort_keys=True).casefold()
        for field in _FORBIDDEN_STATE_KEYS:
            if f'"{field}"' in serialized:
                errors.append(f"forbidden-state-field:{field}:{lease.get('lifecycle_key')}")
        counts = lease.get("object_counts") or {}
        if lease.get("active"):
            for name in totals:
                totals[name] += int(counts.get(name, 0))
        elif lease.get("state") == "closed" and any(int(counts.get(name, 0)) for name in totals):
            errors.append(f"closed-object-count:{lease.get('lifecycle_key')}")
        if lease.get("state") == "ready" and not pid_exists(lease.get("server_pid")):
            errors.append(f"ready-server-missing:{lease.get('lifecycle_key')}")
    return {
        "schema_version": SESSION_STDIO_SCHEMA_VERSION,
        "status": "passed" if not errors else "failed",
        "root": listing["root"],
        "active": listing["active"],
        "object_counts": totals,
        "errors": errors,
    }

"""Machine-local clickable links for source files and Obsidian notes."""

from __future__ import annotations

import json
import os
from pathlib import Path, PurePosixPath
from typing import Any
from urllib.parse import quote, unquote, urlparse

from .common import CkbError, json_load, json_write, path_inside


SOURCE_EDITORS = {"vscode", "vscode-insiders", "file", "custom-template"}


class SourceLinkRenderer:
    """Validate one opener config and cache resolved repository paths.

    Retrieval may render several entities from the same file.  The public
    one-shot helpers below intentionally preserve their old behavior, while a
    long-lived renderer avoids repeating Windows ``resolve`` and
    ``_getfinalpathname`` work for every candidate.
    """

    def __init__(self, config: dict[str, Any], *, trusted_relative_paths: bool = False) -> None:
        self.config = validate_local_openers(config)
        root_value = self.config.get("working_repo_root")
        if self.config.get("source_view") == "baseline" and self.config.get("baseline_snapshot_root"):
            root_value = self.config["baseline_snapshot_root"]
        self.root = Path(str(root_value)).resolve()
        self.trusted_relative_paths = trusted_relative_paths
        self._absolute_paths: dict[str, Path] = {}

    @property
    def cache_size(self) -> int:
        return len(self._absolute_paths)

    def absolute_path(self, relative_path: str) -> Path:
        cached = self._absolute_paths.get(relative_path)
        if cached is not None:
            return cached
        relative = PurePosixPath(relative_path)
        if relative.is_absolute() or ".." in relative.parts:
            raise CkbError(f"source path is outside the repository: {relative_path}")
        joined = self.root.joinpath(*relative.parts)
        if self.trusted_relative_paths:
            # Machine retrieval only supplies paths from the audited source
            # manifest.  Absolute and parent components were rejected above,
            # so the lexical path is repository-bounded without another
            # filesystem canonicalization for every selected entity.
            path = joined
        else:
            path = joined.resolve()
            if not path_inside(path, self.root):
                raise CkbError(f"source path is outside the selected source root: {relative_path}")
        self._absolute_paths[relative_path] = path
        return path

    def uri(self, relative_path: str, line: int, column: int = 1) -> str:
        absolute = self.absolute_path(relative_path)
        encoded = quote(absolute.as_posix(), safe="/:")
        editor = self.config["source_editor"]
        if editor == "vscode":
            return f"vscode://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "vscode-insiders":
            return f"vscode-insiders://file/{encoded}:{int(line)}:{int(column)}"
        if editor == "file":
            prefix = "file:///" if os.name == "nt" else "file://"
            return prefix + encoded
        return str(self.config["custom_template"]).format(
            absolute_path=encoded,
            line=int(line),
            column=int(column),
        )

    def markdown_link(self, relative_path: str, start_line: int, end_line: int) -> str:
        uri = self.uri(relative_path, start_line, 1)
        label = f"打开源码：{relative_path} 第 {start_line} 行"
        suffix = f"  `{relative_path}:{start_line}-{end_line}`" if self.config.get("show_source_range", True) else ""
        return f"[{label}]({uri}){suffix}"


def default_openers(repository_root: Path, snapshot_root: Path | None = None) -> dict[str, Any]:
    return {
        "schema_version": 1,
        "source_editor": "vscode" if os.name == "nt" else "file",
        "working_repo_root": str(repository_root.resolve()),
        "baseline_snapshot_root": str(snapshot_root.resolve()) if snapshot_root else None,
        "source_view": "working",
        "show_source_range": True,
        "custom_template": None,
    }


def ensure_local_openers(output: Path, repository_root: Path, snapshot_root: Path | None = None) -> dict[str, Any]:
    path = output / "local-openers.json"
    if path.is_file():
        return validate_local_openers(json_load(path))
    value = default_openers(repository_root, snapshot_root)
    json_write(path, value)
    return value


def validate_local_openers(value: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(value, dict) or value.get("schema_version") != 1:
        raise CkbError("local-openers.json must use schema_version 1")
    editor = value.get("source_editor")
    if editor not in SOURCE_EDITORS:
        raise CkbError(f"unsupported source editor: {editor}")
    root = Path(str(value.get("working_repo_root", ""))).resolve()
    if not root.is_dir():
        raise CkbError(f"working repository root is missing: {root}")
    source_view = value.get("source_view", "working")
    if source_view not in {"working", "baseline"}:
        raise CkbError("source_view must be working or baseline")
    template = value.get("custom_template")
    if editor == "custom-template" and (
        not isinstance(template, str)
        or "{absolute_path}" not in template
        or "{line}" not in template
        or "{column}" not in template
    ):
        raise CkbError("custom source-link template requires {absolute_path}, {line}, and {column}")
    return {
        "schema_version": 1,
        "source_editor": editor,
        "working_repo_root": str(root),
        "baseline_snapshot_root": value.get("baseline_snapshot_root"),
        "source_view": source_view,
        "show_source_range": bool(value.get("show_source_range", True)),
        "custom_template": template,
    }


def update_local_openers(
    output: Path,
    repository_root: Path,
    *,
    editor: str = "vscode",
    source_view: str = "working",
    custom_template: str | None = None,
) -> dict[str, Any]:
    state_path = output / "state.json"
    if not state_path.is_file():
        raise CkbError(f"state.json does not exist: {state_path}")
    state = json_load(state_path)
    snapshot_root = (state.get("source_snapshot") or {}).get("root")
    value = default_openers(repository_root, Path(snapshot_root) if snapshot_root else None)
    value.update({"source_editor": editor, "source_view": source_view, "custom_template": custom_template})
    value = validate_local_openers(value)
    json_write(output / "local-openers.json", value)
    return value


def source_absolute_path(config: dict[str, Any], relative_path: str) -> Path:
    return SourceLinkRenderer(config).absolute_path(relative_path)


def source_uri(config: dict[str, Any], relative_path: str, line: int, column: int = 1) -> str:
    return SourceLinkRenderer(config).uri(relative_path, line, column)


def source_markdown_link(config: dict[str, Any], relative_path: str, start_line: int, end_line: int) -> str:
    return SourceLinkRenderer(config).markdown_link(relative_path, start_line, end_line)


def obsidian_open_uri(path: Path) -> str:
    return "obsidian://open?path=" + quote(str(path.resolve()), safe="")


def audit_source_uri(config: dict[str, Any], uri: str, relative_path: str, line: int) -> str | None:
    expected = source_uri(config, relative_path, line, 1)
    if uri != expected:
        return "source-uri-does-not-match-source-location"
    parsed = urlparse(uri)
    if parsed.scheme not in {"vscode", "vscode-insiders", "file", "cursor", "idea"}:
        return "source-uri-scheme-is-not-allowed"
    if parsed.scheme.startswith("vscode"):
        decoded = unquote(parsed.path)
        if f":{int(line)}:1" not in decoded:
            return "source-uri-line-is-missing"
    return None

"""Human-first navigation for durable Agent work records.

The index treats every analysis, change, pitfall, experiment, and session note
uniformly.  It never receives task-specific keywords or a hand-picked result
set; titles and one-line descriptions come from the existing reviewed notes.
"""

from __future__ import annotations

from pathlib import Path
import re
from typing import Any

from .common import CkbError, json_write
from .obsidian import NOTE_DIRECTORIES


WORK_RECORD_INDEX = "RECORDS.md"
WORK_RECORD_TAG = "#类型/导览"
LONG_HEX = re.compile(r"(?<![0-9A-Fa-f])[0-9A-Fa-f]{40,}(?![0-9A-Fa-f])")
CHINESE_RE = re.compile(r"[\u3400-\u9fff]")
SECTIONS = {
    "analysis": ("分析与决策", "查找已经形成的结论、方案比较、边界和后续判断。"),
    "changes": ("实现与变更", "查找已经修改的内容、修改原因、验证结果和交付范围。"),
    "experiments": ("实验与量化结果", "查找测试协议、性能数字、对照结果和适用限制。"),
    "pitfalls": ("踩坑与限制", "查找失败原因、环境差异、规避条件和复现入口。"),
    "sessions": ("会话与任务过程", "查找一次任务的目标、执行范围、结果和待继续事项。"),
}
SECTION_ORDER = ("analysis", "changes", "experiments", "pitfalls", "sessions")


def _contains_chinese(value: str) -> bool:
    return len(CHINESE_RE.findall(value)) >= 2


def _title(text: str, fallback: str) -> str:
    first = text.splitlines()[0] if text else ""
    return first.removeprefix("# ").strip() or fallback


def _plain_text(value: str) -> str:
    value = re.sub(r"!\[[^\]]*\]\([^)]*\)", "", value)
    value = re.sub(r"\[([^\]]+)\]\([^)]*\)", r"\1", value)
    value = re.sub(r"\[\[([^\]|#]+)(?:[|#][^\]]*)?\]\]", r"\1", value)
    value = re.sub(r"[`*>#]", "", value)
    return re.sub(r"\s+", " ", value).strip()


def _first_narrative(text: str) -> str:
    if "\n## 后续补充\n" in text:
        text = text.rsplit("\n## 后续补充\n", 1)[1]
    paragraphs: list[str] = []
    current: list[str] = []
    fenced = False
    for raw in text.splitlines()[1:]:
        line = raw.strip()
        if line.startswith("```"):
            fenced = not fenced
            continue
        if fenced:
            continue
        if not line:
            if current:
                paragraphs.append(" ".join(current))
                current = []
            continue
        if line.startswith(("#", "标签：", "- [[", "- [打开源码：", "|", "<!--")):
            continue
        if re.match(r"^[-*+]\s+", line) or re.match(r"^\d+[.)]\s+", line):
            continue
        current.append(line)
    if current:
        paragraphs.append(" ".join(current))
    for paragraph in paragraphs:
        value = _plain_text(paragraph)
        if not _contains_chinese(value):
            continue
        sentence = re.match(r"^(.{12,140}?[。！？；])(?:\s|$)", value)
        if sentence:
            return sentence.group(1)
        if len(value) <= 120:
            return value
        return value[:117].rstrip("，、；： ") + "……"
    return "本记录保存一次经过审阅的任务结论、实现变化或验证结果。"


def collect_work_records(root: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    seen_titles: set[str] = set()
    for directory in SECTION_ORDER:
        for path in sorted((root / directory).glob("*.md"), key=lambda item: item.name.casefold()):
            text = path.read_text(encoding="utf-8-sig")
            title = _title(text, path.stem)
            if title == "工作记录导览":
                raise CkbError("work record title conflicts with generated navigation: 工作记录导览")
            if title in seen_titles:
                raise CkbError(f"work record title must be unique: {title}")
            seen_titles.add(title)
            records.append(
                {
                    "title": title,
                    "directory": directory,
                    "file": path.relative_to(root).as_posix(),
                    "summary": _first_narrative(text),
                }
            )
    return records


def render_work_record_index(root: Path) -> tuple[str, list[dict[str, Any]]]:
    records = collect_work_records(root)
    lines = [
        "# 工作记录导览",
        "",
        f"标签：{WORK_RECORD_TAG}",
        "",
        "> 这里按任务目的汇总全部分析、变更、实验、踩坑和会话记录；每条记录都使用同一套确定性规则进入导览。",
        "",
        "## 先按任务选择",
        "",
        "- 需要理解已有结论或设计边界时，查看“分析与决策”。",
        "- 需要确认已经修改什么以及如何验证时，查看“实现与变更”。",
        "- 需要比较性能、召回、上下文或其他量化结果时，查看“实验与量化结果”。",
        "- 需要避开已知失败和环境差异时，查看“踩坑与限制”。",
        "- 需要恢复一次任务的上下文时，查看“会话与任务过程”。",
        "",
        "## 快速查找",
        "",
        "在 Obsidian 中先使用本页标题浏览；记录较多时，再用核心搜索输入任务中的两个或三个稳定关键词。需要定位源码时，转到首页的确定性检索入口。",
        "",
    ]
    from .research_gaps import gap_navigation_counts

    gap_counts = gap_navigation_counts(root)
    if gap_counts is not None:
        lines.extend(
            [
                "## 研究缺口与待补来源",
                "",
                "这里仅汇总待验证主张，不把缺口写成已确认事实，也不为每个缺口创建页面。使用 `gaps list` 查看机器记录和证据路径。",
                "",
                f"- 当前共 {gap_counts['total']} 项：待补证据 {gap_counts['open']} 项，暂缓 {gap_counts['deferred']} 项，已关闭 {gap_counts['resolved']} 项。",
                "",
            ]
        )
    by_directory = {directory: [] for directory in NOTE_DIRECTORIES}
    for record in records:
        by_directory[record["directory"]].append(record)
    for directory in SECTION_ORDER:
        heading, description = SECTIONS[directory]
        lines.extend([f"## {heading}", "", description, ""])
        items = by_directory[directory]
        if items:
            lines.extend(f"- [[{item['title']}]] — {item['summary']}" for item in items)
        else:
            lines.append("- 当前没有这一类记录。")
        lines.append("")
    return "\n".join(lines).rstrip() + "\n", records


def write_work_record_index(root: Path) -> dict[str, Any]:
    text, records = render_work_record_index(root)
    target = root / WORK_RECORD_INDEX
    target.write_text(text, encoding="utf-8", newline="\n")
    return {
        "status": "ready",
        "file": str(target.resolve()),
        "record_count": len(records),
        "sections": {directory: sum(1 for item in records if item["directory"] == directory) for directory in NOTE_DIRECTORIES},
    }


def refresh_work_record_index(output: Path) -> dict[str, Any]:
    markdown = output / "markdown"
    human = output / "human"
    if not markdown.is_dir() or not human.is_dir():
        raise CkbError("work record navigation requires human and markdown roots")
    text, records = render_work_record_index(markdown)
    for root in (markdown, human):
        (root / WORK_RECORD_INDEX).write_text(text, encoding="utf-8", newline="\n")
    audit = audit_work_record_index(output)
    json_write(output / "workspace-meta/work-record-index-audit.json", audit)
    if audit["status"] != "passed":
        raise CkbError(f"work record navigation audit failed: {audit['errors'][:10]}")
    return {"status": "passed", "record_count": len(records), "audit": audit}


def audit_work_record_root(root: Path) -> dict[str, Any]:
    errors: list[dict[str, Any]] = []
    target = root / WORK_RECORD_INDEX
    try:
        expected, records = render_work_record_index(root)
    except CkbError as exc:
        return {"status": "failed", "record_count": 0, "errors": [{"reason": "work-record-collection", "detail": str(exc)}]}
    if not target.is_file():
        errors.append({"reason": "work-record-index-missing"})
        actual = ""
    else:
        actual = target.read_text(encoding="utf-8-sig")
        if actual != expected:
            errors.append({"reason": "work-record-index-stale"})
        if actual.startswith("---\n"):
            errors.append({"reason": "work-record-index-frontmatter"})
        if actual.count(WORK_RECORD_TAG) != 1:
            errors.append({"reason": "work-record-index-tag", "count": actual.count(WORK_RECORD_TAG)})
        if LONG_HEX.search(actual):
            errors.append({"reason": "work-record-index-hash"})
    expected_titles = {item["title"] for item in records}
    linked_titles = set(re.findall(r"\[\[([^\]|#]+)", actual))
    if linked_titles != expected_titles:
        errors.append(
            {
                "reason": "work-record-index-link-set",
                "missing": sorted(expected_titles - linked_titles),
                "extra": sorted(linked_titles - expected_titles),
            }
        )
    missing_summaries = [item["title"] for item in records if not _contains_chinese(item["summary"])]
    if missing_summaries:
        errors.append({"reason": "work-record-index-summary-not-chinese", "titles": missing_summaries})
    return {
        "status": "passed" if not errors else "failed",
        "record_count": len(records),
        "linked_record_count": len(linked_titles & expected_titles),
        "section_counts": {directory: sum(1 for item in records if item["directory"] == directory) for directory in NOTE_DIRECTORIES},
        "errors": errors,
    }


def audit_work_record_index(output: Path) -> dict[str, Any]:
    markdown = output / "markdown"
    human = output / "human"
    result = audit_work_record_root(markdown)
    errors = list(result["errors"])
    left = markdown / WORK_RECORD_INDEX
    right = human / WORK_RECORD_INDEX
    if not left.is_file() or not right.is_file():
        errors.append({"reason": "work-record-index-mirror-missing"})
    elif left.read_bytes() != right.read_bytes():
        errors.append({"reason": "work-record-index-mirror-differs"})
    return {**result, "status": "passed" if not errors else "failed", "errors": errors}

#!/usr/bin/env python3
"""Create reproducible core and Obsidian-plugin archives with strict boundaries."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import sys
import zipfile
from pathlib import Path, PurePosixPath


VERSION = "5.4.0"
ROOT = Path(__file__).resolve().parents[1]
EXCLUDED_PARTS = {".git", "__pycache__", ".pytest_cache", ".mypy_cache"}
CORE_EXCLUDED_TOP_LEVEL = {"plugins"}
RUNTIME_PREFIX = ("assets", "runtime", "win-x64")
PLUGIN_ROOT = ROOT / "plugins" / "obsidian-code-knowledge-builder"
PLUGIN_FILES = ("main.js", "manifest.json", "styles.css", "LICENSE", "NOTICE.md", "build-record.json", "deploy.py")
CORE_REQUIRED_FILES = (
    "SKILL.md",
    "agents/openai.yaml",
    "scripts/ckb.py",
    "scripts/ckb_core/__init__.py",
    "references/workflow.md",
    "references/runtime.md",
    "toolchain.lock.json",
    "THIRD_PARTY_NOTICES.md",
)


def sha256(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()


def source_files(include_runtime: bool) -> list[Path]:
    result: list[Path] = []
    for current, directories, filenames in os.walk(ROOT):
        directory = Path(current)
        retained_directories: list[str] = []
        for name in sorted(directories):
            relative = (directory / name).relative_to(ROOT)
            if any(part in EXCLUDED_PARTS for part in relative.parts):
                continue
            if relative.parts and relative.parts[0] in CORE_EXCLUDED_TOP_LEVEL:
                continue
            if not include_runtime and relative.parts[:3] == RUNTIME_PREFIX:
                continue
            retained_directories.append(name)
        directories[:] = retained_directories
        for name in sorted(filenames):
            path = directory / name
            relative = path.relative_to(ROOT)
            if path.suffix in {".pyc", ".pyo"}:
                continue
            result.append(path)
    return sorted(result, key=lambda item: item.relative_to(ROOT).as_posix())


def core_capabilities(kind: str) -> dict[str, bool]:
    return {
        "source_scanning": True,
        "machine_sqlite_knowledge": True,
        "deterministic_retrieval": True,
        "human_markdown_obsidian_vault": True,
        "logseq_projection": True,
        "local_scope_and_segmented_build": True,
        "agent_review_and_audit": True,
        "automation_adapters": True,
        "session_scoped_stdio": True,
        "bundled_offline_runtime": kind == "full-win-x64",
        "obsidian_companion_plugin": False,
    }


def validate_core_boundary() -> None:
    lite = {path.relative_to(ROOT).as_posix() for path in source_files(False)}
    full = {path.relative_to(ROOT).as_posix() for path in source_files(True)}
    missing = sorted(set(CORE_REQUIRED_FILES) - lite)
    if missing:
        raise RuntimeError(f"lite core capability files are absent: {missing}")
    if any(path == "plugins" or path.startswith("plugins/") for path in lite | full):
        raise RuntimeError("core distributions must not contain plugins/")
    if not lite < full:
        raise RuntimeError("full-win-x64 must strictly extend lite")
    unexpected = sorted(
        path for path in full - lite
        if not path.startswith("assets/runtime/win-x64/")
    )
    if unexpected:
        raise RuntimeError(f"full-win-x64 adds non-runtime files: {unexpected}")


def validate_full_payload(lock: dict) -> Path:
    payload_lock = lock.get("payload")
    if not isinstance(payload_lock, dict):
        raise RuntimeError("full payload lock is pending")
    relative = payload_lock.get("path")
    if not isinstance(relative, str):
        raise RuntimeError("full payload path is absent from the lock")
    path = (ROOT / relative).resolve()
    if not path.is_file():
        raise RuntimeError(f"full payload is absent: {path}")
    if path.stat().st_size != int(payload_lock.get("size", -1)):
        raise RuntimeError("full payload size differs from toolchain.lock.json")
    actual_hash = sha256(path)
    if actual_hash != payload_lock.get("sha256"):
        raise RuntimeError("full payload SHA-256 differs from toolchain.lock.json")
    for required in payload_lock.get("required_members", []):
        with zipfile.ZipFile(path) as archive:
            if required not in archive.namelist():
                raise RuntimeError(f"full payload member is absent: {required}")
    return path


def build_core(kind: str, dist: Path) -> dict:
    lock = json.loads((ROOT / "toolchain.lock.json").read_text(encoding="utf-8"))
    validate_core_boundary()
    include_runtime = kind == "full-win-x64"
    if include_runtime:
        validate_full_payload(lock)
    files = source_files(include_runtime)
    manifest = {
        "schema_version": 1,
        "name": "code-knowledge-builder",
        "version": VERSION,
        "distribution": kind,
        "category": "core",
        "capabilities": core_capabilities(kind),
        "extends": "lite" if include_runtime else None,
        "forbidden_prefixes": ["plugins/"],
        "only_adds_prefix": "assets/runtime/win-x64/" if include_runtime else None,
        "toolchain_lock_id": lock["lock_id"],
        "files": [
            {
                "path": path.relative_to(ROOT).as_posix(),
                "size": path.stat().st_size,
                "sha256": sha256(path),
            }
            for path in files
        ],
    }
    dist.mkdir(parents=True, exist_ok=True)
    archive_path = dist / f"code-knowledge-builder-{kind}-{VERSION}.zip"
    if archive_path.exists():
        archive_path.unlink()
    prefix = PurePosixPath("code-knowledge-builder")
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in files:
            relative = PurePosixPath(path.relative_to(ROOT).as_posix())
            info = zipfile.ZipInfo(str(prefix / relative), date_time=(2026, 8, 26, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
        manifest_info = zipfile.ZipInfo(str(prefix / "distribution" / "release-manifest.json"), date_time=(2026, 8, 26, 0, 0, 0))
        manifest_info.compress_type = zipfile.ZIP_DEFLATED
        manifest_info.external_attr = 0o100644 << 16
        archive.writestr(manifest_info, json.dumps(manifest, ensure_ascii=False, indent=2).encode("utf-8") + b"\n")
    with zipfile.ZipFile(archive_path) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"ZIP CRC failed: {bad_member}")
        archived_manifest = json.loads(archive.read(str(prefix / "distribution" / "release-manifest.json")))
        if archived_manifest != manifest:
            raise RuntimeError("archived release manifest differs from the generated manifest")
    result = {
        "status": "passed",
        "distribution": kind,
        "archive": str(archive_path.resolve()),
        "size": archive_path.stat().st_size,
        "sha256": sha256(archive_path),
        "file_count": len(files),
    }
    (dist / f"code-knowledge-builder-{kind}-{VERSION}.manifest.json").write_text(
        json.dumps({**result, "content": manifest}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return result


def validate_plugin_dist() -> tuple[str, list[Path], dict]:
    dist = PLUGIN_ROOT / "dist"
    files = [dist / name for name in PLUGIN_FILES]
    missing = [path.name for path in files if not path.is_file() or path.stat().st_size == 0]
    if missing:
        raise RuntimeError(f"Obsidian plugin dist files are absent: {missing}")
    manifest = json.loads((dist / "manifest.json").read_text(encoding="utf-8"))
    version = manifest.get("version")
    if not isinstance(version, str) or not version.strip():
        raise RuntimeError("Obsidian plugin version is absent from manifest.json")
    build_record = json.loads((dist / "build-record.json").read_text(encoding="utf-8"))
    if build_record.get("status") != "passed":
        raise RuntimeError("Obsidian plugin build-record.json has not passed")
    recorded = {item["path"]: item for item in build_record.get("files", [])}
    for path in files:
        if path.name == "build-record.json":
            continue
        item = recorded.get(path.name)
        if not item:
            raise RuntimeError(f"Obsidian plugin build record is missing: {path.name}")
        if int(item.get("size", -1)) != path.stat().st_size or item.get("sha256") != sha256(path):
            raise RuntimeError(f"Obsidian plugin dist differs from build record: {path.name}")
    return version, files, build_record


def build_plugin(dist: Path) -> dict:
    version, files, build_record = validate_plugin_dist()
    manifest = {
        "schema_version": 1,
        "name": "code-knowledge-builder-obsidian",
        "version": version,
        "distribution": "obsidian-plugin",
        "category": "plugin",
        "requires": {
            "knowledge_base": "CKB output with machine/knowledge.sqlite",
            "core_package": "installed separately",
        },
        "bundled_core": False,
        "bundled_offline_runtime": False,
        "agent_deploy": {
            "standalone": "python deploy.py deploy --vault VAULT",
            "core": "ckb.py obsidian-plugin register/deploy/status/remove",
            "auto_deploy_after_registration": True,
        },
        "files": [
            {"path": path.name, "size": path.stat().st_size, "sha256": sha256(path)}
            for path in files
        ],
        "upstream_commit": build_record.get("claudian_commit"),
    }
    dist.mkdir(parents=True, exist_ok=True)
    archive_path = dist / f"code-knowledge-builder-obsidian-{version}.zip"
    if archive_path.exists():
        archive_path.unlink()
    with zipfile.ZipFile(archive_path, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=9) as archive:
        for path in files:
            info = zipfile.ZipInfo(path.name, date_time=(2026, 8, 30, 0, 0, 0))
            info.compress_type = zipfile.ZIP_DEFLATED
            info.external_attr = 0o100644 << 16
            archive.writestr(info, path.read_bytes(), compress_type=zipfile.ZIP_DEFLATED, compresslevel=9)
    with zipfile.ZipFile(archive_path) as archive:
        bad_member = archive.testzip()
        if bad_member:
            raise RuntimeError(f"Obsidian plugin ZIP CRC failed: {bad_member}")
        if archive.namelist() != list(PLUGIN_FILES):
            raise RuntimeError("Obsidian plugin ZIP member set or order differs")
        for path in files:
            if archive.read(path.name) != path.read_bytes():
                raise RuntimeError(f"Obsidian plugin ZIP bytes differ: {path.name}")
    result = {
        "status": "passed",
        "distribution": "obsidian-plugin",
        "archive": str(archive_path.resolve()),
        "size": archive_path.stat().st_size,
        "sha256": sha256(archive_path),
        "file_count": len(files),
    }
    (dist / f"code-knowledge-builder-obsidian-{version}.manifest.json").write_text(
        json.dumps({**result, "content": manifest}, ensure_ascii=False, indent=2) + "\n",
        encoding="utf-8",
        newline="\n",
    )
    return result


def build(kind: str, dist: Path) -> dict:
    if kind == "obsidian-plugin":
        return build_plugin(dist)
    return build_core(kind, dist)


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--kind",
        choices=("lite", "full-win-x64", "obsidian-plugin", "both", "all"),
        required=True,
    )
    parser.add_argument("--dist", type=Path, required=True)
    args = parser.parse_args()
    if args.kind == "both":
        kinds = ("lite", "full-win-x64")
    elif args.kind == "all":
        kinds = ("lite", "full-win-x64", "obsidian-plugin")
    else:
        kinds = (args.kind,)
    results = []
    try:
        for kind in kinds:
            results.append(build(kind, args.dist.resolve()))
    except RuntimeError as exc:
        print(json.dumps({"status": "pending", "reason": str(exc), "completed": results}, ensure_ascii=False, indent=2), file=sys.stderr)
        return 3
    print(json.dumps({"status": "passed", "results": results}, ensure_ascii=False, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
